export const STARTING_CASH = 15_000_000;

function freshState() {
  return {
    airlineName: '',
    logoId: 'horizon',
    logoColor: '#f5a623',
    customLogo: null,   // data URL of a user-uploaded logo (overrides logoId when set)
    hub: '',
    homeCountry: '',  // ISO country code of starting hub — hubs restricted to this country
    cash: STARTING_CASH,
    activeEvents:  [],    // currently active random events
    showDebrief:   false, // show weekly debrief modal
    pendingToasts: [],    // toast configs waiting to be shown
    week: 1,
    year: 1,
    fleet: [],         // { id, typeId, name, status, ageWeeks, config, ownershipType, fuelMod, rangeMod, maintMod, engineId, engineLabel, hasWingtips, hasWifi }
    pendingOrders: [], // { id, typeId, ownershipType, name, engineId, engineLabel, hasWingtips, hasWifi, fuelMod, rangeMod, maintMod, deliverAbsWeek, totalPrice }
    // NOTE: `foundedAbsWeek` is deliberately NOT seeded here. It is stamped by
  // worldService.joinWorld (multiplayer only, where the world clock and the
  // airline's own age diverge). Adding it to freshState would change the solo
  // state shape and the golden-master hash for no behavioural gain — weeklyTick
  // falls back to age 0 when it is absent, so seniority simply never applies.
  starterDeliveriesUsed: 0, // Headwinds MP only: first 2 aircraft ever taken deliver INSTANTLY (see ORDER_AIRCRAFT). Counts instant grants used; capped at 2. No effect in solo.
    routes: [],      // { id, origin, destination, stops:[origin,...,destination], aircraftId, weeklyFrequency, hub } — price lives in routePricing; stops carries intermediate tag-flight airports (single-leg routes have stops=[origin,destination])
    routePricing: {},// { [pairKey]: { economy, premiumEconomy, businessClass, firstClass } } — one price set per O&D pair
    routeCatering: {},// { [pairKey]: cateringLevel } — one catering level per O&D pair
    cargoRoutes: [], // { id, origin, destination, aircraftId, yieldPrice ($/tonne-km), weeklyFrequency, weeksOpen, hub, cargo:true }
    gates:             {},    // { [airportCode]: gateCount } — each gate = 50 slots/wk
    hubs:              {},    // { [airportCode]: { tier: 0|1|2|3, tierSince } } — 0 = focus city
    hubConstruction:   {},    // { [airportCode]: { targetTier, weeksLeft, capex } } — upgrades in progress
    hubThroughput:     {},    // { [airportCode]: number[] } — last 4 weeks connecting pax (T3 prereq)
    labor:             DEFAULT_LABOR_STATE,
    laborRelations:    DEFAULT_LABOR_RELATIONS,  // union unrest, strikes, contract negotiations
    maintenanceBudget: DEFAULT_MAINTENANCE_BUDGET,
    mroBases:          {},    // { [code]: { level, families[], openedWeek, buildWeeksLeft, partsPool } }
    lounges:           {},    // { [code]: { code, openedWeek, buildWeeksLeft, capex } } — built airport lounges
    loungePolicy:      null,  // { loyaltyAccess, allianceAccess } — null until the first lounge is built
    marketingBudget:   0,          // weekly BRAND marketing spend ($) — builds awareness (adstock), no instant boost
    targetedMarketing: {},         // { [airportCode]: weeklySpend } — tactical campaigns per airport
    campaignStrength:  {},         // { [airportCode]: 0-100 } — campaign stock, fast build/fast decay
    defaultCateringLevel: 'full',  // catering service level applied to newly-opened routes
    ancillaries: null,             // airline-wide à la carte policy — null = not yet configured (no effect)
    loyalty: {
      weeklyInvestment: 0,   // weekly $ spend on loyalty program (the set budget)
      effInvestment: 0,      // ramped "effective" budget — eases toward weeklyInvestment
      members: 0,            // current active members
      maturity: 0,           // 0–1 program maturity — grows over ~18 months funded, gates all effects
      pointsLiability: 0,    // $ value of outstanding unredeemed points (balance-sheet debt)
    },
    financialHistory: [],  // last 52 weeks of reports
    statsHistory: [],      // compact long-term KPI series (Statistics page) — see STATS_HISTORY_CAP
    lastReport: null,
    fuelPrice: { index: 1.0, history: [] },  // fuel price index + 52-week history
    marketIndex: MARKET_BASE_INDEX,          // world equity-market sentiment index
    hedgeContracts: [],                       // active fuel hedge contracts
    loans: [],             // active loans: { id, principal, interestRate, termWeeks, weeklyPayment, weeksRemaining, totalInterestPaid, takenWeek }
    phase: 'setup',  // 'setup' | 'playing' | 'bankrupt'
    competitors: sampleAndInitializeCompetitors(25),
    encroachments: {},           // { [pairKey]: entrant } — AI carriers contesting player routes
    allianceMembership:   null,  // { allianceId, joinedWeek, weeklyFee } | null
    codeshareAgreements:  [],    // [{ id, competitorId, competitorName, competitorTier, weeklyFee, signedWeek, weeksRemaining }]
    awareness: 5,                // 0–100: how well-known the airline is; gates demand
    satisfaction: null,          // 0–100 earned passenger satisfaction (null until first tick initializes it)
    reputationPenalty: 0,        // transient reputation hit (e.g. forced grounding); decays weekly
    missedLoanPayments:       0,   // total weeks where loans were due and cash went negative
    consecutiveNegativeWeeks: 0,   // weeks in a row ending with negative cash (resets on recovery)
    bankruptcyReason:         null, // 'missed_loans' | 'consecutive_negative' | null
    // Valuation v2: a fresh airline is worth BOOK_WEIGHT × net book (= cash).
    marketCap:         STARTING_CASH * 0.85,  // player market cap ($), updated each week
    // Unsmoothed fundamental value, tracked alongside the published cap. While the
    // airline is private this is what a listing would be priced off; it is never
    // shown as a share price. Starts equal to the cap — a fresh airline is exactly
    // its book value, so there is nothing to smooth yet.
    fairValue:         STARTING_CASH * 0.85,
    sharePrice:        STARTING_CASH * 0.85 / TOTAL_SHARES,  // player share price ($)
    // Share count, listing status and lifetime dividends. Share count is per
    // airline now (issuance/buybacks move it), so nothing may assume TOTAL_SHARES.
    equity:            emptyEquity(),
    // Shareholder Value Per Share — the leaderboard metric (see svpsOf).
    svps:              STARTING_CASH * 0.85 / TOTAL_SHARES,
    portfolio:         emptyPortfolio(),      // stock held in rival airlines
    objectives:        [],   // [{ id, completed, completedWeek, completedYear }]
    objectivesEnabled: true, // can be disabled at setup
    paxAllTime:        0,    // cumulative passengers flown (starter pax objectives)
    cabinTemplates:    [],   // saved cabin configs: { id, name, typeId, config: { firstClass, businessClass, premiumEconomy, economy, seatQuality, serviceQuality } }
  };
}

// ─────────────────────────────────────────────
// REDUCER
// ─────────────────────────────────────────────

// Use timestamp + random suffix so HMR (hot-reload resetting module scope)
// never produces an ID that collides with IDs already stored in localStorage.
function uid() {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
}

// Depreciated value of the OWNED fleet ($) — same NAV math as SELL_AIRCRAFT
// (purchase price × depreciation remaining, floored at 10%), without the 5%
// selling fee. Feeds the valuation model's net book value so buying aircraft
// converts cash into fleet value instead of vaporizing market cap (and selling
// the fleet no longer pumps it).
function fleetNAVOf(fleet, absWeek = null) {
  let total = 0;
  for (const a of fleet ?? []) {
    if (a.ownershipType !== 'owned' || a.status === 'retired') continue;
    const type      = getAircraftType(a.typeId);
    const remaining = valueRemaining(a.ageWeeks, type);
    const maintMod  = absWeek == null ? 1 : maintNavMultiplier(a, absWeek);
    total += Math.round((type?.purchasePrice ?? 0) * remaining * maintMod);
  }
  return total;
}

// ─────────────────────────────────────────────
// TAIL NUMBER GENERATION
// ─────────────────────────────────────────────

/** ICAO-style registration prefix by country code. */
const COUNTRY_REG_PREFIX = {
  US: 'N',  CA: 'C',  MX: 'XA', PA: 'HP', BR: 'PP', AR: 'LV',
  CL: 'CC', CO: 'HK', PE: 'OB', GB: 'G',  FR: 'F',  DE: 'D',
  NL: 'PH', ES: 'EC', IT: 'I',  CH: 'HB', AT: 'OE', BE: 'OO',
  PT: 'CS', NO: 'LN', SE: 'SE', FI: 'OH', DK: 'OY', IE: 'EI',
  PL: 'SP', GR: 'SX', TR: 'TC', AE: 'A6', QA: 'A7', SA: 'HZ',
  IL: '4X', ZA: 'ZS', EG: 'SU', KE: '5Y', NG: '5N', MA: 'CN',
  ET: 'ET', SG: '9V', HK: 'B',  MY: '9M', TH: 'HS', ID: 'PK',
  PH: 'RP', IN: 'VT', LK: '4R', JP: 'JA', KR: 'HL', CN: 'B',
  TW: 'B',  AU: 'VH', NZ: 'ZK',
};

/** Derive a 3-letter ICAO-style airline code from the airline name. */
function airlineCode(name) {
  const words = name.toUpperCase().replace(/[^A-Z\s]/g, '').split(/\s+/).filter(Boolean);
  if (words.length === 0) return 'AIR';
  if (words.length >= 3)  return words.slice(0, 3).map(w => w[0]).join('');
  if (words.length === 2)  return (words[0].slice(0, 2) + words[1][0]).slice(0, 3);
  return words[0].slice(0, 3).padEnd(3, 'X').slice(0, 3);
}

/**
 * Generate a unique aircraft registration based on hub country and airline name.
 * US format:  N + code + seq    → e.g. NDAL01
 * All others: prefix + - + code + seq → e.g. G-BAW01, VH-QAN01
 */
function generateTailNumber(hubCode, airlineName, usedTails = []) {
  const airport = getAirport(hubCode);
  const country = airport?.country ?? 'US';
  // A territory flies its sovereign's registry: San Juan is N-, Papeete is F-.
  // The bare `?? 'N'` fallback quietly made every non-US territory American.
  const prefix  = COUNTRY_REG_PREFIX[country]
    ?? COUNTRY_REG_PREFIX[sovereignCountry(country)]
    ?? 'N';
  const code    = airlineCode(airlineName);

  let n = 1;
  let tail;
  do {
    const seq = String(n).padStart(2, '0');
    tail = prefix === 'N'
      ? `N${code}${seq}`
      : `${prefix}-${code}${seq}`;
    n++;
  } while (usedTails.includes(tail) && n < 9999);

  return tail;
}

// Next auto-name number for an aircraft type: one past the highest "#N" suffix
// in use across the fleet and pending orders (never below the current count of
// that type). Count-based numbering reused numbers after a sale, producing two
// aircraft both named "#18".
function nextAircraftNumber(typeId, fleet = [], pendingOrders = []) {
  const ofType = [...fleet, ...pendingOrders].filter(x => x && x.typeId === typeId);
  let max = ofType.length;
  for (const item of ofType) {
    const m = /#(\d+)\s*$/.exec(item.name ?? '');
    if (m) max = Math.max(max, parseInt(m[1], 10));
  }
  return max + 1;
}

function reducer(state, action) {
  // World fare index (New World Restrictions). Set on every action, from state, so
  // every referencePrice()/cargoReferenceYield() call downstream — demand model,
  // competitor AI, encroachment, positioning, connecting fares — sees the same
  // ladder. The reducer is synchronous, so no two airlines can interleave here.
  // Era worlds (ERA_MODE_PLAN.md §3.3): the fare ladder is DERIVED from the
  // calendar, not stored — the era yield curve declines across the century, so
  // a seeded-once fareIndex would go stale within a decade. Composes
  // multiplicatively with any stored index (an era world that is also NWR).
  const _eraFi = eraFareIndex(calendarYear(state));
  setFareIndex(_eraFi != null ? _eraFi * (state?.fareIndex ?? 1) : (state?.fareIndex ?? 1));
  setEraStartYear(state?.startYear ?? null);
  setEraCostScale(eraCapitalScale(calendarYear(state)) ?? 1);
  setNwrYieldChoke(state?.newWorldRestrictions === true);
  switch (action.type) {

    case 'START_GAME': {
      // Startup capital: $15M of founders' EQUITY (see STARTING_CASH in freshState).
      // It is not a loan — there is no debt to service at launch, giving new airlines
      // breathing room to reach profitability. Players can borrow from the bank later.
      return {
        ...freshState(),
        airlineName: action.airlineName,
        logoId:      action.logoId    ?? 'horizon',
        logoColor:   action.logoColor ?? '#f5a623',
        customLogo:  action.customLogo ?? null,
        hub:         action.hub,
        homeCountry: getAirport(action.hub)?.country ?? '',
        gates:       { [action.hub]: 1 },
        hubs:        { [action.hub]: { tier: 1 } },
        loans:       [],
        phase:             'playing',
        // objectiveSet: 'multiplayer' → the Headwinds 10-objective starter board
        objectives:        action.enableObjectives !== false ? initialObjectives(action.objectiveSet) : [],
        objectivesEnabled: action.enableObjectives !== false,
      };
    }

    case 'LEASE_AIRCRAFT': {
      // Legacy instant-lease path (solo only — not in the Headwinds allow-list,
      // multiplayer leasing goes through ORDER_AIRCRAFT). Restricted worlds gate
      // it on the same rules so the old action can't be a back door.
      if (state.newWorldRestrictions && leaseDenial(state, action.typeId, 1)) return state;
      const type       = getAircraftType(action.typeId);
      const count      = nextAircraftNumber(action.typeId, state.fleet, state.pendingOrders);
      const name       = action.name ?? `${type?.name ?? action.typeId} #${count}`;
      const usedTails  = state.fleet.map(a => a.tailNumber).filter(Boolean);
      const tailNumber = generateTailNumber(state.hub, state.airlineName, usedTails);
      // Default lease term by aircraft category
      const LEASE_TERM_BY_CATEGORY = {
        'Turboprop':    52,   // 1 year
        'Regional Jet': 78,   // 1.5 years
        'Narrow Body':  104,  // 2 years
        'Wide Body':    156,  // 3 years
      };
      const leaseTermWeeks = action.leaseTermWeeks ?? (LEASE_TERM_BY_CATEGORY[type?.category] ?? 104);
      const newAircraft = {
        id:                 uid(),
        typeId:             action.typeId,
        name,
        tailNumber,
        status:             'idle',
        ageWeeks:           eraDeliveredAgeWeeks(type, calendarYear(state)),
        config:             defaultConfig(type?.seats ?? 100),
        ownershipType:      'lease',
        // Lock the rate at signing. Without this the tail carried no weeklyLease
        // at all, so every cost site fell through to `type.weeklyLease` — which
        // means a rebalance of the aircraft table silently repriced leases
        // ALREADY IN SERVICE. ORDER_AIRCRAFT deliveries were immune because they
        // do stamp the rate (a real lease fixes rent for its term; only a renewal
        // reprices). Same value as the fallback it replaces, so no existing save
        // changes behaviour on the week this ships.
        weeklyLease:        Math.round(type?.weeklyLease ?? 0),
        leaseTermWeeks,
        leaseRemainingWeeks: leaseTermWeeks,
        // This path charges no deposit, so the tail must say so explicitly. An
        // absent field would let the refund sites fall through to a rate-derived
        // default and hand back money that was never paid.
        leaseDeposit:        0,
      };
      return { ...state, fleet: [...state.fleet, newAircraft] };
    }

    case 'BUY_AIRCRAFT': {
      const type         = getAircraftType(action.typeId);
      if (!type) return state;
      // Instant single-unit buy — no bulk-order discount (that requires a
      // multi-unit ORDER_AIRCRAFT). Price at the single-frame tier.
      const price        = effectivePurchasePrice(type, 1);
      if (state.cash < price) return state;  // can't afford — ignore silently
      const count      = nextAircraftNumber(action.typeId, state.fleet, state.pendingOrders);
      const name       = action.name ?? `${type.name} #${count}`;
      const usedTails  = state.fleet.map(a => a.tailNumber).filter(Boolean);
      const tailNumber = generateTailNumber(state.hub, state.airlineName, usedTails);
      const newAircraft = {
        id:            uid(),
        typeId:        action.typeId,
        name,
        tailNumber,
        status:        'idle',
        ageWeeks:      eraDeliveredAgeWeeks(type, calendarYear(state)),
        config:        defaultConfig(type.seats),
        ownershipType: 'owned',
      };
      return {
        ...state,
        cash:  state.cash - price,
        fleet: [...state.fleet, newAircraft],
      };
    }

    // ─── Ordered aircraft with staggered delivery ────────────────────────────────
    // Lead times by category (weeks). The FIRST delivery of a type takes 2× the lead.
    // Subsequent deliveries in the same queue stack at +lead intervals after the last.
    //   Wide Body    → first 8w, then every 4w
    //   Narrow Body  → first 6w, then every 3w
    //   Regional Jet → first 4w, then every 2w
    //   Turboprop    → first 2w, then every 1w
    case 'ORDER_AIRCRAFT': {
      const type = getAircraftType(action.typeId);
      if (!type) return state;
      // Era gate: not yet in service = not orderable, buy or lease. The UI
      // shows the same denial; this is the authoritative check.
      if (orderDenial(state, action.typeId)) return state;

      const DELIVERY_LEAD = { 'Wide Body': 4, 'Narrow Body': 3, 'Regional Jet': 2, 'Turboprop': 1 };
      const lead     = DELIVERY_LEAD[type.category] ?? 2;
      const quantity = Math.max(1, Math.min(100, action.quantity ?? 1));

      const currentAbsWeek = absoluteWeek(state.year, state.week);

      // Resolve engine and wingtip modifiers (same for all aircraft in the batch)
      const engineOptions  = type.configOptions?.engines ?? [];
      const engineOpt      = engineOptions.find(e => e.id === action.engineId)
                          ?? engineOptions.find(e => e.default)
                          ?? engineOptions[0];
      const engineFuelMod  = engineOpt?.fuelMod  ?? 1.0;
      const enginePriceMod = engineOpt?.priceMod ?? 1.0;
      const engineMaintMod = engineOpt?.maintMod ?? 1.0;
      const wingtipDef     = type.configOptions?.wingtips;
      const wingtipFuelMod  = (action.hasWingtips && wingtipDef) ? (wingtipDef.fuelMod  ?? 1.0) : 1.0;
      const wingtipRangeMod = (action.hasWingtips && wingtipDef) ? (wingtipDef.rangeMod ?? 1.0) : 1.0;
      const wingtipCost     = (action.hasWingtips && wingtipDef) ? (wingtipDef.cost     ?? 0)   : 0;
      const fuelMod  = Math.round(engineFuelMod  * wingtipFuelMod  * 10000) / 10000;
      const rangeMod = Math.round(                  wingtipRangeMod * 10000) / 10000;
      const maintMod = Math.round(engineMaintMod                    * 10000) / 10000;

      // Build all N orders, updating the running pendingOrders list so each order
      // can see the previous ones when computing its staggered delivery week.
      //
      // Headwinds multiplayer: the first two aircraft a player EVER takes delivery
      // of are handed over INSTANTLY — straight into the fleet, skipping the queue —
      // so a new competitor can start flying immediately instead of idling for real
      // hours waiting on their first plane. The purchase price / lease deposit is
      // still charged in full; only the delivery wait is waived. Solo (Tailwinds)
      // is unaffected: state.multiplayer is undefined, so isMultiplayerWorld is
      // false and this behaves exactly as before.
      const isMultiplayerWorld   = state.multiplayer === true;
      const STARTER_DELIVERY_CAP = 2;
      // Lease term is now chosen by the player at order time (1–4 yr). Fall back to
      // the neutral 2-year reference term for legacy/crafted orders that omit it.
      const chosenLeaseTermWeeks = action.ownershipType === 'lease'
        ? (action.leaseTermWeeks ?? DEFAULT_LEASE_TERM_WEEKS)
        : undefined;
      const leaseRateMult        = leaseTermRateMultiplier(chosenLeaseTermWeeks);
      let starterUsed    = state.starterDeliveriesUsed ?? 0;
      let runningPending = [...(state.pendingOrders ?? [])];
      let runningFleet   = [...(state.fleet ?? [])];
      let cashBalance    = state.cash;
      // One-off seat-quality fitting fee (per aircraft) for seats above basic economy,
      // plus the per-seat install fee for any premium cabins (first/business/prem-eco).
      const seatFittingFee = (SEAT_QUALITY_FITTING_FEE[action.config?.seatQuality ?? 'basic'] ?? 0)
                           + cabinInstallFee(action.config);
      // Onboard connectivity, fitted on the production line. Cheaper than the
      // retrofit (see data/wifi.js), which is the entire reason this is a
      // decision at order time rather than something you get round to later.
      const wantsWifi    = action.hasWifi === true;
      const wifiFitCost  = wantsWifi ? wifiInstallCost() : 0;
      const newOrders       = [];
      const instantAircraft = [];
      const instantToasts   = [];
      // Set when the per-unit affordability check stops the order short, so the
      // return path can say how much was needed rather than silently trimming.
      let cashShortfallAt   = null;

      // ── Bulk-order discount (owned purchases only) ───────────────────────────
      // Discount scales with how many frames you commit to in THIS order and is
      // applied uniformly to every unit. Resolve the affordable quantity first so
      // requesting 100 can't snag the 20% tier on a few affordable frames: the
      // discount is non-decreasing in quantity, so dropping unaffordable frames
      // only lowers the tier (raising unit price) — converge downward.
      let orderQty  = quantity;
      let orderDisc = 0;

      // ── New World Restrictions: lessor stock + order book (leases only) ──────
      // Purchases are untouched — they are already capital-gated. A blocked type
      // stops the order dead; a full order book stops it dead; an order larger
      // than the remaining slots is CLAMPED to what fits, mirroring the
      // affordability trim below rather than silently dropping the whole thing.
      if (state.newWorldRestrictions && action.ownershipType === 'lease') {
        const denial = leaseDenial(state, action.typeId, orderQty);
        if (denial && denial.code !== 'order_book_partial') {
          return {
            ...state,
            pendingToasts: [
              ...(state.pendingToasts ?? []),
              { type: 'warning', icon: '🔒', title: 'Lease unavailable', message: denial.message },
            ],
          };
        }
        if (denial && denial.code === 'order_book_partial') {
          orderQty = denial.free;
          instantToasts.push({
            type: 'info', icon: '🔒',
            title: 'Lease order trimmed',
            message: `${denial.message} Ordered ${orderQty} instead of ${quantity}.`,
          });
        }
      }

      if (action.ownershipType === 'owned') {
        const unitCostAt = (disc) =>
          Math.round(Math.round(type.purchasePrice * (1 - disc)) * enginePriceMod)
          + wingtipCost + seatFittingFee + wifiFitCost;
        while (orderQty > 0) {
          orderDisc = orderDiscount(orderQty);
          if (cashBalance >= unitCostAt(orderDisc) * orderQty) break;
          orderQty--;
        }
        if (orderQty === 0) {
          // Was a silent `return state`. With the client's optimistic apply that
          // read as the game eating your order and your money — the single most
          // common "it stole my deposit" report. Name the number instead.
          const need = unitCostAt(orderDiscount(1));
          return {
            ...state,
            pendingToasts: [
              ...(state.pendingToasts ?? []),
              {
                type: 'warning', icon: '💸',
                title: 'Not enough cash',
                message: `A ${type.name} costs ${formatMoney(need)} to buy outright. You have ${formatMoney(cashBalance)}.`,
              },
            ],
          };
        }
      }

      for (let i = 0; i < orderQty; i++) {
        const pendingOfType = runningPending.filter(o => o.typeId === action.typeId);

        // First-ever order of this type takes 2× lead; subsequent stack at +lead
        const maxExistingDelivery = pendingOfType.length > 0
          ? Math.max(...pendingOfType.map(o => o.deliverAbsWeek))
          : null;
        const deliverAbsWeek = maxExistingDelivery === null
          ? currentAbsWeek + 2 * lead          // first in queue → 2× lead
          : maxExistingDelivery + lead;         // subsequent → +lead after last

        // Price: uniform bulk-order discount (orderDisc) applied to every frame in
        // this order. Leases carry no purchase price.
        const unitBasePrice  = action.ownershipType === 'owned'
          ? Math.round(type.purchasePrice * (1 - orderDisc))
          : 0;
        const unitTotalPrice = action.ownershipType === 'owned'
          ? Math.round(unitBasePrice * enginePriceMod) + wingtipCost
          : 0;

        // Lease: term-adjusted weekly rate (longer term = lower rate) + 12-week
        // upfront deposit due at order time.
        const baseWeeklyLease   = type.weeklyLease ?? 0;
        const engineLeaseAdj    = Math.round(baseWeeklyLease * (enginePriceMod - 1));
        const wingtipLeaseAdj   = (action.hasWingtips && wingtipDef) ? Math.round((wingtipDef.cost ?? 0) / 200) : 0;
        // A lessor recovers a factory-fitted connectivity package through the
        // rate, on the same amortisation the wingtip surcharge uses.
        const wifiLeaseAdj      = wantsWifi ? wifiLeaseSurcharge() : 0;
        const unitWeeklyLease   = Math.round((baseWeeklyLease + engineLeaseAdj + wingtipLeaseAdj + wifiLeaseAdj) * leaseRateMult);
        const leaseDeposit      = action.ownershipType === 'lease' ? unitWeeklyLease * LEASE_DEPOSIT_WEEKS : 0;

        // Stop if we can't afford this unit (buy price or lease deposit).
        // Record what we needed so the partial fill can explain itself below —
        // silently trimming an order is indistinguishable from losing it.
        // Owned aircraft pay the connectivity capex up front; leased ones have
        // already had it amortised into unitWeeklyLease above, so charging it
        // here as well would bill for the same antenna twice.
        const unitUpfrontCost = (action.ownershipType === 'owned' ? unitTotalPrice + wifiFitCost : leaseDeposit)
                              + seatFittingFee;
        if (cashBalance < unitUpfrontCost) { cashShortfallAt = unitUpfrontCost; break; }

        const serialNum = nextAircraftNumber(action.typeId, runningFleet, runningPending);
        const customName = (action.name ?? '').trim();
        const orderName = customName
          ? (quantity > 1 ? `${customName} #${i + 1}` : customName)
          : `${type.name} #${serialNum}`;
        const order = {
          id:            uid(),
          typeId:        action.typeId,
          ownershipType: action.ownershipType,
          name:          orderName,
          engineId:      engineOpt?.id    ?? null,
          engineLabel:   engineOpt?.label ?? null,
          hasWingtips:   action.hasWingtips ?? false,
          hasWifi:       wantsWifi,
          fuelMod,
          rangeMod,
          maintMod,
          config:        action.config ?? null,  // cabin layout chosen at order time
          deliverAbsWeek,
          totalPrice:    unitTotalPrice,
          leaseDeposit:  leaseDeposit,
          weeklyLease:   action.ownershipType === 'lease' ? unitWeeklyLease : 0,
          leaseTermWeeks: chosenLeaseTermWeeks,   // player-chosen term (undefined for owned)
          orderedWeek:   state.week,
          orderedYear:   state.year,
        };

        newOrders.push(order);
        cashBalance   -= unitUpfrontCost;

        // Starter Fleet perk (multiplayer only): the first two aircraft go straight
        // into the fleet now instead of onto the delivery queue. Mirrors the tick's
        // delivery construction (tail number, lease term, cabin config).
        if (isMultiplayerWorld && starterUsed < STARTER_DELIVERY_CAP) {
          const usedTails  = runningFleet.map(a => a.tailNumber).filter(Boolean);
          const tailNumber = generateTailNumber(state.hub, state.airlineName, usedTails);
          const deliveredLeaseTerm = order.ownershipType === 'lease'
            ? (order.leaseTermWeeks ?? DELIVERY_LEASE_TERMS[type.category] ?? DEFAULT_LEASE_TERM_WEEKS)
            : undefined;
          const aircraft = {
            id:            uid(),
            typeId:        order.typeId,
            name:          order.name,
            tailNumber,
            status:        'idle',
            ageWeeks:      eraDeliveredAgeWeeks(type, calendarYear(state)),
            config:        order.config ?? defaultConfig(type.seats ?? 100),
            ownershipType: order.ownershipType,
            weeklyLease:         order.weeklyLease ?? 0,
            leaseDeposit:        order.leaseDeposit ?? 0,
            leaseTermWeeks:      deliveredLeaseTerm,
            leaseRemainingWeeks: deliveredLeaseTerm,
            fuelMod:       order.fuelMod   ?? 1.0,
            rangeMod:      order.rangeMod  ?? 1.0,
            maintMod:      order.maintMod  ?? 1.0,
            engineId:      order.engineId  ?? null,
            engineLabel:   order.engineLabel ?? null,
            hasWingtips:   order.hasWingtips ?? false,
            hasWifi:       order.hasWifi ?? false,
          };
          runningFleet = [...runningFleet, aircraft];
          instantAircraft.push(aircraft);
          instantToasts.push({
            type:     'success',
            title:    `Aircraft Delivered: ${order.name}`,
            message:  `Your ${type.name} (${tailNumber}) arrived instantly thanks to the Starter Fleet perk (first ${STARTER_DELIVERY_CAP} aircraft). Later orders arrive on the normal delivery schedule.`,
            icon:     '✈',
            duration: 7000,
          });
          starterUsed += 1;
        } else {
          runningPending = [...runningPending, order];
        }
      }

      if (newOrders.length === 0 && instantAircraft.length === 0) {
        // Nothing could be funded. Previously a silent no-op.
        const need = cashShortfallAt;
        return {
          ...state,
          pendingToasts: [
            ...(state.pendingToasts ?? []),
            {
              type: 'warning', icon: '💸',
              title: 'Not enough cash',
              message: need != null
                ? `${action.ownershipType === 'lease'
                    ? `The deposit on a ${type.name} is ${formatMoney(need)}`
                    : `A ${type.name} costs ${formatMoney(need)}`}. You have ${formatMoney(cashBalance)}.`
                : `You can't fund a ${type.name} right now.`,
            },
          ],
        };
      }

      // Partial fill: some frames funded, the rest dropped for cash. Say so.
      const placedCount = newOrders.length + instantAircraft.length;
      if (cashShortfallAt != null && placedCount < orderQty) {
        instantToasts.push({
          type: 'info', icon: '💸',
          title: 'Order trimmed',
          message: `Ordered ${placedCount} of ${orderQty} — the next ${type.name} needed ${formatMoney(cashShortfallAt)} and you had ${formatMoney(cashBalance)}.`,
        });
      }

      return {
        ...state,
        cash:                  cashBalance,
        fleet:                 runningFleet,
        pendingOrders:         runningPending,
        starterDeliveriesUsed: starterUsed,
        pendingToasts:         instantToasts.length > 0
          ? [ ...(state.pendingToasts ?? []), ...instantToasts ]
          : state.pendingToasts,
      };
    }

    case 'CANCEL_ORDER': {
      const order = (state.pendingOrders ?? []).find(o => o.id === action.orderId);
      if (!order) return state;
      // Refund purchase price with a 5% cancellation fee. A lease order refunds
      // its security deposit in FULL: nothing was delivered, so there is nothing
      // for the lessor to secure. This used to refund 0 while the Fleet and
      // Marketplace screens both promised "Lease orders are free to cancel
      // before delivery" — ordering and cancelling a lease quietly destroyed
      // twelve weeks of rent.
      const refund = order.ownershipType === 'owned'
        ? Math.round(order.totalPrice * 0.95)
        : (order.leaseDeposit ?? 0);
      return {
        ...state,
        cash:          state.cash + refund,
        pendingOrders: (state.pendingOrders ?? []).filter(o => o.id !== action.orderId),
      };
    }

    case 'RENAME_ORDER': {
      const name = (action.name ?? '').trim();
      if (!name) return state;
      return {
        ...state,
        pendingOrders: (state.pendingOrders ?? []).map(o =>
          o.id === action.orderId ? { ...o, name } : o
        ),
      };
    }

    case 'RETIRE_AIRCRAFT': {
      const aircraft      = state.fleet.find(a => a.id === action.aircraftId);
      // Same reasoning as SELL_AIRCRAFT: retiring pledged metal would destroy
      // the security while the debt survives.
      if (isPledged(state, action.aircraftId)) {
        const why = 'This aircraft is pledged against an aircraft loan. Repay the loan to release it.';
        return {
          ...state,
          error: why,
          pendingToasts: [...(state.pendingToasts ?? []), {
            type: 'warning', title: '🔒 Pledged as collateral', message: why, duration: 9000,
          }],
        };
      }
      // Settle any live reserve covers involving this tail before removal.
      const settled       = settleCoversForRemoval(state, action.aircraftId);
      const updatedRoutes = settled.routes.filter(r => r.aircraftId !== action.aircraftId);
      const updatedCargo  = settled.cargoRoutes.filter(r => r.aircraftId !== action.aircraftId);
      const updatedFleet  = settled.fleet.filter(a => a.id !== action.aircraftId);
      const routeAircraftIds = new Set([...updatedRoutes, ...updatedCargo].map(r => r.aircraftId));
      const reStatusFleet = updatedFleet.map(a => ({
        ...a,
        // Preserve out-of-service statuses — a retirement elsewhere in the fleet
        // must not yank another tail out of its repair bay or heavy check.
        status: (a.status === 'retired' || isOutOfService(a))
          ? a.status
          : (routeAircraftIds.has(a.id) ? 'assigned' : 'idle'),
      }));
      // Early termination penalty: 50 % of remaining weekly lease × weeks left
      const type    = aircraft ? getAircraftType(aircraft.typeId) : null;
      const weeksLeft = aircraft?.leaseRemainingWeeks ?? 0;
      const leaseRate = aircraft?.weeklyLease ?? type?.weeklyLease ?? 0;
      const penalty = (aircraft?.ownershipType === 'lease' && weeksLeft > 0)
        ? Math.round(leaseRate * weeksLeft * 0.5)
        : 0;
      // The security deposit comes back when the aircraft does. It is a deposit,
      // not a fee: the termination penalty above is what makes an early return
      // expensive, and it is charged in full and unchanged. Tails that never
      // paid a deposit (the instant LEASE_AIRCRAFT path) carry 0 and get 0.
      const depositBack = aircraft?.ownershipType === 'lease'
        ? (aircraft.leaseDeposit ?? 0)
        : 0;
      return {
        ...state,
        cash:        state.cash - penalty + depositBack,
        fleet:       reStatusFleet,
        routes:      updatedRoutes,
        cargoRoutes: updatedCargo,
      };
    }

    case 'SCHEDULE_CHECK': {
      // action: { aircraftId, checkType: 'C'|'D', startNow?, startWeek? (absolute week) }
      const a = state.fleet.find(x => x.id === action.aircraftId);
      if (!a || a.status === 'retired' || isOutOfService(a)) return state;
      const mType = getAircraftType(a.typeId);
      if (!mType) return state;
      const ct     = action.checkType === 'D' ? 'D' : 'C';
      const curAbs = absoluteWeek(state.year, state.week);
      if (action.startNow) {
        // Best facility wins: hub discount or a certified jet base on this
        // aircraft's network, whichever is cheaper. They do not stack.
        const mfNow   = mroFactorsFor(resolveBaseFor(a, state.mroBases ?? {}, state.routes, state.cargoRoutes, curAbs));
        const hubFNow = aircraftHubMaintFactor(a.id, state.routes, state.cargoRoutes, state.hubs);
        const facNow  = Math.min(hubFNow, ct === 'D' ? mfNow.dCostMult : mfNow.cCostMult);
        const cost = checkCost(mType, ct, { maintMod: a.maintMod ?? 1, laborMult: laborEffects(state.labor).maintenanceCostMultiplier, hubFactor: facNow });
        if (state.cash < cost) return { ...state, error: 'Not enough cash to start this check.' };
        const savedNow = ct === 'D' ? mfNow.dWeeksSaved : mfNow.cWeeksSaved;
        const dur = Math.max(1, checkDurationWeeks(mType, ct) - savedNow);
        return {
          ...state,
          cash:  state.cash - cost,
          fleet: state.fleet.map(x => x.id === a.id ? startCheck(x, ct, dur) : x),
        };
      }
      const startWeek = Math.max(curAbs, Math.min(curAbs + MAX_SCHEDULE_AHEAD_WEEKS, Math.round(Number(action.startWeek) || curAbs)));
      return {
        ...state,
        fleet: state.fleet.map(x => x.id === a.id ? { ...x, scheduledCheck: { type: ct, startWeek } } : x),
      };
    }

    case 'CANCEL_SCHEDULED_CHECK': {
      return { ...state, fleet: state.fleet.map(x => x.id === action.aircraftId ? { ...x, scheduledCheck: null } : x) };
    }

    // ─── Jet bases (MRO network) ─────────────────────────────────────────────
    case 'BUILD_MRO_BASE': {
      // action: { code, level, families: [familyId] }
      const code  = action.code;
      const level = Math.max(1, Math.min(MRO_MAX_LEVEL, Math.round(Number(action.level) || 1)));
      const bases = state.mroBases ?? {};
      if (!code || bases[code]) return state;
      // Certifications are counted BEFORE the cash check, not clamped after it:
      // a base may be built certified for more families than its level includes,
      // at extraCertCapex each, so the count is an input to the quote.
      const fams = [...new Set((action.families ?? []).filter(Boolean))].slice(0, MRO_MAX_CERTS_PER_BASE);
      if (fams.length === 0) return { ...state, error: 'Certify at least one aircraft family.' };
      const check = canBuildBase(code, level, { bases, gates: state.gates ?? {}, cash: state.cash }, fams.length);
      if (!check.ok) return { ...state, error: check.reasons[0] };
      return {
        ...state,
        cash:     state.cash - check.capex,
        mroBases: { ...bases, [code]: makeBase(code, level, fams, absoluteWeek(state.year, state.week)) },
      };
    }

    case 'UPGRADE_MRO_BASE': {
      // Upgrades build IN PLACE — the existing level keeps working throughout.
      const code     = action.code;
      const bases    = state.mroBases ?? {};
      const existing = bases[code];
      if (!existing) return state;
      const level = Math.max(1, Math.min(MRO_MAX_LEVEL, Math.round(Number(action.level) || existing.level + 1)));
      const check = canBuildBase(code, level, { bases, gates: state.gates ?? {}, cash: state.cash });
      if (!check.ok) return { ...state, error: check.reasons[0] };
      const def = mroLevelDef(level);
      return {
        ...state,
        cash:     state.cash - check.capex,
        mroBases: { ...bases, [code]: { ...existing, upgradeTo: level, upgradeWeeksLeft: def.buildWeeks } },
      };
    }

    case 'ADD_BASE_CERTIFICATION': {
      // action: { code, familyId }
      const bases = state.mroBases ?? {};
      const base  = bases[action.code];
      const famId = action.familyId;
      if (!base || !famId) return state;
      const fams = base.families ?? [];
      if (fams.includes(famId)) return state;
      if (fams.length >= MRO_MAX_CERTS_PER_BASE) return { ...state, error: 'This base is certified for as many families as it can hold.' };
      const def = mroLevelDef(base.level);
      if (!def) return state;
      // Certifications beyond the level's included allowance cost capex + weekly opex.
      const capex = fams.length >= def.certsIncluded ? def.extraCertCapex : 0;
      if (state.cash < capex) return { ...state, error: 'Not enough cash to certify this family.' };
      return {
        ...state,
        cash:     state.cash - capex,
        mroBases: { ...bases, [action.code]: { ...base, families: [...fams, famId] } },
      };
    }

    case 'SET_BASE_PARTS_POOL': {
      const bases = state.mroBases ?? {};
      const base  = bases[action.code];
      if (!base) return state;
      return {
        ...state,
        mroBases: { ...bases, [action.code]: { ...base, partsPool: clampPartsPool(action.pool) } },
      };
    }

    case 'CLOSE_MRO_BASE': {
      const bases = state.mroBases ?? {};
      const base  = bases[action.code];
      if (!base) return state;
      const rest = { ...bases };
      delete rest[action.code];
      return { ...state, cash: state.cash + closeRefund(base), mroBases: rest };
    }

    // ─── Onboard connectivity (Wi-Fi retrofit) ───────────────────────────────
    // The only per-tail RETROFIT in the game besides a cabin reconfigure. Bulk
    // by design: nobody fits connectivity one aircraft at a time, and the Fleet
    // page applies it to a selection. Aircraft already fitted are silently
    // skipped rather than charged again, which is why the quote comes from
    // canRetrofitWifi() — the same function the UI shows the player, so the
    // number on the button is the number the reducer takes.
    case 'INSTALL_WIFI': {
      const ids = [...new Set((action.aircraftIds ?? (action.aircraftId ? [action.aircraftId] : [])).filter(Boolean))];
      if (ids.length === 0) return state;
      const targets = (state.fleet ?? []).filter(a => ids.includes(a.id));
      if (targets.length === 0) return state;

      const check = canRetrofitWifi(targets, state.cash);
      if (!check.ok) {
        return {
          ...state,
          pendingToasts: [
            ...(state.pendingToasts ?? []),
            {
              type: 'warning', icon: '📶',
              title: 'Wi-Fi not fitted',
              // Only quote a price when there is something to buy. When every
              // selected tail is already fitted the capex is 0, and "costs $0;
              // you have $X" reads as a bug rather than as "nothing to do".
              message: check.eligible.length === 0
                ? check.reasons[0]
                : `${check.reasons[0]} Fitting ${check.eligible.length} aircraft costs `
                  + `${formatMoney(check.capex)}; you have ${formatMoney(state.cash)}.`,
            },
          ],
        };
      }

      const fitted = new Set(check.eligible.map(a => a.id));
      return {
        ...state,
        cash:  state.cash - check.capex,
        fleet: state.fleet.map(a => (fitted.has(a.id) ? { ...a, hasWifi: true } : a)),
        pendingToasts: [
          ...(state.pendingToasts ?? []),
          {
            type: 'success', icon: '📶',
            title: fitted.size === 1 ? 'Wi-Fi fitted' : `Wi-Fi fitted to ${fitted.size} aircraft`,
            message: `${formatMoney(check.capex)} spent. Set what you charge for it on the `
                   + `Ancillaries tab — the fee is airline-wide.`,
            duration: 6000,
          },
        ],
      };
    }

    // ─── Airport lounges ─────────────────────────────────────────────────────
    case 'BUILD_LOUNGE': {
      const code    = action.code;
      const lounges = state.lounges ?? {};
      const check   = canBuildLounge(code, { lounges, gates: state.gates ?? {}, cash: state.cash });
      if (!check.ok) return { ...state, error: check.reasons[0] };
      return {
        ...state,
        cash:    state.cash - check.capex,
        lounges: { ...lounges, [code]: makeLounge(code, absoluteWeek(state.year, state.week)) },
        // Building your first lounge activates the access policy with both doors
        // shut — free access is a decision, not a default, and switching it on
        // costs servicing on every guest who walks in.
        loungePolicy: state.loungePolicy ?? normalizeLoungePolicy(null),
      };
    }

    case 'CLOSE_LOUNGE': {
      const lounges = state.lounges ?? {};
      const lounge  = lounges[action.code];
      if (!lounge) return state;
      const rest = { ...lounges };
      delete rest[action.code];
      return { ...state, cash: state.cash + loungeCloseRefund(lounge), lounges: rest };
    }

    case 'SET_LOUNGE_POLICY': {
      // Partial updates: the UI toggles one switch at a time.
      const current = normalizeLoungePolicy(state.loungePolicy);
      return {
        ...state,
        loungePolicy: normalizeLoungePolicy({
          loyaltyAccess:  action.loyaltyAccess  ?? current.loyaltyAccess,
          allianceAccess: action.allianceAccess ?? current.allianceAccess,
        }),
      };
    }

    case 'SET_RESERVE': {
      // Station an idle aircraft as a reserve at one of YOUR hubs/focus cities.
      // While stationed it pays a readiness premium + weekly parking fee (see
      // data/reserve.js) and the weekly tick auto-dispatches it onto the routes
      // of any same-type aircraft that goes out of service at that base.
      const a = state.fleet.find(x => x.id === action.aircraftId);
      const code = action.baseCode;
      if (!a || a.status !== 'idle' || isOutOfService(a)) return state;
      if ((state.hubs ?? {})[code] == null) return state;   // must be an own hub or focus city (tier 0 valid)
      return {
        ...state,
        fleet: state.fleet.map(x => x.id === a.id ? { ...x, reserveBase: code } : x),
      };
    }

    case 'CLEAR_RESERVE': {
      // Free. If the tail is mid-cover, the cover simply runs to its natural
      // end (route markers are the source of truth); it just won't be
      // dispatched again.
      return {
        ...state,
        fleet: state.fleet.map(x => x.id === action.aircraftId ? { ...x, reserveBase: null } : x),
      };
    }

    case 'SELL_AIRCRAFT': {
      // Sell an owned aircraft at NAV minus 5% selling & admin fee.
      const aircraft      = state.fleet.find(a => a.id === action.aircraftId);
      // Guard: only OWNED aircraft can be sold. Leased tails are returned via
      // RETIRE_AIRCRAFT — without this, a crafted SELL_AIRCRAFT on a leased plane
      // pays out its full purchase-price NAV for a jet you never bought.
      if (!aircraft || aircraft.ownershipType !== 'owned') return state;
      // A tail pledged against aircraft finance is the lender's security. Selling
      // it would hand the player the cash AND leave the loan standing against
      // nothing — the oldest trick in asset-backed lending.
      if (isPledged(state, action.aircraftId)) {
        const loan = loanSecuredOn(state, action.aircraftId);
        const why = `This aircraft is pledged against ${loan ? `a $${loan.principal.toLocaleString()} aircraft loan` : 'an aircraft loan'}. Repay the loan to release it.`;
        // A toast as well as state.error: solo has no consumer for `error`, and
        // this is a refusal a player can walk straight into from the Fleet screen.
        return {
          ...state,
          error: why,
          pendingToasts: [...(state.pendingToasts ?? []), {
            type: 'warning', title: '🔒 Pledged as collateral', message: why, duration: 9000,
          }],
        };
      }
      const type          = aircraft ? getAircraftType(aircraft.typeId) : null;
      const remaining     = valueRemaining(aircraft?.ageWeeks, type);
      const sellAbsWeek   = absoluteWeek(state.year, state.week);
      const nav           = Math.round((type?.purchasePrice ?? 0) * remaining * maintNavMultiplier(aircraft, sellAbsWeek));
      const fee           = Math.round(nav * 0.05);
      const proceeds      = nav - fee;
      const settled       = settleCoversForRemoval(state, action.aircraftId);
      const updatedRoutes = settled.routes.filter(r => r.aircraftId !== action.aircraftId);
      const updatedCargo  = settled.cargoRoutes.filter(r => r.aircraftId !== action.aircraftId);
      const updatedFleet  = settled.fleet.filter(a => a.id !== action.aircraftId);
      const routeAircraftIds = new Set([...updatedRoutes, ...updatedCargo].map(r => r.aircraftId));
      const reStatusFleet = updatedFleet.map(a => ({
        ...a,
        // Preserve out-of-service statuses (see RETIRE_AIRCRAFT note).
        status: (a.status === 'retired' || isOutOfService(a))
          ? a.status
          : (routeAircraftIds.has(a.id) ? 'assigned' : 'idle'),
      }));
      return {
        ...state,
        cash:        state.cash + proceeds,
        fleet:       reStatusFleet,
        routes:      updatedRoutes,
        cargoRoutes: updatedCargo,
        // Used-aircraft market (MP): expose the exact NAV this sale was valued at
        // so the server can list the tail in the world Used Market at NAV.
        // Harmless in solo; stripped before persistence in multiplayer.
        lastSale:    { aircraftId: action.aircraftId, nav },
      };
    }

    case 'BUY_USED_AIRCRAFT': {
      // Server-only: dispatched by the used-aircraft market buy route, never a
      // client (it is not on ALLOWED_PLAYER_ACTIONS). The buyer pays the price
      // now; the used tail arrives on the NEXT weekly tick (one week), carried on
      // the delivery queue like a factory order but flagged used so it
      // materializes from its snapshot (real age / cabin / engines / maintenance)
      // rather than as a fresh airframe.
      const snap  = action.snapshot;
      const price = Math.max(0, Math.round(Number(action.price) || 0));
      if (!snap || !snap.typeId || state.cash < price) return state;
      const usedType = getAircraftType(snap.typeId);
      const usedOrder = {
        id:             uid(),
        typeId:         snap.typeId,
        ownershipType:  'owned',
        name:           snap.name || (usedType && usedType.name) || snap.typeId,
        used:           true,
        usedSnapshot:   snap,
        deliverAbsWeek: absoluteWeek(state.year, state.week) + 1,
        totalPrice:     price,
        orderedWeek:    state.week,
        orderedYear:    state.year,
      };
      return { ...state, cash: state.cash - price, pendingOrders: [...(state.pendingOrders ?? []), usedOrder] };
    }

    case 'TRANSFER_ROUTES': {
      // Move EVERY route (pax + cargo) from one aircraft to an idle compatible
      // tail — routes keep their identity (weeksOpen ramp, pricing, season), so
      // swapping a new delivery in for a leased plane costs nothing but the click.
      const { fromAircraftId, toAircraftId } = action;
      if (!transferCompatibility(state, fromAircraftId, toAircraftId).ok) return state;
      const move = r => (r.aircraftId === fromAircraftId ? { ...r, aircraftId: toAircraftId } : r);
      return {
        ...state,
        routes:      state.routes.map(move),
        cargoRoutes: (state.cargoRoutes ?? []).map(move),
        fleet: state.fleet.map(a =>
          a.id === toAircraftId   ? withRouteStatus(a, 'assigned', { reserveBase: null }) :
          a.id === fromAircraftId ? withRouteStatus(a, 'idle')                            : a),
      };
    }

    case 'REASSIGN_ROUTE': {
      // Move ONE route to another tail. The route keeps its identity — id,
      // weeksOpen ramp, pricing, season, catering — so the pair does not
      // re-enter its maturity ramp and no launch cost is charged. That is the
      // whole point: closing and re-opening cost both.
      const { routeId, toAircraftId } = action;
      if (!reassignCompatibility(state, routeId, toAircraftId).ok) return state;
      const move = r => (r.id === routeId ? { ...r, aircraftId: toAircraftId } : r);
      const nextRoutes = (state.routes ?? []).map(move);
      const nextCargo  = (state.cargoRoutes ?? []).map(move);
      const stillFlying = (id) =>
        nextRoutes.some(r => r.aircraftId === id) || nextCargo.some(r => r.aircraftId === id);
      const fromId = ((state.routes ?? []).find(r => r.id === routeId)
                   ?? (state.cargoRoutes ?? []).find(r => r.id === routeId))?.aircraftId;
      return {
        ...state,
        routes:      nextRoutes,
        cargoRoutes: nextCargo,
        fleet: state.fleet.map(a => {
          // Taking a route puts a reserve back into normal service — it is no
          // longer standing by for anyone.
          if (a.id === toAircraftId) return withRouteStatus(a, 'assigned', { reserveBase: null });
          // The donor only goes idle if it gave up its last route.
          if (a.id === fromId) return withRouteStatus(a, stillFlying(a.id) ? 'assigned' : 'idle');
          return a;
        }),
      };
    }

    // ─── Bulk fleet actions ─────────────────────────────────────────────────
    // One decision, one write. The Fleet page used to loop a single action per
    // aircraft, which in multiplayer is N authoritative round-trips — slow, and
    // a failure partway leaves a partly-applied result underneath a dialog that
    // promised one outcome ("Sell 18 aircraft — proceeds $X"). CLOSE_ROUTES was
    // batched for exactly this reason; these follow it.
    //
    // Each FOLDS the single-aircraft case rather than reimplementing it, so
    // reserve settlement, lease penalties, cover teardown and status
    // recomputation cannot drift from the one-at-a-time path.
    case 'SELL_AIRCRAFT_BULK':
    case 'RETIRE_AIRCRAFT_BULK':
    case 'SCHEDULE_CHECKS':
    case 'BUY_OUT_LEASES':
    case 'EXTEND_LEASES': {
      const singleOf = {
        SELL_AIRCRAFT_BULK:   'SELL_AIRCRAFT',
        RETIRE_AIRCRAFT_BULK: 'RETIRE_AIRCRAFT',
        SCHEDULE_CHECKS:      'SCHEDULE_CHECK',
        BUY_OUT_LEASES:       'BUY_OUT_LEASE',
        EXTEND_LEASES:        'EXTEND_LEASE',
      };
      const single = singleOf[action.type];
      const ids = [...new Set(action.aircraftIds ?? [])].filter(Boolean);
      if (ids.length === 0) return state;
      let next = state;
      let applied = 0, skipped = 0;
      const sales = [];
      for (const aircraftId of ids) {
        const res = reducer(next, { ...action, type: single, aircraftId });
        // A refusal is either "nothing changed" or "an error was raised" (the
        // check case reports insufficient cash that way). Neither aborts the
        // batch: 7 of 12 checks starting before the money runs out is the
        // honest outcome, and the count comes back so the UI can say so. The
        // error itself is dropped — state.error is sticky, and one skipped
        // aircraft must not leave a permanent banner.
        if (res === next || (res.error && res.error !== next.error)) { skipped += 1; continue; }
        next = res;
        applied += 1;
        if (single === 'SELL_AIRCRAFT' && next.lastSale) sales.push(next.lastSale);
      }
      if (applied === 0) return state;
      return {
        ...next,
        // Every tail that actually sold. The used-market listing hook reads
        // `lastSale`, which alone would list only the final one of a batch.
        ...(sales.length ? { lastSales: sales, lastSale: sales[sales.length - 1] } : {}),
        bulkResult: { action: action.type, requested: ids.length, applied, skipped },
      };
    }

    case 'CONFIGURE_AIRCRAFT': {
      // action: { aircraftId, config, reconfCost }
      // A refit is shop work: the cabin is stripped and refitted with the tail
      // out of service, which is what the modal has always promised and what
      // nothing here used to do. Downtime is priced by refitWeeks() from the
      // size of the change and the airframe; the cost is re-derived here rather
      // than trusted from the payload, so a partial batch charges honestly.
      const target = state.fleet.find(a => a.id === action.aircraftId);
      if (!target || !action.config || typeof action.config !== 'object') return state;
      // Already in a heavy check or grounded by a failure: taking the hangar
      // slot for a cabin job would cancel the check (or wipe the AOG clock) and
      // hand the player back an airframe that never had the work done.
      if (isOutOfService(target)) {
        return { ...state, error: `${target.name ?? 'That aircraft'} is out of service — it cannot start a cabin refit until it is back.` };
      }
      const type    = getAircraftType(target.typeId);
      const current = target.config ?? defaultConfig(type?.seats ?? 100);
      const cost    = calcReconfCost(current, action.config);
      if (cost > state.cash) {
        return { ...state, error: `Not enough cash for that refit (${formatMoney(cost)}).` };
      }
      const weeks = refitWeeks(type, current, action.config);
      return {
        ...state,
        cash:  state.cash - cost,
        fleet: state.fleet.map(a => (
          a.id === action.aircraftId
            ? {
                ...a,
                config: action.config,
                ...(weeks > 0
                  ? { status: 'grounded', groundedWeeksLeft: weeks, groundedReason: 'refit' }
                  : {}),
              }
            : a
        )),
      };
    }

    case 'CONFIGURE_AIRCRAFT_BULK': {
      // action: { aircraftIds, config, reconfCost } — apply ONE target layout to
      // N tails and charge the summed cost ONCE, atomically. The Fleet page used
      // to loop CONFIGURE_AIRCRAFT, which in multiplayer fired N serialized server
      // writes and could leave a partially-reconfigured fleet if a mid-loop write
      // was refused after the modal had already closed.
      const ids = [...new Set(action.aircraftIds ?? [])].filter(Boolean);
      if (ids.length === 0 || !action.config || typeof action.config !== 'object') return state;
      // Price and time EACH tail: they may start from different layouts, and a
      // tail already in the shop is skipped rather than charged for work it
      // cannot have done. Charging the client's summed total would bill the
      // player for the ones that were skipped.
      let cost = 0;
      const refits = new Map();
      for (const id of ids) {
        const a = state.fleet.find(x => x.id === id);
        if (!a || isOutOfService(a)) continue;
        const type    = getAircraftType(a.typeId);
        const current = a.config ?? defaultConfig(type?.seats ?? 100);
        const c = calcReconfCost(current, action.config);
        cost += c;
        refits.set(id, refitWeeks(type, current, action.config));
      }
      if (refits.size === 0) return state;
      if (cost > state.cash) {
        return { ...state, error: `Not enough cash to refit ${refits.size} aircraft (${formatMoney(cost)}).` };
      }
      return {
        ...state,
        cash:  state.cash - cost,
        fleet: state.fleet.map(a => {
          if (!refits.has(a.id)) return a;
          const weeks = refits.get(a.id);
          return {
            ...a,
            config: action.config,
            ...(weeks > 0
              ? { status: 'grounded', groundedWeeksLeft: weeks, groundedReason: 'refit' }
              : {}),
          };
        }),
        bulkResult: { action: 'CONFIGURE_AIRCRAFT_BULK', requested: ids.length, applied: refits.size, skipped: ids.length - refits.size },
      };
    }

    case 'SAVE_CABIN_TEMPLATE': {
      // action: { name, typeId, config }
      const name = (action.name ?? '').trim();
      if (!name || !action.typeId || !action.config) return state;
      const templates = state.cabinTemplates ?? [];
      // Same name + same type overwrites the existing template
      const existing = templates.find(t => t.typeId === action.typeId && t.name.toLowerCase() === name.toLowerCase());
      const template = {
        id:     existing?.id ?? uid(),
        name,
        typeId: action.typeId,
        config: { ...action.config },
      };
      return {
        ...state,
        cabinTemplates: existing
          ? templates.map(t => (t.id === existing.id ? template : t))
          : [...templates, template],
      };
    }

    case 'DELETE_CABIN_TEMPLATE': {
      return {
        ...state,
        cabinTemplates: (state.cabinTemplates ?? []).filter(t => t.id !== action.templateId),
      };
    }

    case 'RENAME_AIRCRAFT': {
      return {
        ...state,
        fleet: state.fleet.map(a =>
          a.id === action.aircraftId ? { ...a, name: action.name } : a
        ),
      };
    }

    case 'SET_BRANDING': {
      // Update airline name / logo / accent colour mid-game. Only fields that
      // are provided are changed; customLogo may be explicitly set to null to
      // clear an uploaded image and fall back to the chosen preset.
      const next = { ...state };
      if (typeof action.airlineName === 'string' && action.airlineName.trim()) {
        next.airlineName = action.airlineName.trim();
      }
      if (typeof action.logoId === 'string')   next.logoId    = action.logoId;
      if (typeof action.logoColor === 'string') next.logoColor = action.logoColor;
      if ('customLogo' in action)              next.customLogo = action.customLogo ?? null;
      return next;
    }

    case 'ADD_ROUTE': {
      // ── Every rejection lives in addRouteBlockReason() ────────────────────────
      // Single source of truth for "can this route open?", shared with the planner
      // and with the decisions endpoint so a refused route always comes back with a
      // sentence instead of an unchanged state. Range, regulation, block-hours,
      // connectivity, gates, slots and cash are all checked there.
      if (addRouteBlockReason(state, action)) return state;

      const aircraft = state.fleet.find(a => a.id === action.aircraftId);
      const type     = getAircraftType(aircraft.typeId);
      // Frequency must be a positive integer.
      const weeklyFrequency = Math.max(1, Math.round(Number(action.weeklyFrequency) || 0));

      const dist = routeDistanceKm(action.origin, action.destination);

      // ── Seasonal window ──────────────────────────────────────────────────────
      // action.season = { months:[1..12] } | null (year-round).
      const newSeason = (Array.isArray(action.season?.months) && action.season.months.length > 0)
        ? { months: [...action.season.months].sort((a, b) => a - b) }
        : null;
      const newMonths = routeActiveMonths({ origin: action.origin, destination: action.destination, season: newSeason });
      const pairKey = [action.origin, action.destination].sort().join('-');

      // ── Consolidate: merge only when the same aircraft flies the same O&D with
      // the SAME season window (different windows must stay separate routes). ──
      const sameSeason = (r) => {
        const a = routeActiveMonths(r), b = newMonths;
        return a.length === b.length && a.every((m, i) => m === b[i]);
      };
      const existingRoute = state.routes.find(r =>
        r.aircraftId === action.aircraftId && sameSeason(r) &&
        ((r.origin === action.origin && r.destination === action.destination) ||
         (r.origin === action.destination && r.destination === action.origin))
      );
      if (existingRoute) {
        return {
          ...state,
          routes: state.routes.map(r =>
            r.id === existingRoute.id
              ? { ...r, weeklyFrequency: r.weeklyFrequency + weeklyFrequency }
              : r
          ),
        };
      }

      // ── Route launch cost (affordability already checked above) ────────────────
      const launchCost = routeLaunchCost(dist);

      const basePrice = Math.max(1, Math.round(Number(action.ticketPrice) || 0));
      // Full per-cabin fares set in the planner's fare editor. Each fare is
      // sanitized and clamped to its own class ceiling; missing cabins fall back
      // to the standard multipliers off the economy fare.
      const addRefP = mktReferencePrice(action.origin, action.destination);
      const requestedFares = defaultClassPrices(basePrice);
      if (action.classPrices && typeof action.classPrices === 'object') {
        for (const cls of Object.keys(requestedFares)) {
          const v = Number(action.classPrices[cls]);
          if (!isNaN(v) && v > 0) requestedFares[cls] = clampClassPrice(v, addRefP, cls);
        }
      }
      const newRoute = {
        id:              uid(),
        origin:          action.origin,
        destination:     action.destination,
        stops:           [action.origin, action.destination],
        aircraftId:      action.aircraftId,
        weeklyFrequency: weeklyFrequency,
        weeksOpen:       0,
        launchCost,
        hub:             state.hub,
        // Seasonal flights: null = year-round. seasonState tracks dormant↔active so
        // ADVANCE_WEEK only charges the reactivation fee when a season resumes.
        season:          newSeason,
        seasonState:     newSeason
          ? (isRouteActive({ season: newSeason }, weekToGameDate(state.week).monthIndex) ? 'active' : 'dormant')
          : 'active',
      };
      const updatedFleet = state.fleet.map(a =>
        a.id === action.aircraftId ? withRouteStatus(a, 'assigned', { reserveBase: null }) : a
      );
      // Price and catering are per-route (O&D pair). The first aircraft on a pair sets
      // them; additional aircraft inherit whatever the route already uses.
      const routePricing = state.routePricing ?? {};
      const newRoutePricing = routePricing[pairKey]
        ? routePricing
        : { ...routePricing, [pairKey]: requestedFares };
      const routeCatering = state.routeCatering ?? {};
      const newRouteCatering = routeCatering[pairKey]
        ? routeCatering
        : { ...routeCatering, [pairKey]: normalizeCateringLevel(action.cateringLevel ?? state.defaultCateringLevel) };
      return {
        ...state,
        cash:          state.cash - launchCost,
        routes:        [...state.routes, newRoute],
        routePricing:  newRoutePricing,
        routeCatering: newRouteCatering,
        fleet:         updatedFleet,
      };
    }

    // ─── Tag (multi-stop) passenger routes ──────────────────────────────────────
    // One aircraft flying A→B→C(→…). Mirrors ADD_ROUTE's guards but applies them
    // per LEG (range, restrictions, block hours) and per STOP (gates, slots), and
    // stores directional per-segment fares on the route (route.segmentPrices).
    case 'ADD_TAG_ROUTE': {
      const aircraft = state.fleet.find(a => a.id === action.aircraftId);
      const type     = aircraft ? getAircraftType(aircraft.typeId) : null;
      if (!aircraft || !type) return state;
      if (type.freighter) return state;   // freighters fly cargo routes only

      // Stop list: need 3–MAX_ROUTE_STOPS distinct airports (use ADD_ROUTE for a
      // single leg; the cap is the gameplay limit on intermediate stops).
      const stops = (Array.isArray(action.stops) ? action.stops : []).filter(Boolean);
      if (stops.length < 3 || stops.length > MAX_ROUTE_STOPS) return state;
      if (new Set(stops).size !== stops.length) return state;   // no repeated airports

      const proto = { stops, origin: stops[0], destination: stops[stops.length - 1] };
      const legs  = routeLegs(proto);
      for (const l of legs) {
        if (l.from === l.to) return state;
        if (!getAirport(l.from) || !getAirport(l.to)) return state;
      }

      const weeklyFrequency = Math.max(1, Math.round(Number(action.weeklyFrequency) || 0));

      // ── Range: the LONGEST leg must be reachable (a stop extends total reach) ──
      if (routeMaxLegKm(proto) > effectiveRangeKm(aircraft, type)) return state;

      // ── Regulatory restrictions: evaluate EACH leg independently ──
      const ownKey = routePairKey(proto.origin, proto.destination);
      const legPairFreq = (pk) => state.routes.reduce((s, r) =>
        routeLegs(r).some(rl => routePairKey(rl.from, rl.to) === pk) ? s + (r.weeklyFrequency ?? 0) : s, 0);
      for (const l of legs) {
        const pk = routePairKey(l.from, l.to);
        if (checkRouteRestrictions(l.from, l.to, routeDistanceKm(l.from, l.to),
              legPairFreq(pk) + weeklyFrequency, freighterBodyClass(type),
              { routes: state.routes, excludeKey: ownKey, aircraftType: type,
                marketFreq: peakMarketFreqOn(state.routes, pk, ALL_MONTHS) })) return state;
      }
      // ── And the market the rotation SELLS (see addTagRouteBlockReason) ──
      if (checkRouteRestrictions(proto.origin, proto.destination,
            routeDistanceKm(proto.origin, proto.destination),
            weeklyFrequency, freighterBodyClass(type),
            { routes: state.routes, excludeKey: ownKey, aircraftType: type,
              marketFreq: peakMarketFreqOn(state.routes, ownKey, ALL_MONTHS) + weeklyFrequency })) return state;

      // ── Block hours: cumulative across this aircraft's COMMITTED routes,
      //    legs-aware (and including any a reserve is covering for it) ──
      const existingBlockHrs = routesCommittedTo(action.aircraftId, state.routes, state.cargoRoutes ?? [])
        .reduce((s, r) => s + routeBlockHours(r, type, r.weeklyFrequency), 0);
      if (existingBlockHrs + routeBlockHours(proto, type, weeklyFrequency) > maxWeeklyBlockHoursFor(state)) return state;

      // ── Connectivity: a plane already flying can only extend from a served stop ──
      const aircraftRoutes = routesCommittedTo(action.aircraftId, state.routes, state.cargoRoutes ?? []);
      if (aircraftRoutes.length > 0) {
        const served = new Set(aircraftRoutes.flatMap(r => routeStops(r)));
        if (!stops.some(c => served.has(c))) return state;
      }

      // ── Gates + slots at EVERY stop (interior stops see two departures/cycle) ──
      const gates = state.gates ?? {};
      const tagAllOps = [...state.routes, ...(state.cargoRoutes ?? [])];
      const slotsAtStop = (code) => slotsUsedAt(tagAllOps, code);
      const addIncident = {};
      for (const l of legs) {
        addIncident[l.from] = (addIncident[l.from] ?? 0) + 1;
        addIncident[l.to]   = (addIncident[l.to]   ?? 0) + 1;
      }
      for (const code of stops) {
        if (!(gates[code] > 0) && poolGrantAt(state, code) <= 0) return state;   // no gate (or pool grant) at this stop
        if (slotsAtStop(code) + addIncident[code] * weeklyFrequency > slotCapAt(state, code)) return state;
      }

      // ── Launch cost (priced on total ground distance covered) ──
      const totalDist  = legs.reduce((s, l) => s + routeDistanceKm(l.from, l.to), 0);
      const launchCost = routeLaunchCost(totalDist);
      if (state.cash < launchCost) return state;

      // ── Default directional per-segment fares (player can edit via SET_SEGMENT_PRICE) ──
      const segmentPrices = {};
      for (const seg of routeSegments(proto)) {
        const key = routeSegmentKey(seg.from, seg.to);
        const eco = Math.max(1, Math.round(routeReferencePrice(seg.from, seg.to)));
        segmentPrices[key] = action.segmentPrices?.[key] ?? defaultClassPrices(eco);
      }

      const newRoute = {
        id:              uid(),
        origin:          stops[0],
        destination:     stops[stops.length - 1],
        stops:           [...stops],
        aircraftId:      action.aircraftId,
        weeklyFrequency,
        weeksOpen:       0,
        launchCost,
        hub:             state.hub,
        segmentPrices,
        cateringLevel:   normalizeCateringLevel(action.cateringLevel ?? state.defaultCateringLevel),
      };
      const updatedFleet = state.fleet.map(a =>
        a.id === action.aircraftId ? withRouteStatus(a, 'assigned', { reserveBase: null }) : a
      );
      return {
        ...state,
        cash:   state.cash - launchCost,
        routes: [...state.routes, newRoute],
        fleet:  updatedFleet,
      };
    }

    // Update one directional segment fare on a tag route.
    case 'SET_SEGMENT_PRICE': {
      const { routeId, from, to, classPrices } = action;
      const key = routeSegmentKey(from, to);
      return {
        ...state,
        routes: state.routes.map(r => {
          if (r.id !== routeId || !r.segmentPrices?.[key]) return r;
          const eco = Math.max(1, Math.round(Number(classPrices?.economy) || r.segmentPrices[key].economy || 1));
          return {
            ...r,
            segmentPrices: {
              ...r.segmentPrices,
              [key]: { ...r.segmentPrices[key], ...classPrices, economy: eco },
            },
          };
        }),
      };
    }

    case 'ADD_GATE': {
      const { airportCode } = action;
      const current = (state.gates ?? {})[airportCode] ?? 0;
      // Gate scarcity worlds (optional Headwinds setting): the airport is a
      // finite shared resource — capacity, ownership caps and lockouts are
      // checked against the server-injected market view. The server re-verifies
      // against its authoritative ledger; this check makes the optimistic /
      // solo-path apply agree with it. Non-scarcity games skip all of it.
      if (state.gateScarcityWorld && gateLeaseDenial(state, airportCode)) return state;
      return {
        ...state,
        gates: { ...(state.gates ?? {}), [airportCode]: current + 1 },
        // A fresh acquisition restarts the use-it-or-lose-it clock.
        ...(state.gateScarcityWorld
          ? { gateIdleWeeks: { ...(state.gateIdleWeeks ?? {}), [airportCode]: 0 } }
          : {}),
      };
    }

    // ── Gate scarcity: SERVER-DISPATCHED gate transfers ───────────────────────
    // These three are never in ALLOWED_PLAYER_ACTIONS — only the Headwinds
    // server dispatches them (auction resolution and the player-to-player gate
    // marketplace), exactly like alliance membership is server-governed. They
    // keep ALL cash math inside the engine so client, API and worker agree.

    case 'GATE_BID_LOST': {
      // Sealed-bid loser's notice. No state changes hands — this exists purely
      // so a losing bid is not silent. Before it, an auction you bid in and did
      // not win produced nothing at all: no toast, no feed item, and the auction
      // itself dropped out of the Airports tab the moment it resolved.
      const { airportCode, reason, detail, amount = 0, quantity = 1 } = action;
      const bid = `$${Math.round(amount).toLocaleString()}/gate × ${quantity}`;
      const message = ({
        OUTBID:
          `Your ${bid} bid at ${airportCode} was outbid — the gates went to higher bids.`,
        BELOW_RESERVE:
          `Your ${bid} bid at ${airportCode} was below the reserve price and did not qualify.`,
        INSUFFICIENT_CASH:
          `Your ${bid} bid at ${airportCode} won on price but was voided: bids are not escrowed and the cash has to be there when the auction resolves.`,
        OWNERSHIP_CAP:
          `Your ${bid} bid at ${airportCode} was voided by the single-airline ownership cap.`,
        ALLIANCE_CAP:
          `Your ${bid} bid at ${airportCode} was voided by the alliance ownership cap.`,
        LOCKED_OUT:
          `Your ${bid} bid at ${airportCode} was voided — you are locked out of that airport after a forfeited gate.`,
      })[reason] ?? `Your ${bid} bid at ${airportCode} did not win.`;
      return {
        ...state,
        pendingToasts: [...(state.pendingToasts ?? []), {
          type: reason === 'OUTBID' || reason === 'BELOW_RESERVE' ? 'info' : 'warning',
          title: '🔨 Auction lost',
          message: detail ? `${message} (${detail})` : message,
          duration: 11000,
        }],
      };
    }

    case 'GATE_AWARDED': {
      // Auction win: `gates` gates at airportCode for pricePerGate each.
      const { airportCode, gates: won = 1, pricePerGate = 0 } = action;
      const cost = won * pricePerGate;
      const current = (state.gates ?? {})[airportCode] ?? 0;
      return {
        ...state,
        cash:  state.cash - cost,
        gates: { ...(state.gates ?? {}), [airportCode]: current + won },
        gateIdleWeeks: { ...(state.gateIdleWeeks ?? {}), [airportCode]: 0 },
        pendingToasts: [...(state.pendingToasts ?? []), {
          type: 'success', title: '🔨 Auction won',
          message: `You won ${won} gate${won > 1 ? 's' : ''} at ${airportCode} for $${Math.round(cost).toLocaleString()}.`,
          duration: 9000,
        }],
      };
    }

    case 'GATE_PURCHASED': {
      // Bought one gate from another airline at their asking price.
      const { airportCode, price = 0 } = action;
      const current = (state.gates ?? {})[airportCode] ?? 0;
      return {
        ...state,
        cash:  state.cash - price,
        gates: { ...(state.gates ?? {}), [airportCode]: current + 1 },
        gateIdleWeeks: { ...(state.gateIdleWeeks ?? {}), [airportCode]: 0 },
        pendingToasts: [...(state.pendingToasts ?? []), {
          type: 'success', title: '🤝 Gate purchased',
          message: `You bought a gate at ${airportCode} for $${Math.round(price).toLocaleString()}.`,
          duration: 8000,
        }],
      };
    }

    case 'GATE_SOLD': {
      // Sold one gate to another airline; proceeds arrive in full.
      const { airportCode, proceeds = 0 } = action;
      const gates   = state.gates ?? {};
      const current = gates[airportCode] ?? 0;
      if (current === 0) return state;
      const newGates = { ...gates };
      if (current === 1) delete newGates[airportCode];
      else newGates[airportCode] = current - 1;
      return {
        ...state,
        cash:  state.cash + proceeds,
        gates: newGates,
        pendingToasts: [...(state.pendingToasts ?? []), {
          type: 'success', title: '💰 Gate sold',
          message: `Your gate at ${airportCode} sold for $${Math.round(proceeds).toLocaleString()}.`,
          duration: 8000,
        }],
      };
    }

    case 'REMOVE_GATE': {
      const { airportCode } = action;
      const gates   = state.gates ?? {};
      const current = gates[airportCode] ?? 0;
      if (current === 0) return state;
      // Prevent removal if existing routes need the capacity
      const usedSlots = state.routes
        .filter(r => r.origin === airportCode || r.destination === airportCode)
        .reduce((s, r) => s + r.weeklyFrequency, 0);
      if (usedSlots > (current - 1) * SLOTS_PER_GATE) return state;
      const newGates = { ...gates };
      if (current === 1) delete newGates[airportCode];
      else newGates[airportCode] = current - 1;
      return { ...state, gates: newGates };
    }

    case 'CLOSE_ROUTE': {
      const route = state.routes.find(r => r.id === action.routeId);
      const updatedRoutes = state.routes.filter(r => r.id !== action.routeId);
      const updatedFleet = state.fleet.map(a => {
        if (a.id !== route?.aircraftId) return a;
        // Only idle the aircraft if it has no remaining routes (passenger or cargo)
        const stillActive = updatedRoutes.some(r => r.aircraftId === a.id)
          || (state.cargoRoutes ?? []).some(r => r.aircraftId === a.id);
        return withRouteStatus(a, stillActive ? 'assigned' : 'idle');
      });
      return { ...state, routes: updatedRoutes, fleet: updatedFleet };
    }

    // Batched close: remove many routes in ONE reducer pass. Semantically identical
    // to dispatching CLOSE_ROUTE once per id, but a single action → a single state
    // result → (in multiplayer) a single server write. Looping CLOSE_ROUTE instead
    // fires N un-awaited decisions that all race the server's per-airline version
    // check, so all but one 409 ("your airline just changed") and most routes never
    // actually close. Accepts { routeIds: [...] } (or a lone { routeId }).
    case 'CLOSE_ROUTES': {
      const ids = new Set(action.routeIds ?? (action.routeId != null ? [action.routeId] : []));
      if (ids.size === 0) return state;
      const updatedRoutes = state.routes.filter(r => !ids.has(r.id));
      // Aircraft that had at least one of the closed routes — only these can change
      // status, and only to idle if they now have no remaining routes (pax or cargo).
      const touched = new Set(
        state.routes.filter(r => ids.has(r.id)).map(r => r.aircraftId)
      );
      const updatedFleet = state.fleet.map(a => {
        if (!touched.has(a.id)) return a;
        const stillActive = updatedRoutes.some(r => r.aircraftId === a.id)
          || (state.cargoRoutes ?? []).some(r => r.aircraftId === a.id);
        return withRouteStatus(a, stillActive ? 'assigned' : 'idle');
      });
      return { ...state, routes: updatedRoutes, fleet: updatedFleet };
    }

    // ─── Cargo routes ───────────────────────────────────────────────────────────
    // Freighters fly a parallel cargo network. Mirrors ADD_ROUTE's guards (range,
    // gates, slots, block-hours, regulatory, connectivity) but with no cabins,
    // pricing in $/tonne-km yield instead of ticket fares, and no catering.
    case 'ADD_CARGO_ROUTE': {
      const aircraft = state.fleet.find(a => a.id === action.aircraftId);
      const type     = aircraft ? getAircraftType(aircraft.typeId) : null;
      if (!aircraft || !type) return state;
      // Cargo routes require a dedicated freighter.
      if (!type.freighter) return state;
      if (action.origin === action.destination) return state;
      // The freight RATE is stated by the client, and `Math.max(0.01, Number(x))`
      // below lets NaN straight through: Math.max(0.01, NaN) is NaN, so a
      // yieldPrice of 'abc' put NaN on the lane, and the first tick multiplied
      // it into revenue and wiped the airline's cash to NaN. Refuse a
      // non-numeric rate outright — same treatment BUY_HEDGE gives a coverage
      // that is not a fraction. A rate that is merely out of range still CLAMPS
      // (below), and an OMITTED rate still defaults to the lane's reference
      // yield, so no legitimate request changes behaviour.
      // addCargoRouteBlockReason() carries the matching sentence, so the
      // multiplayer endpoint answers 400 rather than a silent no-op.
      if (action.yieldPrice != null && !Number.isFinite(Number(action.yieldPrice))) return state;

      const weeklyFrequency = Math.max(1, Math.round(Number(action.weeklyFrequency) || 0));
      const dist = routeDistanceKm(action.origin, action.destination);

      // Range (incl. engine/wingtip rangeMod)
      const effectiveRange = effectiveRangeKm(aircraft, type);
      if (dist > effectiveRange) return state;

      // Regulatory restrictions (perimeter rules etc. apply to freighters too).
      const pairKey = [action.origin, action.destination].sort().join('-');
      const allOps  = [...state.routes, ...(state.cargoRoutes ?? [])];
      const existingPairFreq = allOps
        .filter(r => [r.origin, r.destination].sort().join('-') === pairKey)
        .reduce((s, r) => s + r.weeklyFrequency, 0);
      if (checkRouteRestrictions(action.origin, action.destination, dist, existingPairFreq + weeklyFrequency,
            freighterBodyClass(type), { routes: allOps, excludeKey: pairKey, aircraftType: type })) return state;

      // Block-hours across everything committed to this freighter — its cargo
      // network, anything a reserve is covering for it, and (defensively) any
      // passenger route that ever reached it.
      const existingBlockHrs = routesCommittedTo(action.aircraftId, state.routes, state.cargoRoutes ?? [])
        .reduce((sum, r) => sum + routeBlockHours(r, type, r.weeklyFrequency), 0);
      if (existingBlockHrs + weeklyBlockHours(dist, weeklyFrequency, type) > maxWeeklyBlockHoursFor(state)) return state;

      // Network connectivity: a freighter already flying can only extend from airports it serves.
      const acCargoRoutes = routesCommittedTo(action.aircraftId, state.routes, state.cargoRoutes ?? []);
      if (acCargoRoutes.length > 0) {
        const served = new Set(acCargoRoutes.flatMap(r => [r.origin, r.destination]));
        if (!served.has(action.origin) && !served.has(action.destination)) return state;
      }

      // Gates required at both endpoints; slots counted across passenger + cargo ops.
      const gates = state.gates ?? {};
      if (!(gates[action.origin] > 0)      && poolGrantAt(state, action.origin) <= 0)      return state;
      if (!(gates[action.destination] > 0) && poolGrantAt(state, action.destination) <= 0) return state;
      if (slotsUsedAt(allOps, action.origin)      + weeklyFrequency > slotCapAt(state, action.origin))      return state;
      if (slotsUsedAt(allOps, action.destination) + weeklyFrequency > slotCapAt(state, action.destination)) return state;

      // Consolidate onto an existing identical cargo route for this freighter.
      const existingRoute = (state.cargoRoutes ?? []).find(r =>
        r.aircraftId === action.aircraftId &&
        ((r.origin === action.origin && r.destination === action.destination) ||
         (r.origin === action.destination && r.destination === action.origin))
      );
      if (existingRoute) {
        return {
          ...state,
          cargoRoutes: state.cargoRoutes.map(r =>
            r.id === existingRoute.id
              ? { ...r, weeklyFrequency: r.weeklyFrequency + weeklyFrequency }
              : r
          ),
        };
      }

      const launchCost = routeLaunchCost(dist);
      if (state.cash < launchCost) return state;

      // Non-finite rates were refused at the top of this case, so this can only
      // ever clamp a real number now.
      const refYield   = cargoReferenceYield(action.origin, action.destination);
      const yieldPrice = action.yieldPrice != null
        ? Math.max(0.01, Number(action.yieldPrice))
        : refYield;

      const newRoute = {
        id:              uid(),
        origin:          action.origin,
        destination:     action.destination,
        aircraftId:      action.aircraftId,
        yieldPrice,
        weeklyFrequency,
        weeksOpen:       0,
        launchCost,
        hub:             state.hub,
        cargo:           true,
      };
      const updatedFleet = state.fleet.map(a =>
        a.id === action.aircraftId ? withRouteStatus(a, 'assigned', { reserveBase: null }) : a
      );
      return {
        ...state,
        cash:        state.cash - launchCost,
        cargoRoutes: [...(state.cargoRoutes ?? []), newRoute],
        fleet:       updatedFleet,
      };
    }

    case 'CLOSE_CARGO_ROUTE': {
      const route = (state.cargoRoutes ?? []).find(r => r.id === action.routeId);
      const updatedCargo = (state.cargoRoutes ?? []).filter(r => r.id !== action.routeId);
      const updatedFleet = state.fleet.map(a => {
        if (a.id !== route?.aircraftId) return a;
        const stillActive = updatedCargo.some(r => r.aircraftId === a.id)
          || state.routes.some(r => r.aircraftId === a.id);
        return withRouteStatus(a, stillActive ? 'assigned' : 'idle');
      });
      return { ...state, cargoRoutes: updatedCargo, fleet: updatedFleet };
    }

    case 'UPDATE_CARGO_FREQUENCY': {
      const targetRoute = (state.cargoRoutes ?? []).find(r => r.id === action.routeId);
      if (!targetRoute) return state;
      const ac   = state.fleet.find(a => a.id === targetRoute.aircraftId);
      const type = ac ? getAircraftType(ac.typeId) : null;
      const newFreq = Math.max(1, Math.round(Number(action.weeklyFrequency) || 0));

      if (type && newFreq > targetRoute.weeklyFrequency) {
        // Guards only on INCREASES — reductions are always allowed, which is
        // what lets an over-cap grandfathered freighter (NWR dropped the cap
        // under its existing schedule) ratchet its hours DOWN without being
        // told it exceeds the very limit it is trying to move toward.
        const otherBlockHrs = routesCommittedTo(targetRoute.aircraftId, state.routes, state.cargoRoutes ?? [])
          .filter(r => r.id !== targetRoute.id)
          .reduce((s, r) => s + routeBlockHours(r, type, r.weeklyFrequency), 0);
        if (otherBlockHrs + routeBlockHours(targetRoute, type, newFreq) > maxWeeklyBlockHoursFor(state)) return state;

        const gates = state.gates ?? {};
        const allOps = [...state.routes, ...(state.cargoRoutes ?? [])];
        const otherOps = allOps.filter(r => r.id !== targetRoute.id);
        if (slotsUsedAt(otherOps, targetRoute.origin)      + newFreq > slotCapAt(state, targetRoute.origin))      return state;
        if (slotsUsedAt(otherOps, targetRoute.destination) + newFreq > slotCapAt(state, targetRoute.destination)) return state;
      }

      return {
        ...state,
        cargoRoutes: state.cargoRoutes.map(r =>
          r.id === action.routeId ? { ...r, weeklyFrequency: newFreq } : r
        ),
      };
    }

    case 'UPDATE_CARGO_YIELD': {
      // action: { routeId, yieldPrice } — $/tonne-km, clamped positive
      const yieldPrice = Math.max(0.01, Number(action.yieldPrice) || 0.01);
      return {
        ...state,
        cargoRoutes: (state.cargoRoutes ?? []).map(r =>
          r.id === action.routeId ? { ...r, yieldPrice } : r
        ),
      };
    }

    // ── Hub management ────────────────────────────────────────────────────────
    // Designations cost one-time capex and (except focus cities) take weeks to
    // build. Prerequisites are validated by hubUpgradeChecklist (shared with the
    // HubManagement UI, so the player sees exactly what's enforced here).

    case 'DESIGNATE_FOCUS_CITY': {
      const code = action.airportCode;
      if ((state.hubs ?? {})[code] || (state.hubConstruction ?? {})[code]) return state;
      const snap = {
        routes: state.routes, gates: state.gates ?? {}, homeCountry: state.homeCountry,
        hubs: state.hubs ?? {}, hubThroughput: state.hubThroughput ?? {},
        cash: state.cash, absWeek: absoluteWeek(state.year, state.week),
      };
      if (!hubUpgradeChecklist(snap, code, 0).ok) return state;
      // Focus cities are instant (no construction period)
      return {
        ...state,
        cash: state.cash - HUB_TIERS[0].capex,
        hubs: { ...(state.hubs ?? {}), [code]: { tier: 0, tierSince: snap.absWeek } },
      };
    }

    case 'DESIGNATE_HUB':
    case 'UPGRADE_HUB': {
      // One path for fresh hub designation (no entry → T1), focus-city promotion
      // (T0 → T1), and tier upgrades (T1 → T2 → T3). Capex is charged up front;
      // the tier activates when construction completes in ADVANCE_WEEK.
      const code    = action.airportCode;
      const hubs    = state.hubs ?? {};
      const current = hubs[code]?.tier;   // undefined | 0..3
      if ((state.hubConstruction ?? {})[code]) return state;        // already building
      if (current != null && current >= HUB_TIER_COUNT) return state; // maxed out
      const targetTier = current == null ? 1 : current + 1;
      const snap = {
        routes: state.routes, gates: state.gates ?? {}, homeCountry: state.homeCountry,
        hubs, hubThroughput: state.hubThroughput ?? {},
        cash: state.cash, absWeek: absoluteWeek(state.year, state.week),
      };
      if (!hubUpgradeChecklist(snap, code, targetTier).ok) return state;
      const tierDef = HUB_TIERS[targetTier];
      if ((tierDef.buildWeeks ?? 0) <= 0) {
        return {
          ...state,
          cash: state.cash - tierDef.capex,
          hubs: { ...hubs, [code]: { tier: targetTier, tierSince: snap.absWeek } },
        };
      }
      return {
        ...state,
        cash: state.cash - tierDef.capex,
        hubConstruction: {
          ...(state.hubConstruction ?? {}),
          [code]: { targetTier, weeksLeft: tierDef.buildWeeks, capex: tierDef.capex },
        },
      };
    }

    case 'DOWNGRADE_HUB': {
      const code = action.airportCode;
      // Cancelling an in-progress construction refunds 50% of capex.
      const construction = state.hubConstruction ?? {};
      if (construction[code]) {
        const { [code]: cancelled, ...rest } = construction;
        return {
          ...state,
          cash: state.cash + Math.round((cancelled.capex ?? 0) * 0.5),
          hubConstruction: rest,
        };
      }
      const hubs    = state.hubs ?? {};
      const hubInfo = hubs[code];
      if (!hubInfo) return state;
      if ((hubInfo.tier ?? 0) <= 0) {
        // Remove focus-city designation entirely. Reserves stationed there lose
        // their base (no hub, no stand) — live covers still run to natural end.
        const newHubs = { ...hubs };
        delete newHubs[code];
        return {
          ...state,
          hubs: newHubs,
          fleet: state.fleet.map(a => a.reserveBase === code ? { ...a, reserveBase: null } : a),
        };
      }
      return {
        ...state,
        hubs: { ...hubs, [code]: { tier: hubInfo.tier - 1, tierSince: absoluteWeek(state.year, state.week) } },
      };
    }

    // ──────────────────────────────────────────────────────────────────────────

    case 'UPDATE_TICKET_PRICE': {
      // Legacy: update economy price only, keep other classes in sync.
      // Clamp to a sane positive fare: a 0 or negative price feeds the elasticity
      // model Math.pow(ref/price, …), producing Infinity/NaN that poisons the
      // whole weekly tick (revenue → cashDelta → cash all become NaN).
      // Price belongs to the O&D pair. Resolve the pair from the route, then update
      // its economy fare in routePricing — every aircraft on the pair shares it.
      const tpTarget = state.routes.find(r => r.id === action.routeId);
      if (!tpTarget) return state;
      // Clamp to [1, cap]: the upper bound (PRICE_CAP_MULTIPLE × reference) stops
      // players exploiting the demand curve's flat tail with absurd fares.
      const tpRefP = mktReferencePrice(tpTarget.origin, tpTarget.destination);
      const price  = clampClassPrice(action.ticketPrice, tpRefP, 'economy');
      const tpKey  = routePairKey(tpTarget.origin, tpTarget.destination);
      const tpPrev = state.routePricing?.[tpKey] ?? defaultClassPrices(price);
      return {
        ...state,
        routePricing: { ...state.routePricing, [tpKey]: { ...tpPrev, economy: price } },
      };
    }

    // Set individual class prices without touching others
    case 'UPDATE_CLASS_PRICES': {
      // action: { routeId, updates: { economy?, premiumEconomy?, businessClass?, firstClass? } }
      const cpTarget = state.routes.find(r => r.id === action.routeId);
      if (!cpTarget) return state;
      // Sanitize each provided fare to a positive integer and clamp to its
      // per-class ceiling (PRICE_CAP_MULTIPLE × that class's reference fare).
      const cpRefP = mktReferencePrice(cpTarget.origin, cpTarget.destination);
      const cleanUpdates = {};
      for (const [k, v] of Object.entries(action.updates ?? {})) {
        cleanUpdates[k] = clampClassPrice(v, cpRefP, k);
      }
      // Per-O&D-pair pricing: merge the class updates into the pair's price set.
      const cpKey  = routePairKey(cpTarget.origin, cpTarget.destination);
      const cpPrev = state.routePricing?.[cpKey]
        ?? defaultClassPrices(cleanUpdates.economy ?? mktReferencePrice(cpTarget.origin, cpTarget.destination));
      return {
        ...state,
        routePricing: { ...state.routePricing, [cpKey]: { ...cpPrev, ...cleanUpdates } },
      };
    }

    // Bulk pricing: shift fares by a percentage across many routes at once.
    // action: { routeIds: [...], pct: { economy?, premiumEconomy?, businessClass?, firstClass? } }
    // Each pct value is a percentage delta (e.g. +10 raises that class's fare 10%,
    // -5 cuts it 5%). Pricing belongs to the O&D pair, so we resolve the affected
    // pairs from the route ids and adjust each pair's price set once (covering every
    // aircraft on it). New fares are clamped to each class's [1, cap] range.
    case 'BULK_ADJUST_PRICING': {
      const bulkIds = new Set(action.routeIds ?? []);
      const pct = action.pct ?? {};
      // Only keep classes with a real, non-zero numeric adjustment.
      const activePct = {};
      for (const [k, v] of Object.entries(pct)) {
        const n = Number(v);
        if (!isNaN(n) && n !== 0) activePct[k] = n;
      }
      if (bulkIds.size === 0 || Object.keys(activePct).length === 0) return state;

      // Resolve each affected O&D pair to a representative route (for origin/dest
      // so we can compute the per-class ceiling) — dedupes multi-aircraft pairs.
      const pairs = new Map(); // key -> { origin, destination }
      for (const r of state.routes) {
        if (!bulkIds.has(r.id)) continue;
        const key = routePairKey(r.origin, r.destination);
        if (!pairs.has(key)) pairs.set(key, { origin: r.origin, destination: r.destination });
      }
      if (pairs.size === 0) return state;

      const nextPricing = { ...(state.routePricing ?? {}) };
      for (const [key, { origin, destination }] of pairs) {
        const refP = mktReferencePrice(origin, destination);
        const prev = nextPricing[key] ?? defaultClassPrices(refP);
        const updated = { ...prev };
        for (const [cls, delta] of Object.entries(activePct)) {
          const base = prev[cls] ?? defaultClassPrices(refP)[cls];
          if (base == null) continue;
          const raw = Math.round(base * (1 + delta / 100));
          updated[cls] = clampClassPrice(raw, refP, cls);
        }
        nextPricing[key] = updated;
      }
      return { ...state, routePricing: nextPricing };
    }

    case 'UPDATE_FREQUENCY': {
      const targetRoute = state.routes.find(r => r.id === action.routeId);
      if (!targetRoute) return state;
      const newFreq = Math.max(1, Math.round(Number(action.weeklyFrequency) || 0));
      if (newFreq === targetRoute.weeklyFrequency) return state;
      // Reductions always allowed; increases guarded by the shared predicate
      // (per-month peak block-hours + gate slots + regulatory) — the same logic
      // the Route UI uses to enable/disable and explain the stepper.
      if (frequencyChangeBlockReason(state, action.routeId, newFreq)) return state;
      return {
        ...state,
        routes: state.routes.map(r =>
          r.id === action.routeId ? { ...r, weeklyFrequency: newFreq } : r
        ),
      };
    }

    // Set the catering service level on one route, or several at once
    // (e.g. all routes on a city-pair). action: { routeId? , routeIds?, level }
    case 'SET_ROUTE_CATERING': {
      const level = normalizeCateringLevel(action.level);
      const ids = new Set(action.routeIds ?? (action.routeId ? [action.routeId] : []));
      if (ids.size === 0) return state;
      // Catering belongs to the O&D pair. Resolve the affected pairs from the routes,
      // then set the level once per pair (covers every aircraft on it).
      const keys = new Set(
        state.routes.filter(r => ids.has(r.id)).map(r => routePairKey(r.origin, r.destination))
      );
      if (keys.size === 0) return state;
      const routeCatering = { ...(state.routeCatering ?? {}) };
      for (const k of keys) routeCatering[k] = level;
      return { ...state, routeCatering };
    }

    // Airline-wide default catering level applied to newly-opened routes.
    case 'SET_DEFAULT_CATERING': {
      return { ...state, defaultCateringLevel: normalizeCateringLevel(action.level) };
    }

    // Edit ONE ancillary product's { offered, price }. Touching any product for the
    // first time activates the whole policy from the recommended baseline, then
    // applies this change on top — so partial edits never leave a half-built policy.
    // action: { id, offered?, price? }
    case 'SET_ANCILLARY': {
      const product = ANCILLARY_MAP[action.id];
      if (!product) return state;
      const base = state.ancillaries ? { ...state.ancillaries } : defaultAncillaries();
      const cur  = base[action.id] ?? { offered: true, price: product.refPrice };
      const next = { ...cur };
      if (action.offered !== undefined) next.offered = !!action.offered;
      if (action.price   !== undefined) {
        const p = Math.round(Number(action.price));
        next.price = Number.isFinite(p) ? Math.max(0, Math.min(product.maxPrice, p)) : cur.price;
      }
      base[action.id] = next;
      return { ...state, ancillaries: normalizeAncillaries(base) };
    }

    // Activate (seed the recommended baseline), reset, or deactivate the whole
    // ancillary policy. action: { active: boolean } or { ancillaries: {...} }
    case 'SET_ANCILLARIES': {
      if (action.ancillaries !== undefined) {
        return { ...state, ancillaries: normalizeAncillaries(action.ancillaries) };
      }
      return { ...state, ancillaries: action.active ? defaultAncillaries() : null };
    }

    case 'HIRE_CREW': {
      // action: { group, count } — crew pipeline (A7). Inert unless the world
      // /save has `crewPipeline: true`.
      //
      // Hiring does NOT add headcount: it pays the training bill up front and
      // queues a batch that becomes usable after the group's lead time. A pilot
      // needs a type rating and line training; a ramp agent needs a fortnight.
      if (!state.crewPipeline) return state;
      const group = action.group;
      if (!LABOR_GROUP_MAP[group]) return state;
      const count = Math.max(0, Math.round(Number(action.count) || 0));
      if (count === 0) return state;
      const cost = crewHireCost(group, count);
      if (cost > state.cash) return state;               // can't train what you can't fund
      // Seed FIRST: an airline that predates the pipeline has no headcount yet,
      // and hiring must not be the thing that books it down to zero staff.
      const current = ensureCrewSeeded(state.labor ?? DEFAULT_LABOR_STATE, state.fleet ?? [], (a) => getAircraftType(a.typeId));
      const g = current[group] ?? { payMultiplier: 1.0, morale: 80 };
      const have = Math.max(0, Number(g.headcount) || 0);
      // Starter crew: while the airline is still crewing up its first couple of
      // aircraft, hires start work immediately — the counterpart of the Starter
      // Fleet perk that delivers those aircraft instantly. The training cost is
      // charged either way; only the wait is waived.
      const { instant, trained } = splitStarterHire(group, count, have, state.fleet ?? [], (a) => getAircraftType(a.typeId));
      const readyAbsWeek = absoluteWeek(state.year ?? 1, state.week ?? 1) + (CREW_LEAD_WEEKS[group] ?? 1);
      return {
        ...state,
        cash: state.cash - cost,
        labor: {
          ...current,
          [group]: {
            ...g,
            headcount: have + instant,
            pipeline: trained > 0
              ? [...(g.pipeline ?? []), { count: trained, readyAbsWeek }]
              : (g.pipeline ?? []),
          },
        },
      };
    }

    case 'SET_LABOR_PAY': {
      // action: { group: 'pilots' | 'cabinCrew' | 'groundStaff' | 'maintenanceTeam', payMultiplier: number }
      const current = state.labor ?? DEFAULT_LABOR_STATE;
      return {
        ...state,
        labor: {
          ...current,
          [action.group]: {
            ...(current[action.group] ?? { payMultiplier: 1.0, morale: 80 }),
            payMultiplier: Math.max(0.5, Math.min(2.0, action.payMultiplier)),
          },
        },
      };
    }

    case 'RESOLVE_NEGOTIATION': {
      // action: { response: 'accept' | 'counter' | 'refuse' }
      // Answers the open union pay demand (state.laborRelations.negotiation).
      const relations   = state.laborRelations ?? DEFAULT_LABOR_RELATIONS;
      const negotiation = relations.negotiation;
      if (!negotiation) return state;

      const group      = negotiation.group;
      const labor      = state.labor ?? DEFAULT_LABOR_STATE;
      const groupState = labor[group] ?? { payMultiplier: 1.0, morale: 80 };
      const absWk      = absoluteWeek(state.year, state.week);

      let newPay   = groupState.payMultiplier;
      let fx;                 // morale/unrest deltas
      let soured   = false;   // sour talks bring the union back sooner
      let outcome;            // 'accepted' | 'counterAccepted' | 'counterRejected' | 'refused'

      if (action.response === 'accept') {
        newPay  = negotiation.demandMultiplier;
        fx      = NEGOTIATION_EFFECTS.accept;
        outcome = 'accepted';
      } else if (action.response === 'counter') {
        // Midpoint offer. The union always pockets the raise; whether it
        // ACCEPTS the deal (or stays angry) depends on current morale.
        newPay = counterOfferMultiplier(groupState.payMultiplier, negotiation.demandMultiplier);
        if (newPay >= negotiation.demandMultiplier - 1e-9) {
          // The midpoint rounded up to (or past) the demand — that isn't a
          // counter, it's the union's own number. It can't be rejected.
          newPay  = negotiation.demandMultiplier;
          fx      = NEGOTIATION_EFFECTS.accept;
          outcome = 'accepted';
        } else if (counterAccepted(groupState.morale)) {
          fx      = NEGOTIATION_EFFECTS.counterAccepted;
          outcome = 'counterAccepted';
        } else {
          fx      = NEGOTIATION_EFFECTS.counterRejected;
          outcome = 'counterRejected';
          soured  = true;
        }
      } else { // refuse
        fx      = NEGOTIATION_EFFECTS.refuse;
        outcome = 'refused';
        soured  = true;
      }

      // What the union carries out of the room. A settlement clears most of it;
      // a refusal adds to it; a collapsed counter adds less, because you did at
      // least put a number on the table.
      const grievDelta =
        outcome === 'refused'         ?  GRIEVANCE_REFUSE
      : outcome === 'counterRejected' ?  GRIEVANCE_COUNTER_REJECTED
      :                                 -GRIEVANCE_SETTLED;
      const prevGriev = relations.grievance ?? DEFAULT_LABOR_RELATIONS.grievance;

      return {
        ...state,
        labor: {
          ...labor,
          [group]: {
            ...groupState,
            payMultiplier: Math.max(0.5, Math.min(MAX_PAY_MULTIPLIER, newPay)),
            morale: Math.max(5, Math.min(100, groupState.morale + fx.morale)),
          },
        },
        laborRelations: {
          ...relations,
          grievance: {
            ...prevGriev,
            [group]: Math.round(Math.max(0, Math.min(1, (prevGriev?.[group] ?? 0) + grievDelta)) * 1000) / 1000,
          },
          negotiation: null,
          unrest: {
            ...relations.unrest,
            [group]: Math.max(0, Math.min(100, (relations.unrest?.[group] ?? 0) + fx.unrest)),
          },
          nextNegotiationAbsWeek: {
            ...(relations.nextNegotiationAbsWeek ?? {}),
            [group]: scheduleNextNegotiation(absWk, soured),
          },
          lastOutcome: {
            group, outcome,
            newPay: Math.max(0.5, Math.min(MAX_PAY_MULTIPLIER, newPay)),
            demand: negotiation.demandMultiplier,
            absWeek: absWk,
          },
        },
      };
    }

    case 'SETTLE_STRIKE': {
      // Capitulate to end an active walkout immediately: 15% raise for the
      // striking group, morale boost, unrest reset, post-strike truce.
      const relations = state.laborRelations ?? DEFAULT_LABOR_RELATIONS;
      const strike    = relations.strike;
      if (!strike) return state;

      const group      = strike.group;
      const labor      = state.labor ?? DEFAULT_LABOR_STATE;
      const groupState = labor[group] ?? { payMultiplier: 1.0, morale: 80 };
      const absWk      = absoluteWeek(state.year, state.week);

      return {
        ...state,
        labor: {
          ...labor,
          [group]: {
            ...groupState,
            payMultiplier: settlementPayMultiplier(groupState.payMultiplier),
            morale: Math.max(5, Math.min(100, groupState.morale + 10)),
          },
        },
        laborRelations: {
          ...relations,
          strike: null,
          strikeCooldownUntilAbsWeek: absWk + STRIKE_COOLDOWN_WEEKS,
          unrest: { ...relations.unrest, [group]: 15 },
        },
      };
    }

    case 'SET_MAINTENANCE_BUDGET': {
      return {
        ...state,
        maintenanceBudget: Math.max(0.5, Math.min(2.0, action.multiplier)),
      };
    }

    case 'SET_MARKETING_BUDGET': {
      // action: { amount } — weekly brand spend in dollars, 0 = no marketing.
      // Coerce first: a missing/non-numeric amount would make Math.max(0, NaN)
      // NaN, which then poisons awareness/demand math (and JSON-degrades to null).
      return {
        ...state,
        marketingBudget: Math.max(0, Math.round(Number(action.amount) || 0)),
      };
    }

    case 'SET_TARGETED_MARKETING': {
      // action: { airport, amount } — weekly targeted spend at one airport; 0 removes it.
      const amount = Math.max(0, Math.round(action.amount || 0));
      const next   = { ...(state.targetedMarketing ?? {}) };
      if (amount > 0) next[action.airport] = amount;
      else            delete next[action.airport];
      return { ...state, targetedMarketing: next };
    }

    case 'RENEW_LEASE': {
      // action: { aircraftId } — reset lease countdown to full term (same rate).
      // Legacy action, kept for backward compatibility; the UI now uses EXTEND_LEASE.
      return {
        ...state,
        fleet: state.fleet.map(a =>
          a.id === action.aircraftId && a.ownershipType === 'lease'
            ? { ...a, leaseRemainingWeeks: a.leaseTermWeeks ?? DEFAULT_LEASE_TERM_WEEKS }
            : a
        ),
      };
    }

    case 'EXTEND_LEASE': {
      // action: { aircraftId, addWeeks } — add weeks onto the CURRENT remaining term
      // at the same weekly rate, available at any time, free. Remaining time is
      // never lost (unlike a full reset). The nominal term grows to match so the
      // remaining bar never exceeds the term.
      //
      // CEILING (belt and braces with lib/decisionGuard.mjs, which clamps the
      // multiplayer payload to the same 520 weeks): this used to have a floor
      // and no ceiling, so a forged `addWeeks: 10_000_000` was applied verbatim
      // and handed the airline a ten-thousand-year lease at today's weekly rate.
      // 520 weeks = 10 years, the longest term the lease market offers.
      const addWeeks = Math.min(520, Math.max(0, Math.round(Number(action.addWeeks) || 0)));
      if (addWeeks === 0) return state;
      return {
        ...state,
        fleet: state.fleet.map(a => {
          if (a.id !== action.aircraftId || a.ownershipType !== 'lease') return a;
          const newRemaining = (a.leaseRemainingWeeks ?? 0) + addWeeks;
          const newTerm      = Math.max(a.leaseTermWeeks ?? 0, newRemaining);
          return { ...a, leaseRemainingWeeks: newRemaining, leaseTermWeeks: newTerm };
        }),
      };
    }

    case 'BUY_OUT_LEASE': {
      // action: { aircraftId } — purchase a leased aircraft outright. Price is the
      // current depreciated market value (NAV) plus an early-buyout premium, minus
      // the security deposit already on file. The tail converts to 'owned' (no more
      // weekly rent, and it can later be sold like any owned jet).
      const aircraft = state.fleet.find(a => a.id === action.aircraftId);
      if (!aircraft || aircraft.ownershipType !== 'lease') return state;
      // Same quote the Fleet panel showed the player. models/leaseBuyout.js
      // prices off airframeNAV — the exact valuation SELL_AIRCRAFT pays out on —
      // so buying a jet out and selling it back can never turn a profit.
      const buyoutPrice = leaseBuyoutQuote(state, aircraft).price;
      if (state.cash < buyoutPrice) return state;   // can't afford — no-op
      return {
        ...state,
        cash: state.cash - buyoutPrice,
        fleet: state.fleet.map(a =>
          a.id === action.aircraftId
            ? {
                ...a,
                ownershipType:       'owned',
                weeklyLease:         0,
                leaseDeposit:        0,
                leaseTermWeeks:      undefined,
                leaseRemainingWeeks: undefined,
              }
            : a
        ),
      };
    }

    case 'SET_LOYALTY_INVESTMENT': {
      // action: { amount } — weekly spend in dollars, 0 = no program.
      // Coerce first so a missing/non-numeric amount can't inject NaN.
      return {
        ...state,
        loyalty: {
          ...(state.loyalty ?? { members: 0 }),
          weeklyInvestment: Math.max(0, Math.round(Number(action.amount) || 0)),
        },
      };
    }

    // ─── Alliance & codeshare actions ───────────────────────────────────────

    case 'JOIN_ALLIANCE': {
      // action: { allianceId }
      const alliance = getAlliance(action.allianceId);
      if (!alliance) return state;
      if (state.cash < alliance.initiationFee) return state;
      if (state.allianceMembership) return state; // already in one
      return {
        ...state,
        cash: state.cash - alliance.initiationFee,
        allianceMembership: {
          allianceId: alliance.id,
          joinedWeek: state.week,
          weeklyFee:  alliance.weeklyFee,
        },
      };
    }

    case 'LEAVE_ALLIANCE': {
      return { ...state, allianceMembership: null };
    }

    case 'SIGN_CODESHARE': {
      // action: { competitorId, partner? }
      const activeAgreements = state.codeshareAgreements ?? [];
      if (activeAgreements.length >= MAX_CODESHARE_AGREEMENTS) return state;
      if (activeAgreements.some(a => a.competitorId === action.competitorId)) return state;

      // `partner` is how the SERVER signs the other side of a bilateral deal.
      // state.competitors is rebuilt on every read and stripped before
      // persistence, so a dispatch against a raw stored blob finds nobody —
      // which would have made an accepted codeshare silently no-op for the
      // acceptor while charging the offerer. Solo and the client keep taking
      // the first branch, unchanged.
      const comp = (state.competitors ?? []).find(c => c.id === action.competitorId)
        ?? (action.partner?.id === action.competitorId ? action.partner : null);
      if (!comp) return state;

      const weeklyFee = CODESHARE_WEEKLY_FEE_BY_TIER[comp.tier] ?? CODESHARE_WEEKLY_FEE_BY_TIER.legacy;
      const newAgreement = {
        id:              uid(),
        competitorId:    comp.id,
        competitorName:  comp.name,
        competitorTier:  comp.tier,
        weeklyFee,
        signedWeek:      state.week,
        signedYear:      state.year,
        weeksRemaining:  CODESHARE_DURATION_WEEKS,
      };
      return {
        ...state,
        codeshareAgreements: [...activeAgreements, newAgreement],
      };
    }

    case 'CANCEL_CODESHARE': {
      // action: { agreementId } | { competitorId }
      //
      // By partner as well as by id, because cancelling is bilateral now: the
      // server tears down BOTH sides, and it knows who the partner is without
      // knowing what the other airline happened to call its copy of the deal.
      return {
        ...state,
        codeshareAgreements: (state.codeshareAgreements ?? []).filter(a =>
          action.competitorId != null
            ? a.competitorId !== action.competitorId
            : a.id !== action.agreementId),
      };
    }

    case 'ACQUIRE_COMPETITOR': {
      // action: { competitorId }
      const target = (state.competitors ?? []).find(c => c.id === action.competitorId);
      if (!target) return state;

      // Value the target. marketCap is only populated after the first weekly tick;
      // fall back to a computed valuation so a fresh-game competitor can never be
      // acquired for $0 (which would also hand the player their cash for free).
      const targetValue = target.marketCap
        ?? computeMarketCap(target.profitHistory ?? [], target.cash ?? 0, target.baseQualityScore ?? 50).marketCap;
      // Distressed carriers sell at a discount (fire sale) instead of a premium.
      const acquisitionCost = Math.round(targetValue * (target.fireSale ? FIRE_SALE_PREMIUM : 1.25));
      if (state.cash < acquisitionCost) return state;  // can't afford — ignore

      // ── Inherit the competitor's REAL fleet ────────────────────────────────
      // Each competitor tail becomes an owned player aircraft (kept aged, flagged
      // `acquired`). We remember oldTailId → new player id so routes can be wired
      // to the correct airframe.
      const usedTails    = state.fleet.map(a => a.tailNumber).filter(Boolean);
      const tailIdMap    = {};        // competitor tail id → new player aircraft id
      const tailsByRoute = {};        // routeKey → [new player aircraft ids]
      const acquiredFleet = (target.fleet ?? []).map(tail => {
        const type       = getAircraftType(tail.typeId);
        const newId      = uid();
        const tailNumber = generateTailNumber(state.hub, state.airlineName, usedTails);
        usedTails.push(tailNumber);
        tailIdMap[tail.id] = newId;
        (tailsByRoute[tail.routeKey] ??= []).push(newId);
        return {
          id:            newId,
          typeId:        tail.typeId,
          name:          `${type?.name ?? tail.typeId} (ex-${target.name})`,
          tailNumber,
          status:        'idle',   // set to 'assigned' below if it takes a route
          ageWeeks:      tail.ageWeeks ?? 0,
          config:        defaultConfig(type?.seats ?? 150),
          ownershipType: 'owned',
          acquired:      true,
        };
      });

      // ── Inherit routes, assigning ONE tail each (player model = 1 aircraft/route).
      // Frequency is capped to what a single airframe can fly; surplus tails stay
      // idle in the fleet, ready to redeploy.
      const assignedIds    = new Set();
      const slotsByAirport = {};
      const inheritedRoutes = Object.entries(target.routes ?? {}).map(([key, cfg]) => {
        const [a, b] = key.split('-');
        const refP   = mktReferencePrice(a, b);
        const dist   = routeDistanceKm(a, b);

        // Take the first available inherited tail on this route as the operator.
        const poolIds   = tailsByRoute[key] ?? [];
        const opId      = poolIds.find(id => !assignedIds.has(id)) ?? null;
        const opType    = opId ? getAircraftType(acquiredFleet.find(f => f.id === opId)?.typeId) : null;
        if (opId) assignedIds.add(opId);

        // Cap frequency to a single tail's block-hour limit.
        const cap  = opType ? Math.max(1, maxFrequency(dist, opType)) : (cfg.frequency ?? 7);
        const freq = Math.min(cfg.frequency ?? 7, cap);

        slotsByAirport[a] = (slotsByAirport[a] ?? 0) + freq;
        slotsByAirport[b] = (slotsByAirport[b] ?? 0) + freq;

        const basePrice = Math.round(refP * (cfg.priceMultiplier ?? 1));
        return {
          id:              uid(),
          origin:          a,
          destination:     b,
          aircraftId:      opId,
          weeklyFrequency: freq,
          hub:             state.hub,
          weeksOpen:       0,
          inherited:       true,
          _basePrice:      basePrice,   // transient: folded into routePricing below
        };
      });

      // Price/cater the inherited pairs (one set per O&D). Don't clobber a pair the
      // player already operates — they keep their own settings on overlapping routes.
      const acquiredPricing  = { ...(state.routePricing  ?? {}) };
      const acquiredCatering = { ...(state.routeCatering ?? {}) };
      const inheritedCatering = normalizeCateringLevel(state.defaultCateringLevel);
      for (const r of inheritedRoutes) {
        const key = routePairKey(r.origin, r.destination);
        if (!acquiredPricing[key])  acquiredPricing[key]  = defaultClassPrices(r._basePrice);
        if (!acquiredCatering[key]) acquiredCatering[key] = inheritedCatering;
        delete r._basePrice;
      }

      // Mark assigned tails as such.
      const acquiredFleetFinal = acquiredFleet.map(f =>
        assignedIds.has(f.id) ? { ...f, status: 'assigned' } : f
      );

      // Grant gate slots at every airport the competitor served (plus home hub),
      // sized to cover inherited route slots, merged with existing gates.
      const newGates = { ...(state.gates ?? {}) };
      for (const [code, slots] of Object.entries(slotsByAirport)) {
        newGates[code] = (newGates[code] ?? 0) + Math.max(1, Math.ceil(slots / SLOTS_PER_GATE));
      }
      if (target.homeHub) {
        newGates[target.homeHub] = Math.max(newGates[target.homeHub] ?? 0, 2);
      }
      const gatesGained = Object.values(newGates).reduce((s, v) => s + v, 0)
                        - Object.values(state.gates ?? {}).reduce((s, v) => s + v, 0);

      // Cancel any codeshare with the acquired competitor.
      const cleanedCodeshares = (state.codeshareAgreements ?? [])
        .filter(a => a.competitorId !== target.id);

      const surplus = acquiredFleetFinal.length - assignedIds.size;

      // If the player holds stock in the airline they just bought outright, the
      // position cashes out at the deal's per-share price (you're paying the
      // full acquisition cost, so the pro-rata slice comes straight back).
      const acqPortfolio = state.portfolio ?? emptyPortfolio();
      const acqHolding   = acqPortfolio.holdings?.[target.id];
      const acqBuyout    = acqHolding?.shares > 0
        ? Math.round(acqHolding.shares * (acquisitionCost / sharesOf(target)))
        : 0;
      const acqHoldings  = { ...(acqPortfolio.holdings ?? {}) };
      delete acqHoldings[target.id];
      const portfolioAfterAcquire = acqBuyout > 0
        ? { ...acqPortfolio,
            holdings:         acqHoldings,
            realizedPnL:      (acqPortfolio.realizedPnL ?? 0) + acqBuyout - (acqHolding.costBasis ?? 0),
            realizedThisWeek: (acqPortfolio.realizedThisWeek ?? 0) + acqBuyout - (acqHolding.costBasis ?? 0) }
        : acqPortfolio;

      // ── Win condition: the last rival has been absorbed ────────────────────
      const remainingCompetitors = (state.competitors ?? []).filter(c => c.id !== target.id);
      const finalFleet  = [...state.fleet, ...acquiredFleetFinal];
      const hasWon      = remainingCompetitors.length === 0 && !state.gameWon;
      const victoryStats = hasWon ? {
        marketCap:    state.marketCap ?? null,
        cash:         state.cash - acquisitionCost + (target.cash ?? 0) + acqBuyout,
        fleetCount:   finalFleet.filter(a => a.status !== 'retired').length,
        routeCount:   state.routes.length + inheritedRoutes.length,
        airports:     Object.values(newGates).filter(n => n > 0).length,
        weeksPlayed:  (state.year - 1) * 52 + state.week,
        year:         state.year,
        lastRival:    target.name,
      } : null;

      const acquireToasts = [
        {
          type: 'success',
          icon: '🤝',
          title: `Acquired ${target.name}`,
          message: `+${inheritedRoutes.length} routes · +${acquiredFleetFinal.length} aircraft`
                 + `${surplus > 0 ? ` (${surplus} spare)` : ''} · +${gatesGained} gates`,
          duration: 8000,
        },
      ];

      return {
        ...state,
        cash:                state.cash - acquisitionCost + (target.cash ?? 0) + acqBuyout,
        portfolio:           portfolioAfterAcquire,
        routes:              [...state.routes, ...inheritedRoutes],
        routePricing:        acquiredPricing,
        routeCatering:       acquiredCatering,
        fleet:               finalFleet,
        gates:               newGates,
        competitors:         remainingCompetitors,
        codeshareAgreements: cleanedCodeshares,
        gameWon:             state.gameWon || hasWon,
        victoryStats:        hasWon ? victoryStats : state.victoryStats,
        victoryAcknowledged: hasWon ? false : state.victoryAcknowledged,
        pendingToasts: [ ...(state.pendingToasts ?? []), ...acquireToasts ],
      };
    }

    case 'ACKNOWLEDGE_VICTORY':
      return { ...state, victoryAcknowledged: true };

    case 'ADVANCE_WEEK': { try {
      // ── Deterministic pre-tick prep (utils/tickPrep.js) ────────────────────
      // Events aged and expired, the fuel shock folded into the index so hedges
      // cover it, grounding and heavy-check countdowns run down, reserve covers
      // dispatched, seasonal routes flipped, bases and lounges opened. It lives
      // in its own module because projectWeek has to run the IDENTICAL prep — a
      // forecast built on the raw state is a forecast of a week that cannot
      // happen (see the header of tickPrep.js for what that cost us).
      //
      // The only random draw inside is rollEvents, and it is the first draw this
      // case made before the extraction too, so the RNG sequence — and the
      // golden master — is unchanged. tickMarketIndex and tickFuelPrice stay
      // below, in their original order.
      const prep = prepareWeek(state, {
        worldEvents:    action.worldEvents,
        worldFuelIndex: action.worldFuelIndex,
      });
      const {
        survivingEvents, expiredEvents, newEvents, allEvents, eventOtpDelta,
        injectedFuel, baseFuelIndex, currentFuelIndex, fuelMultiplier, fuelPriceHistory,
        activeHedges, liveHedges,
        gameMonth, gameDate, curAbsWeek,
        completedChecks, tickedFleetPre, coverPass,
        seasonalReactivationCost: seasonalReactivationCostPrep,
        seasonalReactivations, seasonAdjustedRoutes,
        baseBuild, tickedBases, loungeBuild, tickedLounges,
        laborThisWeek,
      } = prep;
      let seasonalReactivationCost = seasonalReactivationCostPrep;
      const nowAbsWeek = curAbsWeek;

      // World market index: the same shape as the fuel index above. Multiplayer
      // replays one shared walk per world-week (action.marketIndex, seeded from
      // worldSeed in tickService) so every player's valuation moves with the same
      // market; solo keeps its own walk. Zero drift by construction — it makes
      // timing matter without creating or destroying value over a long world.
      const injectedMarket = (state.multiplayer === true
        && typeof action.marketIndex === 'number'
        && Number.isFinite(action.marketIndex))
        ? action.marketIndex : null;
      const currentMarketIndex = injectedMarket ?? state.marketIndex ?? MARKET_BASE_INDEX;
      const nextMarketIndex    = injectedMarket != null
        ? injectedMarket
        : tickMarketIndex(currentMarketIndex);
      // Sentiment levered by fuel — one multiplier applied to every airline in
      // the world, the player included.
      const marketFactor = marketValuationFactor(currentMarketIndex, currentFuelIndex);

      // Next week's stored index: in MP the world injects it each tick, so persist
      // the shared value; in solo, tick the per-save market price forward. Stays
      // here rather than in prepareWeek: it is a random draw, and a projection
      // must neither predict it nor burn it.
      const _fuelCy          = calendarYear(state);
      const nextFuelIndex    = injectedFuel != null ? injectedFuel
        : _fuelCy == null ? tickFuelPrice(baseFuelIndex)
        : tickFuelPrice(baseFuelIndex, undefined,
            eraFuelMean(_fuelCy) ?? FUEL_BASE_INDEX, ERA_FUEL_MIN_INDEX);

      // Age + mechanical tick must run BEFORE weeklyTick so that aircraft recovering
      // from grounding this week can actually fly and earn revenue.
      const mainBudgetPre = state.maintenanceBudget ?? 1.0;
      const agingRatePre  = Math.max(0.5, 1 + (1 - mainBudgetPre) * 0.5);

      // completedChecks, tickedFleetPre, coverPass, gameMonth/gameDate and the
      // seasonal pass all come from prepareWeek above — the same values, in the
      // same order, now shared with projectWeek.

      // Multiplayer (Headwinds): no AI carriers exist. The server injects other
      // human players as state.competitors + state.humanRivals each tick, so AI
      // encroachment, AI network evolution, and AI startups are all skipped.
      const isMultiplayerWorld = state.multiplayer === true;

      // ── Route encroachment: AI carriers contest the player's fat routes ──────
      // Decided from the PRIOR week's outcome (load factor + fares), gated by airline
      // size, then injected into this week's demand model so they split passengers.
      const { encroachments: updatedEncroachments, events: encroachEvents } = isMultiplayerWorld
        ? { encroachments: {}, events: [] }  // MP: wipe — no AI encroachment ever persists or contests a route in multiplayer
        : tickEncroachment({
        // Dormant seasonal routes aren't in the market this month, so AI carriers
        // shouldn't contest them or count their (idle) frequency on the pair.
        routes:       coverPass.routes
          .filter(r => isRouteActive(r, gameMonth))
          .map(r => hydrateRoute(r, state.routePricing, state.routeCatering)),
        routePricing: state.routePricing,
        lastReport:   state.lastReport,
        marketCap:    state.marketCap ?? 0,
        competitors:  state.competitors ?? [],
        encroachments: state.encroachments ?? {},
      });

      // baseBuild/tickedBases and loungeBuild/tickedLounges (construction advanced
      // BEFORE the week's economics, so a hangar or a room that finishes this week
      // earns its keep this week) and laborThisWeek also come from prepareWeek.
      //
      // prep.tickInput is the whole pre-tick state. The ONLY thing added here is
      // this week's freshly-rolled AI challengers — a random draw, and therefore
      // the one input a projection is right not to share.
      const report = weeklyTick({ ...prep.tickInput, encroachments: updatedEncroachments });

      // ── Loyalty program: grow/decay member base + maturity + points debt ──
      // Penetration-based S-curve. Enrollment slows as the base approaches the
      // tier's penetration ceiling (you can't enrol people who already belong).
      // MATURITY compounds slowly (~18 months funded to reach 1.0) and gates
      // all demand-side effects, so the program pays off long after sign-ups
      // plateau. A ramped "effective" budget gives the dial inertia so changing
      // it isn't a light switch.
      const currentLoyalty = state.loyalty ?? { weeklyInvestment: 0, members: 0, effInvestment: 0, maturity: 0, pointsLiability: 0 };
      const targetInvestment = currentLoyalty.weeklyInvestment ?? 0;
      const prevEff          = currentLoyalty.effInvestment ?? targetInvestment;
      // Ease ~18%/week toward the set budget (≈63% of a change felt after 5 weeks).
      const effInvestment    = Math.round(prevEff + (targetInvestment - prevEff) * 0.18);

      // Smoothed passenger base (8-wk avg) so a dip or shrink doesn't fake-inflate
      // penetration; falls back to this week's count for young/old saves.
      const loyaltyWeeklyPax = loyaltyPaxBase(state) || (report.totalPassengers ?? 0);
      const prevMaturity     = currentLoyalty.maturity ?? 0;
      let newLoyaltyMembers  = currentLoyalty.members ?? 0;
      let newMaturity        = prevMaturity;
      // Funding is judged on the SET budget (what's actually being paid), not
      // the ramped effective budget — otherwise a cancelled program would keep
      // enrolling and maturing for free while the ramp winds down.
      if (targetInvestment > 0 && effInvestment > 0 && loyaltyWeeklyPax > 0) {
        const tier      = loyaltyTier(effInvestment);
        const enrollPull = loyaltyEnrollPull(effInvestment);
        const ceiling   = tier.maxPenetration * loyaltyWeeklyPax * 4;   // max members this tier sustains
        const headroom  = ceiling > 0 ? Math.max(0, 1 - newLoyaltyMembers / ceiling) : 0;
        const newEnrollments = Math.round(loyaltyWeeklyPax * enrollPull * headroom);
        // 0.4% weekly churn when funded — real frequent-flyer accounts are sticky.
        newLoyaltyMembers = Math.round(newLoyaltyMembers * 0.996 + newEnrollments);
        // Maturity grows at the tier's pace (~80 funded weeks at Gold).
        newMaturity = Math.min(1, prevMaturity + (tier.maturityFactor ?? 1) / 80);
      } else {
        // Program unfunded: members lapse — and if the program was mature, the
        // betrayal cuts deeper (status flyers defect to rivals fast). Maturity
        // itself unwinds in ~20 weeks: trust is torn down 4× faster than built.
        const lapseRate = prevMaturity > 0.4 ? 0.97 : 0.988;
        newLoyaltyMembers = Math.round(newLoyaltyMembers * lapseRate);
        newMaturity = Math.max(0, prevMaturity - 1 / 20);
      }
      // Members who no longer fly you lapse: the base can't exceed ~85% of a
      // month's flyers. Shrink the airline and the excess bleeds off at
      // ~10%/wk — no more "100% of pax are members" after cutting routes.
      const loyaltyHardCap = Math.round(loyaltyWeeklyPax * 4 * 0.85);
      if (loyaltyHardCap > 0 && newLoyaltyMembers > loyaltyHardCap) {
        newLoyaltyMembers = Math.round(loyaltyHardCap + (newLoyaltyMembers - loyaltyHardCap) * 0.90);
      }
      // Outstanding points liability was advanced by the engine this week
      // (earn accrual minus redemptions/breakage) — persist the new stock.
      const newPointsLiability = report.loyaltyLiability ?? currentLoyalty.pointsLiability ?? 0;
      const updatedLoyalty = {
        ...currentLoyalty,
        members: Math.max(0, newLoyaltyMembers),
        effInvestment,
        maturity: newMaturity,
        pointsLiability: newPointsLiability,
      };

      // ── Awareness: grows from operations + marketing, decays without activity ──
      // Organic: passengers flying builds word-of-mouth. Marketing accelerates growth.
      // Diminishing returns: harder to grow from 80→100 than 5→80.
      const currentAwareness = state.awareness ?? 5;
      const diminishingFactor = 1 - currentAwareness / 100;
      const organicGain   = Math.min(1.0, (report.totalPassengers ?? 0) / 1000) * diminishingFactor;
      // Adstock: brand spend buys awareness points (revenue-scaled, diminishing),
      // and awareness above the floor decays proportionally each week. Demand
      // lift comes ONLY from this stock — see awarenessDemandMultiplier.
      const mktGain = marketingAwarenessGain(state.marketingBudget ?? 0, report.totalRevenue ?? 0)
        * diminishingFactor;
      const awarenessDecay = state.routes.length === 0
        ? Math.max(0.5, (currentAwareness - AWARENESS_FLOOR) * AWARENESS_DECAY_RATE)
        : (currentAwareness - AWARENESS_FLOOR) * AWARENESS_DECAY_RATE;
      const newAwareness   = Math.max(AWARENESS_FLOOR, Math.min(100,
        currentAwareness + organicGain + mktGain - awarenessDecay
      ));

      // ── Targeted campaign stocks: fast build with spend, fast decay without ──
      // Gain is scaled by SHARE OF VOICE: rival marketing at the same airport
      // (hub ads, blitzes) makes your campaign build slower there.
      const prevCampaigns   = state.campaignStrength ?? {};
      const targetedSpend   = state.targetedMarketing ?? {};
      const compMktVoice    = competitorMarketingSpend(state.competitors ?? []);
      const campaignCodes   = new Set([...Object.keys(prevCampaigns), ...Object.keys(targetedSpend)]);
      const newCampaigns    = {};
      for (const code of campaignCodes) {
        const prev  = prevCampaigns[code] ?? 0;
        const popM  = (() => { const ap = getAirport(code); return ap?.effectivePop ?? ap?.population ?? 1; })();
        const sov   = shareOfVoiceFactor(targetedSpend[code] ?? 0, compMktVoice[code] ?? 0);
        const gain  = campaignStrengthGain(targetedSpend[code] ?? 0, popM) * sov * (1 - prev / 100);
        const next  = prev * (1 - CAMPAIGN_DECAY_RATE) + gain;
        if (next >= 0.5) newCampaigns[code] = Math.min(100, +next.toFixed(2));
      }

      // Event demand shocks are baked into report revenue by weeklyTick (they
      // shrink each route's passenger pool). The old flat line-item adjustment
      // is retired; the field is kept at 0 so saved-history charts that add
      // eventDemandAdj back into revenue keep reconciling for old saves.
      const eventDemandAdj  = 0;

      // ── Strike in progress: cancelled flights forfeit a share of revenue ──
      // The walkout that started in a previous week applies to THIS week's
      // schedule. Applied as a line-item revenue loss so cash still
      // reconciles: fixed costs keep running while the picket line is up —
      // that is the pain of a strike.
      const relationsPrev = state.laborRelations ?? DEFAULT_LABOR_RELATIONS;
      const activeStrike  = relationsPrev.strike && relationsPrev.strike.weeksLeft > 0
        ? relationsPrev.strike : null;
      const strikeRevenueLoss = activeStrike && report.totalRevenue
        ? Math.round(report.totalRevenue * activeStrike.severity) : 0;

      // A strike cancelled the revenue but still charged every variable cost of
      // flying the full schedule — fuel for departures that never pushed back,
      // landing fees at airports the aircraft never reached, catering loaded
      // onto nothing. The comment above the old line was right that FIXED costs
      // keep running, which is the pain of a strike; it just also charged the
      // variable ones, making a 55%-severity walkout cost roughly double what
      // it should and making capitulation look artificially cheap next to it.
      //
      // Refunded pro-rata to severity, and only the unambiguously per-departure
      // lines. Lounges, layover hotels and delay compensation keep running —
      // during a walkout the compensation bill would if anything go up.
      const strikeVariableSaved = activeStrike && report.totalRevenue
        ? Math.round(
            ((report.totalFuel ?? 0) + (report.totalCrew ?? 0) + (report.totalCatering ?? 0)
             + (report.totalGroundHandling ?? 0) + (report.totalLandingFees ?? 0)
             + (report.totalAncillaryCost ?? 0)) * activeStrike.severity)
        : 0;

      const adjustedCashDelta = report.cashDelta - strikeRevenueLoss + strikeVariableSaved;

      // agingRate and tickedFleet were computed before weeklyTick above.
      const mainBudget = mainBudgetPre;
      const agingRate  = agingRatePre;

      // ── Mechanical failures ──────────────────────────────────────────────
      // tickedFleet (grounded countdown tick) was already applied before weeklyTick.
      const tickedFleet = coverPass.fleet;

      // 2. Roll for new failures on non-grounded aircraft
      const newFailures = rollMechanicalFailures(tickedFleet, mainBudget);

      // ── AOG repair bills ──────────────────────────────────────────────────
      // A breakdown used to be free — the jet just sat there. It now carries a
      // repair bill scaled to the airframe's value and the severity of the
      // fault. A certified jet base on the aircraft's network makes it cheaper
      // and shorter, IF a shop slot is free. When the repair would cost more
      // than the aircraft is worth it is written off instead (hull insurance
      // pays out on owned metal).
      const mroSlots      = newSlotLedger(tickedBases);
      const mroFactorsRep = report.mroFactorsByAircraft ?? {};
      const mroLaborMult  = laborEffects(state.labor).maintenanceCostMultiplier;
      const mroJobs       = [];
      const writeOffIds   = new Set();
      let aogSpend     = 0;
      let aogInsurance = 0;
      for (const f of newFailures) {
        const ac = tickedFleet.find(a => a.id === f.aircraftId);
        const ty = ac ? getAircraftType(ac.typeId) : null;
        const mf = mroFactorsRep[f.aircraftId] ?? null;
        const atBase = !!(mf && mf.code && claimSlot(mroSlots, mf.code));
        const priced = aogRepairCost(ac, ty, f.severity, {
          maintMod:   ac?.maintMod ?? 1,
          laborMult:  mroLaborMult,
          baseFactor: atBase ? mf.aogCostMult : 1,
          absWeek:    curAbsWeek,
        });
        if (atBase) {
          const pool = tickedBases[mf.code]?.partsPool;
          f.weeksGrounded = Math.max(1, Math.round((f.weeksGrounded - mf.aogWeeksSaved) * partsPoolDurationMult(pool)));
        }
        f.repairCost = priced.cost;
        f.writeOff   = priced.writeOff;
        f.payout     = priced.payout;
        f.baseCode   = atBase ? mf.code : null;
        if (priced.writeOff) { writeOffIds.add(f.aircraftId); aogInsurance += priced.payout; }
        else                 { aogSpend += priced.cost; }
        mroJobs.push({
          kind: 'aog', aircraftId: f.aircraftId, name: f.aircraftName, tailNumber: f.tailNumber,
          label: f.label, cost: priced.cost, base: f.baseCode, weeks: f.weeksGrounded,
          writeOff: priced.writeOff, payout: priced.payout,
        });
      }
      // A written-off airframe is gone, not grounded.
      const failedIds   = new Set(newFailures.filter(f => !f.writeOff).map(f => f.aircraftId));

      // 3. Apply failures + age + lease countdown
      let leaseRedeliveryCost = 0;
      // Security deposits returned this week with the airframes they secured.
      // Cash-only: the deposit never entered the P&L on the way out either.
      let leaseDepositRefund  = 0;
      const removedAircraftIds   = new Set(writeOffIds);   // lease expiries + AOG write-offs
      const leaseWarningToasts = [];

      // ── Toast configs for new / expired events ─────────────────────────
      // NOTE: leaseWarningToasts is populated inside the agedFleet.map() below,
      // so it must be pushed in AFTER that loop (not spread here at construction time).
      const newToasts = [
        ...newEvents.map(ev => ({
          type: ev.type === 'fuel' || ev.type === 'disruption' || ev.type === 'economy'
            ? (ev.effects?.fuelMult > 1 || ev.effects?.globalDemandMult < 1 || ev.effects?.regionDemandMult < 1
                ? 'danger' : 'success')
            : (ev.effects?.globalDemandMult > 1 || ev.effects?.regionDemandMult > 1 ? 'success' : 'warning'),
          title: ev.name,
          message: ev.description,
          icon: ev.icon,
          eventColor: ev.color,
          duration: 7000,
        })),
        ...expiredEvents.map(ev => ({
          type: 'info',
          title: `${ev.name} — ended`,
          message: `The event has resolved after ${ev.totalDur} week${ev.totalDur !== 1 ? 's' : ''}.`,
          icon: ev.icon,
          duration: 4000,
        })),
      ];
      if (seasonalReactivations.length > 0) {
        const list = seasonalReactivations.map(r => `${r.origin}–${r.destination}`).join(', ');
        newToasts.push({
          type:    'info',
          title:   `🗓 Seasonal route${seasonalReactivations.length > 1 ? 's' : ''} resumed`,
          message: `${list} back in service. Reactivation fee: ${seasonalReactivationCost.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}.`,
          icon:    '🗓',
          duration: 7000,
        });
      }
      // ── Heavy-maintenance: block-hours flown this week drive C/D wear ─────────
      const acTypeById = new Map(tickedFleet.map(a => [a.id, getAircraftType(a.typeId)]));
      const maintHoursById = new Map();
      for (const r of [...coverPass.routes, ...coverPass.cargoRoutes]) {
        if (!r.aircraftId || !isRouteActive(r, gameMonth)) continue;
        const ty = acTypeById.get(r.aircraftId);
        if (ty) maintHoursById.set(r.aircraftId, (maintHoursById.get(r.aircraftId) ?? 0) + routeBlockHours(r, ty, r.weeklyFrequency));
      }
      const maintLaborMult = laborEffects(state.labor).maintenanceCostMultiplier;
      // Auto-scheduling: a maintenance org paid ≥1.3× market with a ≥1.3× line
      // budget books its own heavy checks the week they come due (planned cost,
      // planned downtime) — no waking up to regulator groundings.
      const autoMaintActive = autoSchedulingActive(state.labor, state.maintenanceBudget);
      let maintCheckSpend = 0;
      let forcedRepHit    = 0;
      let runningCashForChecks = state.cash;
      const checksStarted = [];
      const checksForced  = [];

      // Facility discount for a heavy check: the better of the hub factor and a
      // certified jet base on this aircraft's network — they do not stack. The
      // base only helps if a shop slot is still free this week; overflow work
      // goes to a third party at full price and full downtime.
      const checkFacility = (ac, ct) => {
        const hubF = aircraftHubMaintFactor(ac.id, coverPass.routes, coverPass.cargoRoutes, state.hubs);
        const mf   = mroFactorsRep[ac.id] ?? null;
        if (!mf || !mf.code || !hasSlot(mroSlots, mf.code)) return { factor: hubF, weeksSaved: 0, base: null };
        const mult = ct === 'D' ? mf.dCostMult : mf.cCostMult;
        if (mult >= 1) return { factor: hubF, weeksSaved: 0, base: null };
        return { factor: Math.min(hubF, mult), weeksSaved: ct === 'D' ? mf.dWeeksSaved : mf.cWeeksSaved, base: mf.code };
      };

      const agedFleet = tickedFleet.map(a => {
        // Written off this week — the airframe leaves the fleet entirely.
        if (writeOffIds.has(a.id)) return null;
        let aged = { ...a, ageWeeks: (a.ageWeeks ?? 0) + agingRate };
        aged = accrueMaintenance(aged, isOutOfService(a) ? 0 : (maintHoursById.get(a.id) ?? 0), curAbsWeek);
        if (failedIds.has(a.id)) {
          const failure = newFailures.find(f => f.aircraftId === a.id);
          return { ...aged, status: 'grounded', groundedWeeksLeft: failure.weeksGrounded, groundedReason: 'failure' };
        }
        // Tick lease countdown for leased aircraft
        if (a.ownershipType === 'lease' && (a.leaseRemainingWeeks ?? 0) > 0) {
          const remaining = (a.leaseRemainingWeeks ?? 0) - 1;
          // Warn at 8 and 4 weeks remaining
          if (remaining === 8 || remaining === 4) {
            // Name all three ways out, in the order a player would want them.
            // Discord (Lancelotbronner, 2026-08-18): "I had a stressful 2
            // in-game years replacing end-of-lease with newly built planes as
            // they were expiring" — on a build that already shipped a buyout
            // button. This toast is where he would have found it and it only
            // ever mentioned renewing and returning.
            const buyout = leaseBuyoutQuote(state, a).price;
            leaseWarningToasts.push({
              type:     'warning',
              title:    `⏳ Lease expiring — ${a.name}`,
              message:  `${remaining} weeks remaining on ${a.name}'s lease. In Fleet you can extend it, `
                      + `buy the aircraft outright for ${buyout.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}, or let it go back `
                      + `(4 weeks' rent redelivery, and its routes close).`,
              duration: 8000,
            });
          }
          // Lease expired: charge redelivery fee (4 weeks of rent), return the
          // security deposit, and remove the aircraft.
          if (remaining <= 0) {
            const type = getAircraftType(a.typeId);
            // Bill the rate this tail signed at, not whatever the table says today.
            const redeliveryRate = a.weeklyLease ?? type?.weeklyLease ?? 0;
            leaseRedeliveryCost += redeliveryRate * 4;
            // The deposit is refundable and comes back with the airframe. It is
            // a pure cash movement in both directions — it was never booked
            // through the P&L when it was paid at order time, so returning it
            // is not income and must not be netted against the redelivery fee.
            const depositBack = a.leaseDeposit ?? 0;
            leaseDepositRefund += depositBack;
            removedAircraftIds.add(a.id);
            leaseWarningToasts.push({
              type:     'danger',
              title:    `📋 Lease ended — ${a.name}`,
              message:  `${a.name}'s lease has expired. Aircraft returned; redelivery fee of ${(redeliveryRate * 4).toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })} charged${depositBack > 0 ? `, security deposit of ${depositBack.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })} returned` : ''}.`,
              duration: 10000,
            });
            return null; // mark for removal
          }
          aged = { ...aged, leaseRemainingWeeks: remaining };
        }

        // Heavy-check lifecycle (in-service aircraft only; leased included).
        if (!isOutOfService(aged)) {
          const mType = getAircraftType(aged.typeId);
          const sc    = aged.scheduledCheck;
          if (sc && curAbsWeek >= (sc.startWeek ?? curAbsWeek)) {
            const ct   = sc.type === 'D' ? 'D' : 'C';
            const fac  = checkFacility(aged, ct);
            const cost = checkCost(mType, ct, { maintMod: aged.maintMod ?? 1, laborMult: maintLaborMult, hubFactor: fac.factor });
            if (runningCashForChecks >= cost) {
              runningCashForChecks -= cost; maintCheckSpend += cost;
              if (fac.base) claimSlot(mroSlots, fac.base);
              const dur = Math.max(1, checkDurationWeeks(mType, ct) - fac.weeksSaved);
              checksStarted.push({ id: aged.id, name: aged.name, tailNumber: aged.tailNumber ?? '', checkType: ct, cost, weeks: dur, base: fac.base });
              mroJobs.push({ kind: 'check', checkType: ct, aircraftId: aged.id, name: aged.name, tailNumber: aged.tailNumber ?? '', cost, base: fac.base, weeks: dur });
              return startCheck(aged, ct, dur);
            }
            aged = { ...aged, scheduledCheck: null };
          }
          const di = dueInfo(aged, mType, curAbsWeek);
          // Auto-scheduling: start a due check at planned cost/duration before
          // it can ever reach the regulator. Respects a player's own future
          // booking, skips leases about to be returned, and falls through to
          // the normal due/forced flow when cash can't cover the check.
          if (autoMaintActive && di.primaryDue && !aged.scheduledCheck) {
            const ct  = di.primaryDue;
            const dur = checkDurationWeeks(mType, ct);
            const leaseSoonReturn = aged.ownershipType === 'lease' && (aged.leaseRemainingWeeks ?? 999) <= dur + 4;
            if (!leaseSoonReturn) {
              const fac  = checkFacility(aged, ct);
              const cost = checkCost(mType, ct, { maintMod: aged.maintMod ?? 1, laborMult: maintLaborMult, hubFactor: fac.factor });
              if (runningCashForChecks >= cost) {
                runningCashForChecks -= cost; maintCheckSpend += cost;
                if (fac.base) claimSlot(mroSlots, fac.base);
                const durF = Math.max(1, dur - fac.weeksSaved);
                checksStarted.push({ id: aged.id, name: aged.name, tailNumber: aged.tailNumber ?? '', checkType: ct, cost, weeks: durF, auto: true, base: fac.base });
                mroJobs.push({ kind: 'check', checkType: ct, aircraftId: aged.id, name: aged.name, tailNumber: aged.tailNumber ?? '', cost, base: fac.base, weeks: durF, auto: true });
                return startCheck(aged, ct, durF);
              }
            }
          }
          if (di.forcedType) {
            const ct   = di.forcedType;
            const dur  = checkDurationWeeks(mType, ct);
            const leaseSoonReturn = aged.ownershipType === 'lease' && (aged.leaseRemainingWeeks ?? 999) <= dur + 4;
            if (!leaseSoonReturn) {
              // No jet-base discount on a forced grounding: the regulator parks it
              // where it stands, and the slot you'd have used was never booked.
              const cost = checkCost(mType, ct, { maintMod: aged.maintMod ?? 1, laborMult: maintLaborMult, hubFactor: aircraftHubMaintFactor(aged.id, coverPass.routes, coverPass.cargoRoutes, state.hubs), forced: true });
              maintCheckSpend += cost; forcedRepHit += FORCED_REP_HIT;
              checksForced.push({ id: aged.id, name: aged.name, tailNumber: aged.tailNumber ?? '', checkType: ct, cost, weeks: dur });
              mroJobs.push({ kind: 'check', checkType: ct, aircraftId: aged.id, name: aged.name, tailNumber: aged.tailNumber ?? '', cost, base: null, weeks: dur, forced: true });
              return startCheck(aged, ct, dur, { forced: true });
            }
          }
        }
        return aged;
      }).filter(Boolean);

      // 4. Build failure toasts
      const money = (n) => (n ?? 0).toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
      const failureToasts = newFailures.map(f => (f.writeOff ? {
        type:    'danger',
        title:   `\u2620\uFE0F Written off — ${f.aircraftName}`,
        message: `${f.label} on ${f.tailNumber || f.aircraftName} would cost more to repair than the airframe is worth. Removed from the fleet${f.payout > 0 ? `; hull insurance paid ${money(f.payout)}` : ''}.`,
        icon:    f.icon,
        duration: 11000,
      } : {
        type:    'danger',
        title:   `Mechanical Failure: ${f.aircraftName}`,
        message: `${f.label} detected on ${f.tailNumber || f.aircraftName}. Grounded for ${f.weeksGrounded} week${f.weeksGrounded !== 1 ? 's' : ''}. Repair ${money(f.repairCost)}${f.baseCode ? ` at your ${f.baseCode} base` : ''}.`,
        icon:    f.icon,
        duration: 8000,
      }));
      const baseOpenToasts = [
        ...baseBuild.opened.map(b => ({
          type: 'success', icon: '\uD83D\uDD27', duration: 9000,
          title: `\uD83D\uDD27 ${mroLevelDef(b.level)?.name ?? 'Jet base'} open — ${b.code}`,
          message: `Your ${b.code} base is certified and taking work. It reaches full effectiveness over the next six months.`,
        })),
        ...baseBuild.upgraded.map(b => ({
          type: 'success', icon: '\uD83D\uDD27', duration: 9000,
          title: `\uD83D\uDD27 ${b.code} upgraded to ${mroLevelDef(b.level)?.name ?? 'a higher tier'}`,
          message: `Heavier work can now be done in-house at ${b.code}.`,
        })),
        ...loungeBuild.opened.map(code => ({
          type: 'success', icon: '\uD83D\uDECB', duration: 9000,
          title: `\uD83D\uDECB Lounge open — ${code}`,
          message: `Your ${code} lounge is taking guests. Business travellers on routes through `
                 + `${code} now rate you higher, premium ground costs there have dropped, and you `
                 + `can sell day passes on the Ancillaries tab.`,
        })),
      ];

      // 5. Build recovery toasts (aircraft that just came back from grounding).
      //    Detect from the PRE-tick fleet (state.fleet): an aircraft recovers this
      //    week if it was grounded with ≤1 week left, since tickedFleetPre has
      //    already flipped it back to assigned/idle. Reading tickedFleet here would
      //    instead match aircraft that are STILL grounded for one more week.
      const recoveredAircraft = state.fleet
        .filter(a => a.status === 'grounded' && (a.groundedWeeksLeft ?? 1) <= 1)
        .filter(a => !failedIds.has(a.id)); // don't re-announce ones that just failed again
      const recoveryToasts = recoveredAircraft.map(a => ({
        type:    'success',
        title:   `Back in Service: ${a.name}`,
        message: `${a.tailNumber || a.name} has completed repairs and returned to service.`,
        icon:    '✅',
        duration: 5000,
      }));

      // Merge lease warnings, failures, and recovery toasts in (after agedFleet is built)
      const checkToasts = [
        ...baseOpenToasts,
        ...checksStarted.map(c => ({ type: 'info', title: `🔧 ${c.checkType} check ${c.auto ? 'auto-scheduled' : 'started'} — ${c.name}`, message: `${c.tailNumber || c.name} is in the shop for ${c.weeks} week${c.weeks !== 1 ? 's' : ''}. Cost: ${c.cost.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}.${c.auto ? ' Booked automatically by your maintenance team.' : ''}`, icon: '🔧', duration: 7000 })),
        ...checksForced.map(c => ({ type: 'danger', title: `⚠️ Forced grounding — ${c.name}`, message: `${c.tailNumber || c.name} blew past its ${c.checkType}-check window. Regulator-grounded ${c.weeks} week${c.weeks !== 1 ? 's' : ''}; rushed check ${c.cost.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}.`, icon: '⚠️', duration: 10000 })),
        ...completedChecks.map(c => ({ type: 'success', title: `✅ ${c.checkType} check complete — ${c.name}`, message: `${c.tailNumber || c.name} has returned to service.`, icon: '✅', duration: 5000 })),
      ];
      // Reserve cover toasts. Gap warnings fire once per incident: only for
      // broken tails that were NOT already listed as gapped last week.
      const prevGapIds = new Set((state.lastReport?.coverage?.gaps ?? []).map(g => g.original?.id));
      const fmtUsd = n => (n ?? 0).toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
      const coverToasts = [
        ...coverPass.coversStarted.map(c => ({
          type: 'info', icon: '🛡️', duration: 7000,
          title: `🛡️ Reserve dispatched — ${c.reserve.name}`,
          message: `${c.reserve.tailNumber || c.reserve.name} is covering ${c.routes} route${c.routes !== 1 ? 's' : ''} for ${c.original.name} while it's out of service.`,
        })),
        ...coverPass.coversEnded.map(c => ({
          type: 'success', icon: '🛡️', duration: 5000,
          title: `🛡️ Cover complete — ${c.reserve.name}`,
          message: `${c.original.name} is back; ${c.reserve.tailNumber || c.reserve.name} returned ${c.routes} route${c.routes !== 1 ? 's' : ''} and is standing by again.`,
        })),
        ...coverPass.coversPermanent.map(c => ({
          type: 'info', icon: '🛡️', duration: 7000,
          title: `🛡️ Cover made permanent — ${c.reserve.name}`,
          message: `${c.original.name} left the fleet mid-cover, so ${c.reserve.name} keeps its ${c.routes} route${c.routes !== 1 ? 's' : ''}.`,
        })),
        ...coverPass.coverGaps.filter(g => !prevGapIds.has(g.original?.id)).map(g => ({
          type: 'warning', icon: '🛡️', duration: 9000,
          title: `🛡️ No cover for ${g.original.name}`,
          message: `${g.routes} route${g.routes !== 1 ? 's' : ''} (~${fmtUsd(g.revenueAtRisk)}/wk) uncovered — ${g.reason === 'no-reserve'
            ? 'no same-type reserve is based at an airport these routes touch'
            : 'your matching reserve is out of weekly block hours'}.`,
        })),
      ];
      newToasts.push(...leaseWarningToasts, ...failureToasts, ...recoveryToasts, ...checkToasts, ...coverToasts);

      // Encroachment notifications — a rival entering or leaving one of your routes.
      for (const ev of encroachEvents ?? []) {
        if (ev.type === 'enter') {
          newToasts.push({
            type: 'warning', icon: '🪧',
            title: `${ev.name} entered ${ev.origin}–${ev.destination}`,
            message: `${ev.name} sees your fares on ${ev.origin}–${ev.destination} and has launched a competing service. Expect to lose some traffic unless you respond on price or frequency.`,
            duration: 9000,
          });
        } else if (ev.type === 'dormant') {
          newToasts.push({
            type: 'success', icon: '🏳️',
            title: `${ev.name} backed off ${ev.origin}–${ev.destination}`,
            message: `${ev.name} has stopped fighting you on price on ${ev.origin}–${ev.destination}. It's keeping a small presence there but no longer undercutting hard — raise fares too far and it'll come back swinging.`,
            duration: 8000,
          });
        } else if (ev.type === 'reawaken') {
          newToasts.push({
            type: 'warning', icon: '🪧',
            title: `${ev.name} is contesting ${ev.origin}–${ev.destination} again`,
            message: `Your fares on ${ev.origin}–${ev.destination} got fat again and ${ev.name} has resumed aggressive pricing and frequency on the route.`,
            duration: 9000,
          });
        } else if (ev.type === 'exit') {
          newToasts.push({
            type: 'success', icon: '🏳️',
            title: `Competitor withdrew from a route`,
            message: `A rival has pulled out of one of your routes — the lane is yours again.`,
            duration: 6000,
          });
        }
      }

      // Morale drifts toward target (based on pay) at 12% per week — but the
      // ceiling is what the money buys MINUS whatever the union is still
      // carrying from talks that went nowhere. Money alone used to be enough.
      // Crew pipeline: a state that has the flag but no headcount (a world that
      // just turned it on, a save from before it existed) is seeded to its
      // CURRENT fleet here — fully staffed, never fired.
      const currentLabor = state.crewPipeline
        ? ensureCrewSeeded(state.labor ?? DEFAULT_LABOR_STATE, state.fleet ?? [], (a) => getAircraftType(a.typeId))
        : (state.labor ?? DEFAULT_LABOR_STATE);
      const grievancePrev = relationsPrev.grievance ?? DEFAULT_LABOR_RELATIONS.grievance;
      const updatedLabor = {};
      // Crew pipeline (A7): the week we are advancing INTO — batches whose
      // training finishes by then join the line.
      const crewAbsWeek = absoluteWeek(state.year ?? 1, state.week ?? 1) + 1;
      for (const [id, g] of Object.entries(currentLabor)) {
        const target   = grievedMoraleTarget(moraleTarget(g.payMultiplier), grievancePrev?.[id]);
        const newMorale = g.morale + (target - g.morale) * 0.12;
        const morale = Math.max(5, Math.min(100, Math.round(newMorale * 10) / 10));
        if (!state.crewPipeline || g.headcount == null) {
          updatedLabor[id] = { ...g, morale };
          continue;
        }
        // Graduating classes join; the rest keep training.
        const pipeline = g.pipeline ?? [];
        let joined = 0;
        const stillTraining = [];
        for (const batch of pipeline) {
          if ((batch?.readyAbsWeek ?? 0) <= crewAbsWeek) joined += Number(batch?.count) || 0;
          else stillTraining.push(batch);
        }
        // Attrition is applied to the people already on the line, at a rate set
        // by pay and morale — this is what makes payMultiplier a retention
        // decision and not just a cost dial.
        const onLine = (Number(g.headcount) || 0) + joined;
        const left = onLine * crewAttritionRate(g.payMultiplier, morale);
        updatedLabor[id] = {
          ...g,
          morale,
          headcount: Math.max(0, Math.round((onLine - left) * 100) / 100),
          pipeline: stillTraining,
        };
      }

      // ── Labor relations: unrest, strikes, contract negotiations ──────────
      const relAbsWeek = absoluteWeek(state.year, state.week);
      let updatedRelations = {
        ...DEFAULT_LABOR_RELATIONS,
        ...relationsPrev,
        unrest: tickUnrest(updatedLabor, relationsPrev.unrest, grievancePrev),
        grievance: tickGrievance(grievancePrev),
        // Old saves: stagger each union's first contract demand.
        nextNegotiationAbsWeek: relationsPrev.nextNegotiationAbsWeek
          ?? scheduleFirstNegotiations(relAbsWeek),
      };

      // 1. Tick down an active strike; announce the end of the walkout.
      if (activeStrike) {
        const weeksLeft = activeStrike.weeksLeft - 1;
        if (weeksLeft <= 0) {
          const gName = LABOR_GROUP_MAP[activeStrike.group]?.name ?? activeStrike.group;
          updatedRelations.strike = null;
          updatedRelations.strikeCooldownUntilAbsWeek = relAbsWeek + STRIKE_COOLDOWN_WEEKS;
          updatedRelations.unrest = { ...updatedRelations.unrest, [activeStrike.group]: 20 };
          newToasts.push({
            type: 'info', icon: '🤝',
            title: `Strike over — ${gName} back at work`,
            message: `The ${gName.toLowerCase()} walkout has ended after ${activeStrike.totalWeeks} week${activeStrike.totalWeeks !== 1 ? 's' : ''}. Unrest has eased for now — fix the pay dispute or they will be back on the picket line.`,
            duration: 9000,
          });
        } else {
          updatedRelations.strike = { ...activeStrike, weeksLeft };
        }
      } else {
        // 2. No strike running — roll for a new walkout starting next week.
        const newStrike = rollStrike(
          updatedRelations.unrest, relAbsWeek, updatedRelations.strikeCooldownUntilAbsWeek);
        if (newStrike) {
          const gName = LABOR_GROUP_MAP[newStrike.group]?.name ?? newStrike.group;
          updatedRelations.strike = newStrike;
          newToasts.push({
            type: 'danger', icon: '✊',
            title: `STRIKE — ${gName} walk out`,
            message: `Your ${gName.toLowerCase()} are on strike over pay: ~${Math.round(newStrike.severity * 100)}% of flights cancelled for up to ${newStrike.totalWeeks} week${newStrike.totalWeeks !== 1 ? 's' : ''}. Settle in Operations → Labor (15% raise) or wait it out.`,
            duration: 12000,
          });
        }
      }

      // 3. Contract negotiations — tick the open one, or table a new demand.
      if (updatedRelations.negotiation
          && updatedRelations.negotiation.demandMultiplier
             <= (updatedLabor[updatedRelations.negotiation.group]?.payMultiplier ?? 1.0) + 1e-9) {
        // Save written before the ceiling fix: an open demand for the pay the
        // player is already on. There is no honest answer to it, so close it
        // quietly — no morale hit, no unrest, no lapse-into-refusal.
        const group = updatedRelations.negotiation.group;
        updatedRelations.negotiation = null;
        updatedRelations.nextNegotiationAbsWeek = {
          ...updatedRelations.nextNegotiationAbsWeek,
          [group]: scheduleNextNegotiation(relAbsWeek, false),
        };
      } else if (updatedRelations.negotiation) {
        const weeksLeft = updatedRelations.negotiation.weeksLeft - 1;
        if (weeksLeft <= 0) {
          // Ignored until it lapsed → counts as a refusal.
          const group = updatedRelations.negotiation.group;
          const gName = LABOR_GROUP_MAP[group]?.name ?? group;
          const fx    = NEGOTIATION_EFFECTS.refuse;
          updatedLabor[group] = {
            ...updatedLabor[group],
            morale: Math.max(5, Math.min(100, (updatedLabor[group]?.morale ?? 80) + fx.morale)),
          };
          updatedRelations.negotiation = null;
          updatedRelations.unrest = {
            ...updatedRelations.unrest,
            [group]: Math.max(0, Math.min(100, (updatedRelations.unrest[group] ?? 0) + fx.unrest)),
          };
          updatedRelations.nextNegotiationAbsWeek = {
            ...updatedRelations.nextNegotiationAbsWeek,
            [group]: scheduleNextNegotiation(relAbsWeek, true),
          };
          newToasts.push({
            type: 'danger', icon: '🚫',
            title: `${gName} pay demand ignored`,
            message: `The ${gName.toLowerCase()} contract demand lapsed without an answer. The union takes it as a refusal — morale has dropped and unrest is building.`,
            duration: 10000,
          });
        } else {
          updatedRelations.negotiation = { ...updatedRelations.negotiation, weeksLeft };
        }
      } else if (!updatedRelations.strike) {
        // Only one open demand at a time; unions hold off during a walkout.
        const due = Object.entries(updatedRelations.nextNegotiationAbsWeek)
          .filter(([, wk]) => relAbsWeek >= wk)
          .sort((a, b) => a[1] - b[1])[0];
        if (due) {
          const group      = due[0];
          const gName      = LABOR_GROUP_MAP[group]?.name ?? group;
          const currentPay = updatedLabor[group]?.payMultiplier ?? 1.0;
          const profitable = (state.financialHistory ?? []).slice(-12)
            .reduce((s, h) => s + (h.profit ?? 0), 0) > 0;
          const demand = negotiationDemand(currentPay, profitable);
          if (demand === null) {
            // Already paying the ceiling — the union has nothing to table, so
            // don't open a round of talks over the rate they're already on.
            // Quietly look in again later (pay may have been cut by then).
            updatedRelations.nextNegotiationAbsWeek = {
              ...updatedRelations.nextNegotiationAbsWeek,
              [group]: scheduleNextNegotiation(relAbsWeek, false),
            };
          } else {
            updatedRelations.negotiation = {
              group,
              demandMultiplier: demand,
              weeksLeft:  NEGOTIATION_RESPONSE_WEEKS,
              totalWeeks: NEGOTIATION_RESPONSE_WEEKS,
            };
            newToasts.push({
              type: 'warning', icon: '📜',
              title: `Contract talks — ${gName} table a pay demand`,
              message: `The ${gName.toLowerCase()} union demands ${demand.toFixed(2)}× market rate (currently ${currentPay.toFixed(2)}×). Respond in Operations → Labor within ${NEGOTIATION_RESPONSE_WEEKS} weeks — silence counts as a refusal.`,
              duration: 12000,
            });
          }
        }
      }

      // ── Loan repayments ──────────────────────────────────────────────────
      const currentLoans = state.loans ?? [];
      let totalLoanPayments = 0;
      let totalLoanInterest = 0;
      const updatedLoans = currentLoans
        .map(loan => {
          if (loan.weeksRemaining <= 0) return null;
          const weeklyRate = loan.interestRate / 52;
          const interestThisWeek = Math.round(outstandingBalance(loan) * weeklyRate);
          totalLoanPayments += loan.weeklyPayment;
          totalLoanInterest += interestThisWeek;
          return {
            ...loan,
            weeksRemaining:    loan.weeksRemaining - 1,
            totalInterestPaid: (loan.totalInterestPaid ?? 0) + interestThisWeek,
          };
        })
        .filter(Boolean)
        .filter(l => l.weeksRemaining > 0);

      // Corporate income tax — 21% on positive EBT (earnings before tax).
      // EBT = operating profit − depreciation − loan INTEREST. Loan principal is a
      // balance-sheet repayment, NOT a deductible expense, so it is excluded from the
      // tax base (previously the full loan payment was deducted, which under-taxed
      // leveraged airlines and turned debt into a tax shelter).
      const CORPORATE_TAX_RATE = 0.21;
      const weeklyDepreciation = fleetWeeklyDepreciation(state.fleet);
      // Seasonal reactivation fees are a deductible operating expense, treated like
      // lease redelivery: they reduce the tax base and flow through the weekly P&L
      // (so the debrief shows them as a cost line and cash reconciles exactly).
      //
      // A returned security deposit is a return of capital, not income: the money
      // was paid out at order time without ever passing through the P&L, so it
      // must not be taxed on the way back — leaseDepositRefund is deliberately
      // absent from taxableIncome. It IS cash, though, so it belongs in
      // preTaxProfit below — this game's P&L card is walked row by row against
      // the week's cash movement, and a movement with no row is a reconciliation
      // failure by design.
      const taxableIncome   = adjustedCashDelta - weeklyDepreciation - totalLoanInterest - leaseRedeliveryCost - seasonalReactivationCost - maintCheckSpend - aogSpend + aogInsurance;
      const corporateTax    = Math.round(Math.max(0, taxableIncome) * CORPORATE_TAX_RATE);
      // Cash movement: operating cash − full loan payment − reactivation fees − tax,
      // plus any security deposits handed back with returned airframes.
      const preTaxProfit    = adjustedCashDelta - totalLoanPayments - leaseRedeliveryCost - seasonalReactivationCost - maintCheckSpend - aogSpend + aogInsurance + leaseDepositRefund;
      const newCash = state.cash + preTaxProfit - corporateTax;
      let newWeek = state.week + 1;
      let newYear = state.year;
      if (newWeek > 52) { newWeek = 1; newYear++; }

      // Advance competitor networks (graceful fallback for old saves missing competitors)
      const currentCompetitors = state.competitors
        ?? sampleAndInitializeCompetitors(25);
      const weekNumber = (state.year - 1) * 52 + state.week;

      // Adaptive competitor AI: expansion, cuts, capacity responses, pricing
      // reactions, distress/fire sales, bankruptcies, mergers, and startups.
      const aiPlayerRoutes = state.routes.map(r => ({
        origin:          r.origin,
        destination:     r.destination,
        weeklyFrequency: r.weeklyFrequency,
        ticketPrice:     state.routePricing?.[routePairKey(r.origin, r.destination)]?.economy
                           ?? r.ticketPrice,
      }));
      // In multiplayer the "competitors" are real humans injected by the server:
      // they manage their own networks, so the AI never moves them, no AI
      // startups spawn, and no scripted fare wars / bankruptcies / mergers fire.
      const { competitors: aiCompetitors, events: competitorEvents } = isMultiplayerWorld
        ? { competitors: currentCompetitors, events: [] }
        : tickCompetitorAI(currentCompetitors, {
          weekNumber,
          month:           gameMonth,
          playerRoutes:    aiPlayerRoutes,
          playerHubs:      Object.keys(state.hubs ?? {}),
          playerMarketCap: state.marketCap ?? 0,
          playerCampaignSpend: state.targetedMarketing ?? {},
        });

      // Simulate competitor networks, accumulate cash, and track profit history
      // for market cap. Demand on each city pair is shared across every carrier
      // (player included) flying it, and cash-rich carriers pay out dividends
      // instead of hoarding (keeps late-game acquisitions attainable).
      const approxMonth = gameMonth;
      const compPairCounts = buildPairIncumbents(aiCompetitors, state.routes);
      const updatedCompetitors = aiCompetitors.map(c => {
        const stats            = computeCompetitorWeeklyStats(c, approxMonth, compPairCounts);
        const newCompCash      = (c.cash ?? 0) + retainedProfit(c.cash ?? 0, stats.weeklyProfit);
        const newProfitHistory = [...(c.profitHistory ?? []), stats.weeklyProfit].slice(-12);
        // Valuation v2 for AI carriers too: same convergence/clamp/noise path so
        // their prices are chartable and tradeable without single-week teleports.
        // AI fleets/debt stay unvalued (their cash is semi-abstract and already
        // stands in for the balance sheet) — symmetric across all AI carriers.
        const { marketCap: compMarketCap, sharePrice: compSharePrice } =
          computeMarketCap(newProfitHistory, newCompCash, c.baseQualityScore, {
            prevMarketCap: c.marketCap ?? null,
            noise:         (Math.random() * 2 - 1) * VALUATION.NOISE_PCT,
            revenueHint:   stats.weeklyRevenue ?? 0,
            marketFactor,
          });
        return {
          ...c,
          weeklyStats:   stats,
          cash:          newCompCash,
          profitHistory: newProfitHistory,
          marketCap:     compMarketCap,
          sharePrice:    compSharePrice,
          // Rolling price series for the Stocks tab chart (solo AI carriers; in
          // multiplayer the server derives the equivalent from statsHistory).
          priceHistory:  [...(c.priceHistory ?? []), compSharePrice].slice(-STOCK_MARKET.SHARE_PRICE_HISTORY_WEEKS),
        };
      });

      // Dramatic market news → toasts (launch/boost/cut stay in the debrief feed).
      for (const ev of competitorEvents) {
        if (ev.type === 'bankrupt') {
          newToasts.push({ type: 'warning', title: `✈️ ${ev.name} Collapses`, message: ev.description, duration: 9000 });
        } else if (ev.type === 'merger') {
          newToasts.push({ type: 'info', title: '🤝 Industry Consolidation', message: ev.description, duration: 9000 });
        } else if (ev.type === 'startup') {
          newToasts.push({ type: 'info', title: '🛫 New Entrant', message: ev.description, duration: 8000 });
        } else if (ev.type === 'fireSale') {
          newToasts.push({ type: 'info', title: `💸 ${ev.name} In Trouble`, message: `${ev.description} Check the Competition tab for a discounted acquisition.`, duration: 9000 });
        } else if (ev.type === 'fareWar') {
          newToasts.push({ type: 'danger', title: `🔥 Fare War — ${ev.name}`, message: ev.description, duration: 10000 });
        } else if (ev.type === 'fareWarEnd') {
          newToasts.push({ type: 'info', title: `🕊️ Fare War Over — ${ev.name}`, message: ev.description, duration: 7000 });
        }
      }

      // Victory can now arrive without a final acquisition: if the last rival
      // goes bankrupt or is absorbed, the skies belong to the player.
      const rivalsGone = updatedCompetitors.length === 0 && (currentCompetitors?.length ?? 0) > 0;
      const lastRivalName = rivalsGone
        ? (competitorEvents.find(e => e.type === 'bankrupt' || e.type === 'merger')?.name ?? null)
        : null;

      // ── Tick codeshare agreement durations (expire old ones) ─────────────
      // A codeshare only survives while the PARTNER does. The term countdown
      // never checked that, so an agreement with a carrier that went bankrupt,
      // abandoned its world or was re-founded kept charging its weekly fee — and
      // kept granting connectivity through buildPartnershipMap — for the rest of
      // its 52-week term, against an airline that no longer flies anything.
      // Same test the delisting sweep below uses: gone from the rival set is
      // gone. Left deliberately as an identity check rather than a
      // poolKeyOf-style normalisation, so a RE-FOUNDED partner (new generation
      // id) correctly terminates the deal the old company signed.
      const partnerStillFlying = new Set(updatedCompetitors.map(c => c.id));
      const partnerGoneCodeshares = (state.codeshareAgreements ?? [])
        .filter(a => a.weeksRemaining > 1 && !partnerStillFlying.has(a.competitorId));
      for (const a of partnerGoneCodeshares) {
        newToasts.push({
          type:    'warning',
          title:   `Codeshare Ended — ${a.competitorName}`,
          message: `${a.competitorName} no longer operates. The agreement is terminated and its weekly fee has stopped.`,
          icon:    '🤝',
          duration: 8000,
        });
      }

      const tickedCodeshares = (state.codeshareAgreements ?? [])
        .map(a => ({ ...a, weeksRemaining: a.weeksRemaining - 1 }))
        .filter(a => a.weeksRemaining > 0 && partnerStillFlying.has(a.competitorId));

      // Notify about newly expired codeshares
      const expiredCodeshares = (state.codeshareAgreements ?? []).filter(a => a.weeksRemaining <= 1);
      for (const a of expiredCodeshares) {
        newToasts.push({
          type:    'info',
          title:   `Codeshare Expired — ${a.competitorName}`,
          message: `Your codeshare agreement with ${a.competitorName} has concluded after 1 year. Renew it in Alliances.`,
          icon:    '🤝',
          duration: 6000,
        });
      }

      // ── Hub construction countdown + throughput history ──────────────────
      const hubConstructionPrev = state.hubConstruction ?? {};
      const newHubConstruction  = {};
      let   hubsAfterBuild      = state.hubs ?? {};
      for (const [code, c] of Object.entries(hubConstructionPrev)) {
        const weeksLeft = (c.weeksLeft ?? 1) - 1;
        if (weeksLeft <= 0) {
          const tName = HUB_TIERS[c.targetTier]?.name ?? 'Hub';
          hubsAfterBuild = {
            ...hubsAfterBuild,
            [code]: { tier: c.targetTier, tierSince: absoluteWeek(newYear, newWeek) },
          };
          newToasts.push({
            type: 'success',
            title: `🏗️ ${tName} Complete — ${code}`,
            message: `Construction at ${code} is finished. ${tName} benefits (connecting traffic, quality, cost efficiencies) are now active.`,
            duration: 9000,
          });
        } else {
          newHubConstruction[code] = { ...c, weeksLeft };
        }
      }
      // Rolling 4-week connecting throughput per designated hub (T3 prerequisite)
      const prevThroughput = state.hubThroughput ?? {};
      const newHubThroughput = {};
      for (const code of Object.keys(hubsAfterBuild)) {
        newHubThroughput[code] = [
          ...(prevThroughput[code] ?? []),
          report.hubThroughput?.[code] ?? 0,
        ].slice(-4);
      }

      // ── Bankruptcy condition tracking ─────────────────────────────────────
      // Condition 1: missed loan payment = week where loans were due AND cash went negative
      const missedThisWeek = totalLoanPayments > 0 && newCash < 0;
      const newMissedLoanPayments = (state.missedLoanPayments ?? 0) + (missedThisWeek ? 1 : 0);

      // Condition 2: consecutive negative weeks (resets on recovery)
      const newConsecutiveNegativeWeeks = newCash < 0
        ? (state.consecutiveNegativeWeeks ?? 0) + 1
        : 0;

      // Warning toasts
      if (missedThisWeek && newMissedLoanPayments === 1) {
        newToasts.push({ type: 'danger', title: '⚠️ Missed Loan Payment (1/3)', message: "You missed a loan payment. Miss 2 more and your airline will be declared bankrupt.", duration: 9000 });
      }
      if (missedThisWeek && newMissedLoanPayments === 2) {
        newToasts.push({ type: 'danger', title: '🚨 Missed Loan Payment (2/3)', message: "Critical: one more missed payment and bankruptcy will be triggered.", duration: 10000 });
      }
      if (newConsecutiveNegativeWeeks === 3) {
        newToasts.push({ type: 'warning', title: '⚠️ Cash Warning: 3 Weeks Negative', message: "Your cash has been negative for 3 consecutive weeks. 6 weeks triggers bankruptcy.", duration: 9000 });
      }
      if (newConsecutiveNegativeWeeks === 5) {
        newToasts.push({ type: 'danger', title: '🚨 Final Warning: 5 Weeks Negative', message: "One more week in the red and your airline will be declared bankrupt.", duration: 10000 });
      }

      // Determine bankruptcy and reason
      let newPhase = state.phase;
      let bankruptcyReason = state.bankruptcyReason ?? null;
      if (newMissedLoanPayments >= 3) {
        newPhase = 'bankrupt';
        bankruptcyReason = 'missed_loans';
      } else if (newConsecutiveNegativeWeeks >= 6) {
        newPhase = 'bankrupt';
        bankruptcyReason = 'consecutive_negative';
      }

      const historyEntry = {
        label:       (() => { const d = weekToGameDate(state.week); return `${d.monthName} W${d.weekInMonth} ${shortYearLabel(state)}`; })(),
        week:        state.week,
        year:        state.year,
        cash:        newCash,
        revenue:     report.totalRevenue,
        passengers:  report.totalPassengers ?? 0,   // for the loyalty smoothed pax base
        leases:      report.totalLeases,
        maintenance: report.totalMaintenance,
        fuel:        report.totalFuel,
        crew:        report.totalCrew,
        quality:     report.totalQuality,
        landingFees:     report.totalLandingFees    ?? 0,
        catering:        report.totalCatering          ?? 0,
        cateringRevenue: report.totalCateringRevenue   ?? 0,
        ancillaryRevenue: report.totalAncillaryRevenue ?? 0,
        ancillaryCost:    report.totalAncillaryCost    ?? 0,
        groundHandling:  report.totalGroundHandling    ?? 0,
        distribution:    report.totalDistributionCost  ?? 0,
        layover:         report.totalLayover           ?? 0,
        compensation:    report.totalCompensation   ?? 0,
        gates:           report.totalGateFees       ?? 0,
        labor:           report.totalLaborCosts     ?? 0,
        familyCosts:     report.totalFamilyBaseCosts ?? 0,
        hqCost:          report.totalHQCost         ?? 0,
        insurance:       report.totalInsurance      ?? 0,
        marketing:       report.totalMarketingSpend ?? 0,
        hubInvestment:   report.totalHubInvestment  ?? 0,
        loyalty:         report.totalLoyaltyCost    ?? 0,
        partnerRevenue:  report.totalPartnerRevenue ?? 0,
        partnerFees:     report.totalPartnerFees    ?? 0,
        cargoRevenue:    report.totalCargoRevenue   ?? 0,
        cargoProfit:     report.totalCargoProfit    ?? 0,
        cargoTonnes:     report.totalCargoTonnes    ?? 0,
        loanPayments:       totalLoanPayments,
        loanInterest:       totalLoanInterest,
        leaseRedelivery:    leaseRedeliveryCost,
        leaseDepositReturned: leaseDepositRefund,
        seasonalReactivation: seasonalReactivationCost,
        corporateTax:       corporateTax,
        depreciation:       weeklyDepreciation,
        // Active-event demand swing applied to revenue this week. Folded into the
        // chart's revenue line so profit = revenue − cost reconciles visually.
        eventDemandAdj:     Math.round(eventDemandAdj),
        // Revenue forfeited to cancelled flights during a labor strike.
        strikeLoss:         strikeRevenueLoss,
        strikeVariableSaved,
        totalCost:          report.totalCost + totalLoanPayments + leaseRedeliveryCost + seasonalReactivationCost + maintCheckSpend + aogSpend,
        // profit = actual cash change this week (after tax, matches newCash delta)
        profit:             preTaxProfit - corporateTax,
        fuelIndex:          currentFuelIndex,
        // Earned passenger satisfaction (0-100) and this week's reputation score,
        // so the Dashboard can trend them. Older history entries lack these - any
        // consumer must guard for null (the trend simply builds up going forward).
        satisfaction:       report.satisfaction ?? state.satisfaction ?? null,
        reputationScore:    report.reputationScore ?? null,
        // World events active during this week — the Dashboard's financial
        // history chart uses these for event markers + hover tooltips.
        events:             allEvents.map(e => ({ id: e.id, name: e.name, icon: e.icon, color: e.color })),
        // Per-route revenue breakdown for Finance page prior-week column
        routeRevenues:      Object.fromEntries(
          (report.routeResults ?? []).map(r => [r.routeId, r.revenue])
        ),
      };
      const newHistory = [...state.financialHistory, historyEntry].slice(-52);

      // ── Stock portfolio: mark to market + delisting liquidations ─────────────
      // Holdings are valued against the PREVIOUS tick's prices (state.competitors
      // as injected/stored at tick start), never this week's — one pass, order-
      // independent, and immune to A-holds-B-holds-A circularity. A held airline
      // that vanished this week (MP: purged/abandoned rival; solo: AI bankruptcy
      // or merger) is force-liquidated at a haircut of its last known price.
      const prevPriceOf = new Map((state.competitors ?? []).map(c =>
        [c.id, (c.sharePrice ?? (c.marketCap ?? 0) / sharesOf(c)) || 0]));
      const liveCompIds = new Set(updatedCompetitors.map(c => c.id));
      const prevPortfolio  = state.portfolio ?? emptyPortfolio();
      const newHoldings    = {};
      let   portfolioValue = 0;
      let   delistProceeds = 0;
      let   delistRealized = 0;
      let   delistTax      = 0;
      for (const [heldId, h] of Object.entries(prevPortfolio.holdings ?? {})) {
        if (!(h?.shares > 0)) continue;
        const lastPrice = prevPriceOf.get(heldId) ?? h.lastPrice ?? 0;
        if (!liveCompIds.has(heldId)) {
          // Delisted this week — a forced liquidation at a haircut to the last
          // marked price. Headwinds is humans-only, so the old solo-AI branches
          // (bankruptcy 50%, AI-vs-AI merger at par) were dead code and are gone:
          // every delisting now settles at the same rate.
          const haircut = STOCK_MARKET.DELIST_HAIRCUT;
          const payout  = Math.round(h.shares * lastPrice * haircut);
          const gain    = payout - (h.costBasis ?? 0);
          const dTax    = capitalGainsTax(gain);
          delistProceeds += payout - dTax;
          delistRealized += gain - dTax;
          delistTax      += dTax;
          newToasts.push({
            type:     'warning',
            icon:     '📉',
            title:    `${h.name ?? 'A rival'} delisted`,
            message:  `Your ${h.shares.toLocaleString()} shares were liquidated at a ${Math.round((1 - haircut) * 100)}% haircut — ${(payout - dTax).toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })} credited${dTax > 0 ? ' after tax' : ''}.`,
            duration: 9000,
          });
          continue;
        }
        const value = Math.round(h.shares * lastPrice);
        portfolioValue += value;
        newHoldings[heldId] = { ...h, lastPrice, lastValue: value };
      }
      const newPortfolio = {
        holdings:         newHoldings,
        taxPaid:          (prevPortfolio.taxPaid ?? 0) + delistTax,
        realizedPnL:      (prevPortfolio.realizedPnL ?? 0) + delistRealized,
        realizedThisWeek: 0,   // folded into this week's P&L line below
        lastValuation:    portfolioValue,
      };
      const cashAfterInvesting = newCash + delistProceeds;
      // Below-the-line P&L: realized trading gains/losses this week (sales made
      // since the last tick + any forced liquidations just now). Recorded on the
      // history entry for the Finance P&L, but NEVER part of `profit` — letting
      // trades into operating profit would feed them back through the ×52 × P/E
      // valuation loop the algorithm rework just closed.
      historyEntry.investmentIncome = (prevPortfolio.realizedThisWeek ?? 0) + delistRealized
        + Math.max(0, Math.round(Number(action.incomingDividends) || 0));

      // ── Dividends ────────────────────────────────────────────────────────────
      // A standing policy paid every DIVIDEND_PERIOD_WEEKS out of trailing-quarter
      // profit. Only shares held OUTSIDE the founder block are paid: paying
      // yourself is a wash, and skipping it means a dividend costs you in
      // proportion to how much of the company you have actually sold.
      //
      // The cash leaves here. WHO receives it is settled by the server, which is
      // the only place that knows every holder (see tickService + DividendCredit) —
      // rival players get a real cross-player transfer, and the slice held by
      // outside investors leaves the world as a sink. A dividend can therefore
      // never create money; it only moves or destroys it.
      const divEquity   = state.equity ?? emptyEquity();
      const divShares   = sharesOf(state);
      const divFounder  = Math.max(0, Math.min(divShares, Number(divEquity.founderShares ?? 0)));
      const divPayable  = Math.max(0, divShares - divFounder);
      const divPolicy   = Number(divEquity.dividendPolicy ?? 0);
      const divPeriodWk = absoluteWeek(newYear, newWeek);
      let   dividendPaid = 0, dividendPerSh = 0, dividendSkipped = null;

      if (divPolicy > 0 && divEquity.isPublic && divPayable > 0
          && divPeriodWk % CAPITAL.DIVIDEND_PERIOD_WEEKS === 0) {
        const trailing = newHistory.slice(-CAPITAL.DIVIDEND_TRAILING_WEEKS)
          .reduce((sum, h) => sum + (h.profit ?? 0), 0);
        const perSh = dividendPerShare(trailing, divPolicy, divShares);
        const total = Math.round(perSh * divPayable);
        // Never pay into insolvency, and never pay out of a losing quarter.
        const recentCost = newHistory.slice(-4);
        const weeklyCost = recentCost.length
          ? recentCost.reduce((sum, h) => sum + (h.totalCost ?? 0), 0) / recentCost.length
          : 0;
        if (trailing <= 0) {
          dividendSkipped = 'a loss-making quarter';
        } else if (total > 0 && cashAfterInvesting - total < weeklyCost * CAPITAL.MIN_CASH_WEEKS_COVER) {
          dividendSkipped = 'insufficient cash cover';
        } else if (total > 0) {
          dividendPaid  = total;
          dividendPerSh = perSh;
        }
      }

      if (dividendPaid > 0) {
        newToasts.push({
          type: 'success', icon: '💵',
          title: 'Dividend paid',
          message: `$${dividendPerSh.toFixed(4)} per share on ${divPayable.toLocaleString()} publicly held shares — `
                 + `${dividendPaid.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })} distributed to shareholders.`,
          duration: 10000,
        });
      } else if (dividendSkipped) {
        newToasts.push({
          type: 'warning', icon: '✂️',
          title: 'Dividend suspended',
          message: `No dividend this quarter — ${dividendSkipped}.`,
          duration: 10000,
        });
      }

      // Annual allowance reset: the offering and buyback throttles are per game year.
      const divYearRollover = newWeek === 1 && newYear !== state.year;
      const nextEquity = {
        ...divEquity,
        ...(dividendPerSh > 0
          ? { cumDividendsPerShare: (divEquity.cumDividendsPerShare ?? 0) + dividendPerSh }
          : {}),
        ...(divYearRollover ? { offeringsThisYear: 0, buybacksThisYear: 0 } : {}),
      };

      const cashAfterDividend = cashAfterInvesting - dividendPaid
        + Math.max(0, Math.round(Number(action.incomingDividends) || 0));

      // ── Player market cap (valuation v2) ─────────────────────────────────────
      // Fundamentals (net book incl. fleet NAV & portfolio, minus debt; earnings
      // with a confidence ramp) with convergence + clamp + noise. Multiplayer
      // noise is server-seeded and injected via the tick action so every client
      // sees the same authoritative print and none can predict or re-roll it;
      // solo rolls locally.
      const valuationNoise = isMultiplayerWorld
        ? (Number.isFinite(action.valuationNoise) ? action.valuationNoise : 0)
        : (Math.random() * 2 - 1) * VALUATION.NOISE_PCT;
      const recentRevWeeks = newHistory.slice(-6);
      const revenueHint    = recentRevWeeks.length
        ? recentRevWeeks.reduce((s, h) => s + (h.revenue ?? 0), 0) / recentRevWeeks.length
        : 0;
      const playerProfitHistory = newHistory.slice(-12).map(h => h.profit);
      // Every airline's published cap is smoothed, listed or not. A private
      // airline USED to publish its raw fair value straight (prevMarketCap: null
      // took computeMarketCap's cold branch), so it skipped convergence, the move
      // clamp and the noise term entirely — which is how a private startup printed
      // a +8383% weekly move to every rival on the Markets tab. The reason that
      // was done is still valid, though: pricing an IPO off a smoothed series that
      // had been chasing a fast-growing fair value meant floating a quarter of the
      // company for a rounding error. So the fair value is now KEPT (state.fairValue)
      // rather than published, and GO_PUBLIC prices the listing off it — see below.
      const { marketCap: newMarketCap, sharePrice: newSharePrice, fairValue: newFairValue } =
        computeMarketCap(playerProfitHistory, cashAfterDividend, state.awareness ?? 5, {
          fleetNAV:       fleetNAVOf(agedFleet, curAbsWeek),
          debt:           loanOutstanding(updatedLoans),
          portfolioValue,
          prevMarketCap:  state.marketCap ?? null,
          noise:          valuationNoise,
          revenueHint,
          marketFactor,
          shares: sharesOf(state),
        });

      // ── Long-term statistics series (Finance ▸ Statistics page) ──────────────
      // A compact per-week KPI record retained far longer than financialHistory
      // (which stays capped at 52 weeks). Only lightweight scalars — no per-route
      // maps — so the save / MP-sync footprint stays small even over decades.
      const statAbsWeek  = (state.year - 1) * 52 + state.week;
      const statRouteById = new Map((state.routes ?? []).map(r => [r.id, r]));
      const statCargoById = new Map((state.cargoRoutes ?? []).map(r => [r.id, r]));
      const statDest      = new Set();
      let   statFlights = 0, statAsk = 0, statRpk = 0, statPaxRev = 0;
      for (const rr of (report.routeResults ?? [])) {
        const r = statRouteById.get(rr.routeId);
        if (r) { statDest.add(r.origin); statDest.add(r.destination); statFlights += (r.weeklyFrequency ?? 0); }
        const seats = rr.configuredSeatsOneWay ?? 0;
        const dist  = rr.distance ?? 0;
        const pax   = rr.passengers ?? 0;
        statAsk    += seats * dist * 2;   // ASK — both directions
        statRpk    += pax   * dist * 2;   // RPK — both directions
        statPaxRev += rr.revenue ?? 0;    // passenger route revenue (incl. connecting)
      }
      for (const cr of (report.cargoRouteResults ?? [])) {
        const r = statCargoById.get(cr.routeId);
        if (r) { statDest.add(r.origin); statDest.add(r.destination); statFlights += (r.weeklyFrequency ?? 0); }
      }
      const statsEntry = {
        label:   historyEntry.label,
        week:    state.week,
        year:    state.year,
        absWeek: statAbsWeek,
        // Passenger segmentation (one-way boardings per direction; ×2 for round trips)
        paxOrganic:     report.paxOrganic    ?? report.totalPassengers ?? 0,
        paxConnecting:  report.paxConnecting ?? 0,
        paxInterline:   report.paxInterline  ?? 0,
        // Network size
        routes:         (report.routeResults?.length ?? 0) + (report.cargoRouteResults?.length ?? 0),
        flights:        statFlights,
        destinations:   statDest.size,
        fleet:          agedFleet?.length ?? state.fleet?.length ?? 0,
        // Financials (mirror historyEntry so charts reconcile with the P&L)
        // report.totalRevenue is ALREADY the grand total: the simulator folds every
        // freighter's revenue into it inside the cargo loop and then returns it with
        // partner O&D added. totalCargoRevenue and totalPartnerRevenue are breakdowns
        // OF that money, not additions to it — the P&L card says so too. Adding cargo
        // back on here counted every freight dollar twice, so a cargo-heavy airline's
        // "Weekly Revenue" tile disagreed with its own P&L and the Revenue-mix chart's
        // Passenger band (revenue − partner − cargo) absorbed the surplus as pax money.
        revenue:        report.totalRevenue ?? 0,   // grand total operating revenue (incl. cargo + partner)
        partnerRevenue: report.totalPartnerRevenue ?? 0,
        cargoRevenue:   report.totalCargoRevenue   ?? 0,
        cost:           historyEntry.totalCost,
        profit:         historyEntry.profit,
        cash:           cashAfterDividend,
        // Markets: this week's authoritative share price (drives price charts —
        // own chart and, via the server rival payload, what rivals see) and the
        // mark-to-market value of the stock portfolio.
        // A private airline records NO price. There is no market in it, so there is
        // no price series to chart — which is the cleanest form of the fix: a
        // newly listed airline's chart starts at its listing instead of carrying a
        // pre-listing series nobody could have traded on. Rival payloads and every
        // price readout already skip non-numeric entries.
        sharePrice:     nextEquity?.isPublic === false ? null : newSharePrice,
        svps:           svpsOf({ sharePrice: newSharePrice, equity: nextEquity }),
        shares:         sharesOf(state),
        portfolioValue,
        marketIndex:    currentMarketIndex,
        // Efficiency
        loadFactor:     statAsk > 0 ? +(statRpk / statAsk).toFixed(4) : 0,
        yield:          statRpk > 0 ? +(statPaxRev / statRpk).toFixed(4) : 0,   // $ per RPK
        ask:            Math.round(statAsk),
      };
      const statsCap = state.multiplayer ? STATS_HISTORY_CAP_MP : STATS_HISTORY_CAP;
      const newStats = [...(state.statsHistory ?? []), statsEntry].slice(-statsCap);

      // ── Era worlds: yearly stats rollup (ERA_MODE_PLAN.md §8) ────────────────
      // The MP weekly series is capped at 260 weeks for egress reasons, which
      // permanently discards all but 5 years — fatal for a mode whose selling
      // point is the sweep of a century. One compact row per COMPLETED game
      // year (~100 rows for the full 1950→2050 run — a rounding error against
      // the blob) keeps the long arc. Era-gated so classic blobs, and the
      // golden master, are byte-identical.
      let newStatsYearly = state.statsHistoryYearly;
      if (state.startYear != null && newWeek === 1 && newYear === state.year + 1) {
        const yrRows = newHistory.filter(h => h.year === state.year);
        const ysum = (k) => Math.round(yrRows.reduce((s, h) => s + (h[k] ?? 0), 0));
        newStatsYearly = [...(state.statsHistoryYearly ?? []), {
          year:         state.year,                              // ordinal, like every stored week
          calendarYear: state.startYear + state.year - 1,
          label:        String(state.startYear + state.year - 1),
          revenue:      ysum('revenue'),
          profit:       ysum('profit'),
          passengers:   ysum('passengers'),
          cargoRevenue: ysum('cargoRevenue'),
          cash:         newCash,
          marketCap:    newMarketCap,
          fleet:        agedFleet.filter(a => a.status !== 'retired').length,
          routes:       state.routes.length,
          fuelIndex:    currentFuelIndex,
        }].slice(-150);
      }

      // ── Board objectives check ───────────────────────────────────────────────
      // Multiplayer worlds always run the compact starter board (10 objectives).
      // Worlds created before objectives shipped have objectivesEnabled: false —
      // force-enable here; the initialObjectivesForState fallback below silently
      // pre-marks anything already achieved, so there is NO back-pay: only new
      // progress pays out (same rule as solo old-save upgrades).
      const objectiveSet      = state.multiplayer ? 'multiplayer' : undefined;
      const objectivesEnabled = state.multiplayer ? true : (state.objectivesEnabled ?? true);

      // Cumulative passengers over the whole game — drives the starter pax
      // milestones (10K/100K/1M). Existing saves start counting from 0 here.
      const paxAllTime = (state.paxAllTime ?? 0) + (report.totalPassengers ?? 0);

      // Era worlds: objective thresholds and rewards scale with the era
      // (ERA_MODE_PLAN.md §4). Classic worlds pass no scalers — identity.
      const _objCy  = calendarYear(state);
      const _objRev = eraRevenueScale(_objCy);
      const _objPax = eraPaxScale(_objCy);
      const _objCap = eraCapitalScale(_objCy) ?? 1;

      const objectiveSnap = {
        ...(_objRev != null ? {
          M: (x) => Math.max(1_000, Math.round(x * _objRev / 1_000) * 1_000),
          P: (x) => Math.max(100,   Math.round(x * _objPax / 100)   * 100),
        } : {}),
        routes:           state.routes,   // current routes (weeksOpen not yet incremented — fine for checks)
        fleet:            agedFleet,      // fleet after aging tick, before deliveries
        gates:            state.gates ?? {},
        hubs:             state.hubs ?? {},
        paxAllTime,
        financialHistory: newHistory,
        lastReport:       report,
        weekProfit:       preTaxProfit - corporateTax,
        cash:             cashAfterDividend,
        marketCap:        newMarketCap,
        fairValue:        newFairValue,
        year:             newYear,
        week:             newWeek,
      };

      // For old saves that pre-date objectives: silently pre-mark already-met
      // objectives so the player only earns credit for future achievements.
      const currentObjectives = !objectivesEnabled
        ? []
        : state.objectives?.length
          ? state.objectives
          : initialObjectivesForState(objectiveSnap, objectiveSet);

      let objectiveCashBonus = 0;
      let updatedObjectives = currentObjectives;

      if (objectivesEnabled && currentObjectives.length > 0) {
        const { newlyCompleted } = checkObjectives(currentObjectives, objectiveSnap);
        updatedObjectives = currentObjectives.map(obj => {
          if (!newlyCompleted.includes(obj.id)) return obj;
          const tmpl = getObjective(obj.id);
          const scaledReward = Math.round((tmpl?.reward ?? 0) * _objCap);
          objectiveCashBonus += scaledReward;
          newToasts.push({
            type:     'success',
            title:    `🏅 Objective Complete — ${tmpl?.title ?? obj.id}`,
            message:  `${objectiveDesc(tmpl, objectiveSnap.M, objectiveSnap.P)} · Board reward: +${scaledReward.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}`,
            icon:     tmpl?.icon ?? '🏅',
            duration: 9000,
          });
          return { ...obj, completed: true, completedWeek: state.week, completedYear: state.year };
        });
      }

      // ── Deliver pending aircraft orders ──────────────────────────────────────
      const newAbsWeek      = absoluteWeek(newYear, newWeek);
      const allPending      = state.pendingOrders ?? [];
      const toDeliver       = allPending.filter(o => o.deliverAbsWeek <= newAbsWeek);
      const remainingOrders = allPending.filter(o => o.deliverAbsWeek >  newAbsWeek);

      // Build delivered aircraft, accumulating used tail numbers to avoid collisions
      const deliveredAircraft = [];
      for (const order of toDeliver) {
        const ordType    = getAircraftType(order.typeId);
        const usedTails  = [
          ...agedFleet.map(a => a.tailNumber),
          ...deliveredAircraft.map(a => a.tailNumber),
        ].filter(Boolean);
        const tailNumber = generateTailNumber(state.hub, state.airlineName, usedTails);
        // Used-aircraft market delivery: rebuild the exact tail from its frozen
        // snapshot (age / cabin / engines / maintenance) instead of a fresh build.
        if (order.used && order.usedSnapshot) {
          deliveredAircraft.push({
            ...order.usedSnapshot,
            id:            uid(),
            tailNumber,
            status:        'idle',
            ownershipType: 'owned',
          });
          newToasts.push({
            type:     'success',
            title:    'Used Aircraft Delivered: ' + order.name,
            message:  'Your used ' + ((ordType && ordType.name) ? ordType.name : order.name) + ' (' + tailNumber + ') has arrived and is ready for service.',
            icon:     '✈',
            duration: 7000,
          });
          continue;
        }
        const DELIVERY_LEASE_TERMS = { 'Turboprop': 52, 'Regional Jet': 78, 'Narrow Body': 104, 'Wide Body': 156 };
        const deliveredLeaseTerm = order.ownershipType === 'lease'
          ? (order.leaseTermWeeks ?? DELIVERY_LEASE_TERMS[ordType?.category] ?? DEFAULT_LEASE_TERM_WEEKS)
          : undefined;
        deliveredAircraft.push({
          id:            uid(),
          typeId:        order.typeId,
          name:          order.name,
          tailNumber,
          status:        'idle',
          ageWeeks:      eraDeliveredAgeWeeks(ordType, calendarYear(state)),
          config:        order.config ?? defaultConfig(ordType?.seats ?? 100),
          ownershipType: order.ownershipType,
          weeklyLease:        order.weeklyLease ?? 0,
          leaseDeposit:       order.leaseDeposit ?? 0,
          leaseTermWeeks:     deliveredLeaseTerm,
          leaseRemainingWeeks: deliveredLeaseTerm,
          fuelMod:       order.fuelMod   ?? 1.0,
          rangeMod:      order.rangeMod  ?? 1.0,
          maintMod:      order.maintMod  ?? 1.0,
          engineId:      order.engineId  ?? null,
          engineLabel:   order.engineLabel ?? null,
          hasWingtips:   order.hasWingtips ?? false,
          hasWifi:       order.hasWifi ?? false,
        });
        newToasts.push({
          type:     'success',
          title:    `Aircraft Delivered: ${order.name}`,
          message:  `Your ${ordType?.name ?? order.name} (${tailNumber}) has arrived and is ready for service.`,
          icon:     '✈',
          duration: 7000,
        });
      }
      const finalFleet = [...agedFleet, ...deliveredAircraft];
      // Self-heal legacy duplicate display names (pre-2026-07-17 fleets could
      // mint two "A320neo #18"s). Keep the first of each name; renumber later
      // ones to the next free number for their type. Deterministic (fleet order
      // is stable), so server and clients converge; no-op once names are unique.
      {
        const seen = new Set();
        for (let i = 0; i < finalFleet.length; i++) {
          const a = finalFleet[i];
          if (!a?.name) continue;
          if (!seen.has(a.name)) { seen.add(a.name); continue; }
          const base = a.name.replace(/\s*#\d+\s*$/, '');
          let num = nextAircraftNumber(a.typeId, finalFleet, state.pendingOrders);
          let candidate = `${base} #${num}`;
          while (seen.has(candidate)) candidate = `${base} #${++num}`;
          finalFleet[i] = { ...a, name: candidate };
          seen.add(candidate);
        }
      }
      // Drop routes whose aircraft lease expired this week, and age weeksOpen on survivors
      // If a COVERING tail's lease expired this week, its covered routes go home
      // to the original instead of dying with the lease.
      const leaseSafeRoutes = removedAircraftIds.size > 0
        ? seasonAdjustedRoutes.map(r => (r.coverForAircraftId && removedAircraftIds.has(r.aircraftId))
            ? { ...r, aircraftId: r.coverForAircraftId, coverForAircraftId: null } : r)
        : seasonAdjustedRoutes;
      const survivingRoutes = removedAircraftIds.size > 0
        ? leaseSafeRoutes.filter(r => !removedAircraftIds.has(r.aircraftId))
        : leaseSafeRoutes;
      const finalRoutes = survivingRoutes.map(r => ({
        ...r,
        weeksOpen: (r.weeksOpen ?? 0) + 1,
      }));
      // Same treatment for cargo routes: drop those whose freighter's lease expired,
      // age weeksOpen on survivors (drives the cargo maturity ramp).
      const leaseSafeCargo = removedAircraftIds.size > 0
        ? coverPass.cargoRoutes.map(r => (r.coverForAircraftId && removedAircraftIds.has(r.aircraftId))
            ? { ...r, aircraftId: r.coverForAircraftId, coverForAircraftId: null } : r)
        : coverPass.cargoRoutes;
      const survivingCargo = removedAircraftIds.size > 0
        ? leaseSafeCargo.filter(r => !removedAircraftIds.has(r.aircraftId))
        : leaseSafeCargo;
      const finalCargoRoutes = survivingCargo.map(r => ({
        ...r,
        weeksOpen: (r.weeksOpen ?? 0) + 1,
      }));

      // ── Gate scarcity: use-it-or-lose-it (scarcity worlds only) ───────────
      // An airport you hold gates at but haven't served for GATE_IDLE_FORFEIT_
      // WEEKS consecutive weeks takes its gates back and locks you out for
      // GATE_LOCKOUT_WEEKS. The home hub is exempt. Warnings from week 16.
      // The server reconciles any forfeiture into the world's gate ledger by
      // diffing gates before/after this tick. Solo games never enter this block.
      let finalGates       = state.gates ?? {};
      let newGateIdleWeeks = state.gateIdleWeeks;
      let newGateLockouts  = state.gateLockouts;
      if (state.gateScarcityWorld) {
        const nextAbsWeek = absoluteWeek(newYear, newWeek);
        const served = new Set();
        for (const r of finalRoutes)      for (const code of routeStops(r)) served.add(code);
        for (const r of finalCargoRoutes) { served.add(r.origin); served.add(r.destination); }
        const gatesNow = { ...finalGates };
        const idle     = {};
        const lockouts = { ...(state.gateLockouts ?? {}) };
        for (const [code, exp] of Object.entries(lockouts)) {
          if (!(exp > nextAbsWeek)) delete lockouts[code];   // expired lockouts clear
        }
        for (const [code, count] of Object.entries(gatesNow)) {
          if (!count || code === state.hub) continue;        // home hub exempt
          if (served.has(code)) continue;                    // any service resets the clock
          // Alliance slot pool: a gate whose slots partners are drawing on is
          // IN USE — the owner's usage for rule-5 purposes. Lending spare
          // capacity protects gates you cannot fill yet; that incentive is the
          // point of the pool.
          if ((state.allianceSlotPool?.[code]?.lentOut ?? 0) > 0) continue;
          const weeks = (state.gateIdleWeeks?.[code] ?? 0) + 1;
          if (weeks >= GATE_IDLE_FORFEIT_WEEKS) {
            delete gatesNow[code];
            lockouts[code] = nextAbsWeek + GATE_LOCKOUT_WEEKS;
            newToasts.push({
              type: 'danger', title: '🛑 Gates forfeited',
              message: `Your ${count} gate${count > 1 ? 's' : ''} at ${code} went unused for ${GATE_IDLE_FORFEIT_WEEKS} weeks and returned to the airport. You are locked out of ${code} for ${GATE_LOCKOUT_WEEKS} weeks.`,
              duration: 10000,
            });
          } else {
            idle[code] = weeks;
            if (weeks >= GATE_IDLE_WARN_WEEKS) {
              const left = GATE_IDLE_FORFEIT_WEEKS - weeks;
              newToasts.push({
                type: 'warning', title: '⚠️ Unused gates',
                message: `No routes serve ${code}. Your ${count} gate${count > 1 ? 's' : ''} there will be forfeited in ${left} week${left === 1 ? '' : 's'} — open a route or release them.`,
                duration: 8000,
              });
            }
          }
        }
        finalGates       = gatesNow;
        newGateIdleWeeks = idle;
        newGateLockouts  = lockouts;
      }

      // ── Alliance slot pool: the squeeze (scarcity MP worlds only) ─────────
      // A borrower's usage can exceed own gates + pool grant when the pool
      // shrinks under them: the owner grew back into their slots, raised their
      // reserve, stopped sharing, or the alliance parted ways (leaving/kick/
      // disband all read as grant → 0 on the next injection — the countdown IS
      // the wind-down). They get SLOT_SQUEEZE_GRACE_WEEKS of warnings, then
      // frequency is trimmed to fit — highest weekly frequency first, ties on
      // id, a route trimmed to zero closes. Deterministic, so a retried tick
      // trims identically. `state.allianceSlotPool` is injected only in
      // Headwinds scarcity worlds, so solo states never enter this block.
      let finalSqueezeRoutes = finalRoutes;
      let finalSqueezeCargo  = finalCargoRoutes;
      let newSlotSqueeze     = state.slotSqueeze;
      if (state.gateScarcityWorld && state.allianceSlotPool) {
        const squeeze = { ...(state.slotSqueeze ?? {}) };
        const codes = new Set([
          ...finalSqueezeRoutes.flatMap(r => [r.origin, r.destination]),
          ...finalSqueezeCargo.flatMap(r => [r.origin, r.destination]),
          ...Object.keys(state.slotSqueeze ?? {}),
        ]);
        const usageAt = (code) =>
          finalSqueezeRoutes.filter(r => r.origin === code || r.destination === code)
            .reduce((s, r) => s + (r.weeklyFrequency ?? 0), 0)
          + finalSqueezeCargo.filter(r => r.origin === code || r.destination === code)
            .reduce((s, r) => s + (r.weeklyFrequency ?? 0), 0);
        const capAt = (code) =>
          (finalGates[code] ?? 0) * SLOTS_PER_GATE
          + (state.allianceSlotPool[code]?.grant ?? 0);
        for (const code of [...codes].sort()) {
          const over = usageAt(code) - capAt(code);
          if (over <= 0) { delete squeeze[code]; continue; }
          const left = (squeeze[code] ?? SLOT_SQUEEZE_GRACE_WEEKS) - 1;
          if (left > 0) {
            squeeze[code] = left;
            newToasts.push({
              type: 'warning', title: '⚠️ Alliance slots withdrawn',
              message: `Your schedule at ${code} uses ${over} more weekly slot${over === 1 ? '' : 's'} than your gates and the alliance pool now cover. Reduce frequency or lease gates within ${left} week${left === 1 ? '' : 's'} — after that, flights will be cut to fit.`,
              duration: 10000,
            });
            continue;
          }
          // Grace exhausted — trim to fit. Highest-frequency operations at the
          // airport shed slots first (they can spare the most); ties break on
          // id so a retried tick cuts the same flights.
          delete squeeze[code];
          let need = over;
          const cuts = new Map(); // routeId → slots to cut
          const candidates = [
            ...finalSqueezeRoutes.filter(r => r.origin === code || r.destination === code),
            ...finalSqueezeCargo.filter(r => r.origin === code || r.destination === code),
          ].sort((a, b) => (b.weeklyFrequency ?? 0) - (a.weeklyFrequency ?? 0)
            || String(a.id).localeCompare(String(b.id)));
          for (const r of candidates) {
            if (need <= 0) break;
            const cut = Math.min(need, r.weeklyFrequency ?? 0);
            if (cut > 0) { cuts.set(r.id, cut); need -= cut; }
          }
          if (cuts.size > 0) {
            finalSqueezeRoutes = finalSqueezeRoutes
              .map(r => cuts.has(r.id) ? { ...r, weeklyFrequency: r.weeklyFrequency - cuts.get(r.id) } : r)
              .filter(r => r.weeklyFrequency > 0);
            finalSqueezeCargo = finalSqueezeCargo
              .map(r => cuts.has(r.id) ? { ...r, weeklyFrequency: r.weeklyFrequency - cuts.get(r.id) } : r)
              .filter(r => r.weeklyFrequency > 0);
            newToasts.push({
              type: 'danger', title: '🛑 Flights cut at ' + code,
              message: `The alliance slot pool at ${code} no longer covers your schedule. ${over} weekly departure${over === 1 ? '' : 's'} ${over === 1 ? 'was' : 'were'} cut to fit your gates.`,
              duration: 10000,
            });
          }
        }
        newSlotSqueeze = squeeze;
      }

      let newReputationPenalty = (state.reputationPenalty ?? 0) * REP_PENALTY_DECAY + forcedRepHit;
      newReputationPenalty = newReputationPenalty < 0.1 ? 0 : Math.min(REP_PENALTY_MAX, newReputationPenalty);

      return {
        ...state,
        cash:              cashAfterDividend + objectiveCashBonus,
        week:              newWeek,
        year:              newYear,
        portfolio:         newPortfolio,
        fleet:             finalFleet,
        reputationPenalty: newReputationPenalty,
        routes:            finalSqueezeRoutes,
        cargoRoutes:       finalSqueezeCargo,
        // Gate scarcity only — spread stays empty elsewhere so non-scarcity
        // (and solo) states are byte-identical to before this feature.
        ...(state.gateScarcityWorld ? {
          gates:         finalGates,
          gateIdleWeeks: newGateIdleWeeks ?? {},
          gateLockouts:  newGateLockouts ?? {},
          // Slot-pool squeeze countdowns. The key appears only once the pool
          // has ever been injected (or a countdown exists), so every pre-pool
          // scarcity state stays byte-identical — golden parity holds without
          // a re-baseline.
          ...(state.allianceSlotPool || state.slotSqueeze
            ? { slotSqueeze: newSlotSqueeze ?? {} } : {}),
        } : {}),
        pendingOrders:     remainingOrders,
        financialHistory:  newHistory,
        statsHistory:      newStats,
        ...(newStatsYearly !== state.statsHistoryYearly ? { statsHistoryYearly: newStatsYearly } : {}),
        lastReport:        { ...report, cashDelta: preTaxProfit - corporateTax,
          // Effective revenue includes the world-event demand adjustment that the
          // headline net already reflects; "all-in" cost folds loan payments,
          // lease redelivery, seasonal reactivation fees and corporate tax on top of
          // operating cost so that (revenueEffective − totalCostAll) reconciles to cashDelta.
          revenueEffective: Math.round(report.totalRevenue + eventDemandAdj - strikeRevenueLoss),
          totalCostAll: report.totalCost + totalLoanPayments + leaseRedeliveryCost + seasonalReactivationCost + corporateTax + maintCheckSpend + aogSpend,
          loanPayments: totalLoanPayments, loanInterest: totalLoanInterest, leaseRedelivery: leaseRedeliveryCost, leaseDepositReturned: leaseDepositRefund, seasonalReactivation: seasonalReactivationCost, corporateTax, eventDemandAdj: Math.round(eventDemandAdj), strikeLoss: strikeRevenueLoss, strikeVariableSaved, competitorEvents, newEvents, expiredEvents, mechanicalFailures: newFailures, mro: { jobs: mroJobs, aogSpend, aogInsurance, baseCosts: report.totalMroBaseCosts ?? 0, contractSavings: report.mroContractSavings ?? 0, opened: baseBuild.opened, upgraded: baseBuild.upgraded }, maintenanceChecks: { started: checksStarted, forced: checksForced, completed: completedChecks, spend: maintCheckSpend, repHit: forcedRepHit }, coverage: { started: coverPass.coversStarted, ended: coverPass.coversEnded, permanent: coverPass.coversPermanent, gaps: coverPass.coverGaps }, fuelIndex: currentFuelIndex, fuelMultiplier, marketIndex: currentMarketIndex, marketFactor,
      dividend: dividendPaid > 0
        ? { perShare: dividendPerSh, total: dividendPaid, payableShares: divPayable }
        : null, loyaltyMemberDelta: updatedLoyalty.members - currentLoyalty.members, loyaltyMembersTotal: updatedLoyalty.members },
        competitors:       updatedCompetitors,
        encroachments:     updatedEncroachments,
        hubs:              hubsAfterBuild,
        hubConstruction:   newHubConstruction,
        hubThroughput:     newHubThroughput,
        loans:             updatedLoans,
        labor:             updatedLabor,
        laborRelations:    updatedRelations,
        maintenanceBudget: mainBudget,
        mroBases:          tickedBases,
        lounges:           tickedLounges,
        activeEvents:      allEvents,
        fuelPrice:         { index: nextFuelIndex, history: fuelPriceHistory },
        marketIndex:       nextMarketIndex,
        hedgeContracts:      liveHedges,
        loyalty:             updatedLoyalty,
        codeshareAgreements: tickedCodeshares,
        awareness:           Math.round(newAwareness * 10) / 10,
        campaignStrength:    newCampaigns,
        // Earned passenger satisfaction (EWMA toward delivered experience);
        // computed by weeklyTick, persisted here, plus any one-time shocks from
        // quality events that triggered this week (catering scandal, viral
        // praise, ...). Old saves start null and initialize on their first tick.
        satisfaction:        (() => {
          const base = report.satisfaction ?? state.satisfaction ?? null;
          if (base == null) return null;
          const shock = newEvents.reduce((s, ev) => s + (ev.effects?.satisfactionShock ?? 0), 0);
          return Math.max(0, Math.min(100, Math.round((base + shock) * 10) / 10));
        })(),
        objectives:               updatedObjectives,
        objectivesEnabled,
        paxAllTime,
        showDebrief:              true,
        pendingToasts:            newToasts,
        phase:                    newPhase,
        bankruptcyReason,
        missedLoanPayments:       newMissedLoanPayments,
        consecutiveNegativeWeeks: newConsecutiveNegativeWeeks,
        marketCap:                newMarketCap,
        // Unsmoothed fundamental value. NOT published as a price — it exists so a
        // listing can be priced honestly (GO_PUBLIC) without the published series
        // having to teleport week to week.
        fairValue:                newFairValue,
        sharePrice:               newSharePrice,
        equity:                   nextEquity,
        // Leaderboard metric: per-share value including lifetime dividends — which
        // is what makes paying one rank-neutral instead of rank-negative.
        svps:                     svpsOf({ sharePrice: newSharePrice, equity: nextEquity }),
        // Last rival collapsed or was absorbed → the player owns the skies.
        gameWon:             state.gameWon || rivalsGone,
        victoryAcknowledged: (rivalsGone && !state.gameWon) ? false : state.victoryAcknowledged,
        victoryStats:        (rivalsGone && !state.gameWon) ? {
          marketCap:   newMarketCap ?? state.marketCap ?? null,
          cash:        cashAfterDividend + objectiveCashBonus,
          fleetCount:  finalFleet.filter(a => a.status !== 'retired').length,
          routeCount:  finalRoutes.length,
          airports:    Object.values(state.gates ?? {}).filter(n => n > 0).length,
          weeksPlayed: (newYear - 1) * 52 + newWeek,
          year:        newYear,
          lastRival:   lastRivalName,
        } : state.victoryStats,
      };
    } catch (err) {
      console.error('[ADVANCE_WEEK] reducer threw:', err);
      return { ...state, advanceWeekError: err?.message ?? String(err) };
    } }

    case 'BUY_HEDGE': {
      // action: { durationId, coverage }
      // durationId: 'short' | 'medium' | 'long'
      // coverage: 0.25 | 0.50 | 0.75 — fraction of fleet fuel to hedge
      const opt = HEDGE_DURATIONS.find(o => o.id === action.durationId);
      if (!opt) return state;

      // Coverage is a FRACTION of the fuel bill, and has to be policed like the
      // duration above it. It used to be stored verbatim: buying a hedge costs
      // no cash, so a coverage of -1000 paired with one of +1000.1 made
      // effectiveFuelMultiplier (which divides by the SIGNED sum of coverages)
      // return -68.997, and every route on the airline booked a large negative
      // fuel cost for the life of the contract.
      const coverage = Number(action.coverage);
      if (!Number.isFinite(coverage) || coverage <= 0 || coverage > 1) return state;

      const marketIndex  = state.fuelPrice?.index ?? 1.0;
      const locked       = hedgeLockedPrice(marketIndex, opt);
      const startAbsWeek = absoluteWeek(state.year, state.week);
      const newContract  = {
        id:            uid(),
        durationId:    opt.id,
        durationLabel: opt.label,
        coverage,
        lockedPrice:   locked,
        marketAtPurchase: marketIndex,
        startAbsWeek,
        expiryAbsWeek: startAbsWeek + opt.weeks,
        weeksTotal:    opt.weeks,
      };
      return {
        ...state,
        hedgeContracts: [...(state.hedgeContracts ?? []), newContract],
      };
    }

    case 'BUY_STOCK': {
      // action: { targetId, shares }
      // Buy shares in a rival airline at the current authoritative price. The
      // price is NEVER taken from the action: it derives from state.competitors,
      // which in multiplayer the server injects fresh from the DB before running
      // the reducer (a client cannot fabricate it) and in solo is engine-owned.
      // Friction (1% spread + 0.5% commission each way ≈ 3% round trip) makes
      // churn and wash-trading lossy by construction.
      const S      = STOCK_MARKET;
      const target = (state.competitors ?? []).find(c => c.id === action.targetId);
      const shares = Math.floor(Number(action.shares));
      if (!target || !(shares > 0)) return state;
      const targetShares = sharesOf(target);
      const price = (target.sharePrice ?? (target.marketCap ?? 0) / targetShares) || 0;
      if (!(price > 0)) return state;

      const portfolio  = state.portfolio ?? emptyPortfolio();
      const held       = portfolio.holdings[action.targetId];
      const heldShares = held?.shares ?? 0;

      // Ownership cap: at most 20% of the rival's OWN shares outstanding (which
      // issuance and buybacks move, so this is read per-airline, never assumed).
      if (heldShares + shares > S.MAX_OWNERSHIP_PCT * targetShares) return state;

      // Privately held rivals have no float to buy. The rival view marks them
      // (isPublic === false); older payloads without the flag stay tradeable.
      if (target.isPublic === false) return state;

      // Float pool: shares come FROM the pool's inventory, so it has to hold
      // them. `worldMarket` is injected by the server (never persisted, never
      // client-supplied). The CLIENT'S optimistic run has no worldMarket, so it
      // falls back to the rival view's `poolShares` — without that fallback a
      // buy the pool cannot fill "succeeded" locally and then reversed when the
      // authoritative state came back. Solo has neither and keeps the legacy
      // unbounded counterparty.
      const buyMarket = state.worldMarket;
      const buyAvailable = (buyMarket && Number.isFinite(buyMarket.sharesAvailable))
        ? buyMarket.sharesAvailable
        : (Number.isFinite(Number(target.poolShares)) ? Number(target.poolShares) : null);
      if (buyAvailable != null && shares > buyAvailable) return state;

      // Execution price includes the order's OWN weight against the free float:
      // a large stake cannot be accumulated at the marked price.
      const execPrice  = executionPrice(price, shares, freeFloatOf(target), true);
      const gross      = Math.round(shares * execPrice);
      const commission = Math.round(gross * S.COMMISSION);
      const totalCost  = gross + commission;
      if (gross < S.MIN_TICKET) return state;          // no dust trades
      if (state.cash < totalCost) return state;        // can't afford

      // Sizing cap: total portfolio cost basis ≤ 40% of your own market cap —
      // investing is a side-game; running the airline stays the main game.
      const basisTotal = Object.values(portfolio.holdings ?? {})
        .reduce((s, h) => s + (h?.costBasis ?? 0), 0);
      if (basisTotal + totalCost > S.MAX_PORTFOLIO_PCT_OF_CAP * (state.marketCap ?? 0)) return state;

      return {
        ...state,
        cash: state.cash - totalCost,
        // The server reads this to settle the pool inside the same transaction:
        // pool cash += gross, pool inventory -= shares. Commission is a fee and
        // vanishes from the world entirely.
        lastStockTrade: { targetId: action.targetId, side: 'buy', shares, gross },
        portfolio: {
          ...portfolio,
          holdings: {
            ...portfolio.holdings,
            [action.targetId]: {
              shares:    heldShares + shares,
              costBasis: (held?.costBasis ?? 0) + totalCost,   // commission included
              name:      target.name ?? held?.name ?? 'Rival',
              lastPrice: price,
              lastValue: Math.round((heldShares + shares) * price),
            },
          },
        },
      };
    }

    case 'SELL_STOCK': {
      // action: { targetId, shares } — sell at price × 0.99 minus 0.5% commission.
      // No minimum ticket on sells: a residual position must always be exitable.
      const S         = STOCK_MARKET;
      const shares    = Math.floor(Number(action.shares));
      const portfolio = state.portfolio ?? emptyPortfolio();
      const held      = portfolio.holdings[action.targetId];
      if (!held || !(shares > 0) || shares > held.shares) return state;
      // Price from the live rival where possible; a rival mid-delisting falls
      // back to the last marked price (the weekly tick will haircut anyway).
      const target = (state.competitors ?? []).find(c => c.id === action.targetId);
      const price  = target
        ? ((target.sharePrice ?? (target.marketCap ?? 0) / sharesOf(target)) || 0)
        : (held.lastPrice ?? 0);
      if (!(price > 0)) return state;

      // Selling into the float pushes the price down against you, in proportion
      // to how much of the free float you are unloading — plus an extra discount
      // when the world's pool is short of cash (a market with no buyers left).
      const sellFloat  = target ? freeFloatOf(target) : freeFloatOf(held);
      // Authoritative pool view where the server injected one; the client's
      // optimistic run falls back to the server-derived stockPool summary so a
      // sale the pool cannot fund is rejected locally too (matching the server)
      // instead of appearing to succeed and then reversing.
      const sellMarket = state.worldMarket
        ?? (Number.isFinite(Number(state.stockPool?.poolCash)) ? state.stockPool : null);
      const liqDiscount = sellMarket
        ? poolLiquidityDiscount(sellMarket.poolCash, sellMarket.seedCash)
        : 0;
      const sellEdge   = S.SPREAD_HALF + priceImpact(shares, sellFloat) + liqDiscount;
      const execPrice  = price * Math.max(0, 1 - sellEdge);
      const gross      = Math.round(shares * execPrice);
      const commission = Math.round(gross * S.COMMISSION);
      const proceeds   = gross - commission;
      const avgCost    = held.costBasis / held.shares;
      // Capital gains tax on the realized gain. This money leaves the world
      // entirely — the sink that offsets equity capital coming in.
      const grossGain  = proceeds - Math.round(avgCost * shares);
      const tax        = capitalGainsTax(grossGain);
      const netProceeds = proceeds - tax;
      const realized   = grossGain - tax;
      const remaining  = held.shares - shares;

      // The pool is the buyer of last resort, and it can run dry: if it cannot
      // fund the gross, the sale does not happen. The client surfaces this as a
      // liquidity message rather than a silent no-op.
      if (sellMarket && Number.isFinite(sellMarket.poolCash) && gross > sellMarket.poolCash) {
        return state;
      }

      const holdings = { ...portfolio.holdings };
      if (remaining > 0) {
        holdings[action.targetId] = {
          ...held,
          shares:    remaining,
          costBasis: Math.round(held.costBasis - avgCost * shares),
          lastPrice: price,
          lastValue: Math.round(remaining * price),
        };
      } else {
        delete holdings[action.targetId];
      }
      return {
        ...state,
        cash:      state.cash + netProceeds,
        // Settles against the pool server-side: pool cash -= gross, inventory
        // += shares. Commission and capital gains tax leave the world.
        lastStockTrade: { targetId: action.targetId, side: 'sell', shares, gross },
        portfolio: {
          ...portfolio,
          holdings,
          taxPaid:          (portfolio.taxPaid ?? 0) + tax,
          realizedPnL:      (portfolio.realizedPnL ?? 0) + realized,
          // Rolls into this week's P&L "investment income" line at the next tick
          // (kept OUT of operating profit so trades can't feed the P/E valuation).
          realizedThisWeek: (portfolio.realizedThisWeek ?? 0) + realized,
        },
      };
    }

    // ── Capital actions ──────────────────────────────────────────────────────
    // The company side of the market. Under the SVPS leaderboard each of these is a
    // real trade-off: issuing shares brings in cash but splits the pie, buying them
    // back shrinks the pie faster than the cash leaves, and dividends convert your
    // own retained cash into shareholder value the board actually credits.
    //
    // All three settle against the world's float pool, so no share appears from
    // nowhere and no cash is minted (see lib/marketService.mjs).

    case 'GO_PUBLIC': {
      // action: { shares, secondaryShares }
      //   shares          — NEW shares issued to outside investors (dilutive)
      //   secondaryShares — EXISTING founder shares sold instead (non-dilutive)
      //
      // Either tranche may be zero. Real listings are routinely a mix of the two,
      // and the choice is a real trade-off rather than a strictly better button:
      // new shares raise the full amount and permanently split the company, while
      // founder shares leave the share count (and therefore every per-share
      // number, including the leaderboard metric) untouched but reach the treasury
      // net of capital-gains tax — see CAPITAL.FOUNDER_BASIS_PER_SHARE.
      const C = CAPITAL;
      const equity = state.equity ?? emptyEquity();
      if (equity.isPublic) return state;                    // already listed

      const absWk = absoluteWeek(state.year, state.week);
      if (absWk < C.IPO_MIN_ABS_WEEK) return state;          // too young to list
      const history = state.financialHistory ?? [];
      if (history.length < C.IPO_MIN_HISTORY_WEEKS) return state;

      const preShares   = sharesOf(state);
      const founderHeld = Math.max(0, Math.min(preShares, Number(equity.founderShares ?? preShares)));
      const wantNew = Math.max(0, Math.floor(Number(action.shares) || 0));
      const wantSec = Math.max(0, Math.floor(Number(action.secondaryShares) || 0));
      const offered = wantNew + wantSec;
      if (!(offered > 0)) return state;
      if (wantSec > founderHeld) return state;               // can't sell what you don't hold

      // The band applies to the FLOAT — how much of the company ends up in outside
      // hands — however the offering is built, so a 35% sell-down and a 35% issue
      // are the same size of listing.
      const postShares = preShares + wantNew;
      const fraction   = offered / postShares;
      // Tolerate ONE share of rounding either way. A UI solving "float 35% of the
      // post-issue company" can only land on a whole number of shares, and at a
      // 100M-share register the nearest integer lands a fraction of a billionth
      // outside the band — which used to make the 10% and 35% buttons no-ops that
      // silently returned the unchanged state.
      const bandEps = 1 / postShares;
      if (fraction < C.IPO_MIN_FRACTION - bandEps || fraction > C.IPO_MAX_FRACTION + bandEps) return state;

      // Price off the airline's own current valuation, less the IPO discount. A
      // short or loss-making record is priced worse — the market wants a bargain
      // for taking a chance on you. One book, one price: the founder sells at the
      // same price the company issues at.
      const recent     = history.slice(-12);
      const profitable = recent.length
        ? recent.filter(h => (h.profit ?? 0) > 0).length / recent.length
        : 0;
      const discount   = ipoDiscount(history.length, profitable);
      // Listing IS the price-discovery event: this is the first week the market
      // prints what the airline is actually worth. Up to now the published cap has
      // been a smoothed series (so the pre-listing chart is readable and rivals
      // never see a four-digit weekly move), so the offer is priced off the
      // unsmoothed fair value and the published cap rebases to it in the same
      // step — otherwise a fast-growing startup would list at a price its own
      // published cap could not support and the stock would gap down on day one.
      const baseCap    = Number(state.fairValue) > 0
        ? Number(state.fairValue)
        : (Number(state.marketCap) || 0);
      const basePrice  = baseCap / preShares;
      const price      = basePrice * (1 - discount);
      if (!(price > 0)) return state;
      // The pool is the buyer and its cash is finite. Fill what it can afford
      // rather than refusing the whole listing: a big airline floating onto a
      // small exchange gets a small float, which is the realistic outcome and
      // beats a button that silently does nothing.
      const mk       = state.worldMarket;
      const poolCash = mk && Number.isFinite(mk.poolCash) ? Math.max(0, mk.poolCash) : Infinity;
      const sold     = Math.min(offered, Math.floor(poolCash / price));
      // A short fill takes the NEW shares first. The company's need for capital
      // ranks ahead of the founder cashing out, and it stops a trimmed offering
      // from quietly turning into a pure sell-down that raises almost nothing.
      const soldNew  = Math.min(wantNew, sold);
      const soldSec  = sold - soldNew;
      // Floors, not rounding: the two tranches together must never bill the pool
      // for more than `sold x price`, or the server's re-check rejects the listing.
      const primaryGross = Math.floor(soldNew * price);
      const secSale      = founderSaleProceeds(soldSec, price);
      const gross        = primaryGross + secSale.gross;   // what the pool pays
      const proceeds     = primaryGross + secSale.net;     // what reaches the treasury
      // A token fill is not a listing — below the market's minimum ticket the
      // equity window is simply shut. Measured on the deal, not on the treasury's
      // share of it: the taxman taking a cut doesn't make the listing smaller.
      if (!(sold > 0) || gross < Math.min(STOCK_MARKET.MIN_TICKET, Math.floor(offered * price))) {
        return state;
      }
      const newShares = preShares + soldNew;
      const partial   = sold < offered;

      // Reprice in the same step as the dilution — see repriceForShareChange.
      // Rebased onto the fair value (baseCap), not the smoothed pre-listing print.
      // Only the NET cash joins the cap: the tax left the world.
      const listed = repriceForShareChange({ ...state, marketCap: baseCap },
                                           { shares: newShares, cashDelta: proceeds });

      const nextEquity = {
        ...equity,
        shares:        newShares,
        // Every share sold out of the founder block is one more share the public
        // holds — which is also one more share dividends must be paid on, and one
        // more share a rival can buy.
        founderShares: founderHeld - soldSec,
        isPublic:      true,
        ipoWeek:       absWk,
      };

      return {
        ...state,
        cash: state.cash + proceeds,
        marketCap:  listed.marketCap,
        fairValue:  listed.marketCap,
        sharePrice: listed.sharePrice,
        svps:       svpsOf({ sharePrice: listed.sharePrice, equity: nextEquity }),
        equity: nextEquity,
        lastEquityAction: {
          kind: 'ipo',
          // `shares` and `gross` are what the POOL transacted — the server settles
          // its inventory and its cash off these two, so they must stay whole-deal
          // figures whatever the mix underneath.
          shares: sold, gross, pricePerShare: price,
          newShares: soldNew, secondaryShares: soldSec, tax: secSale.tax, net: proceeds,
        },
        pendingToasts: [
          ...(state.pendingToasts ?? []),
          {
            type: 'success', icon: '🔔',
            title: 'Listed on the exchange',
            message: `Sold ${sold.toLocaleString()} shares (${Math.round((sold / newShares) * 100)}% of the company) `
                   + `at $${price.toFixed(4)} — ${proceeds.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })} raised `
                   + `after a ${Math.round(discount * 100)}% IPO discount.`
                   + (soldSec > 0
                       ? ` ${soldSec.toLocaleString()} of them came out of your own holding`
                         + (secSale.tax > 0
                             ? `, less ${secSale.tax.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })} of capital-gains tax`
                             : '')
                         + `, so your share count is unchanged.`
                       : '')
                   + (partial
                       ? ` Investors could only absorb ${Math.round((sold / offered) * 100)}% of the offering, so the rest was withdrawn.`
                       : ''),
            duration: 11000,
          },
        ],
      };
    }

    case 'ISSUE_SHARES': {
      // action: { shares } — secondary offering, throttled per game year.
      const C = CAPITAL;
      const equity = state.equity ?? emptyEquity();
      if (!equity.isPublic) return state;                   // list first

      const shares = sharesOf(state);
      const n = Math.floor(Number(action.shares));
      if (!(n > 0)) return state;

      const issuedThisYear = Number(equity.offeringsThisYear ?? 0);
      if (issuedThisYear + n > C.OFFERING_MAX_PCT_PER_YEAR * shares) return state;

      // Going back to the well repeatedly costs more each time; a record of
      // returning capital earns a better price.
      const usedFrac = (issuedThisYear + n) / shares;
      const loyal    = (equity.cumDividendsPerShare ?? 0) > 0 || (equity.buybacksEver ?? 0) > 0 ? 1 : 0;
      const discount = offeringDiscount(usedFrac, loyal);
      const basePrice = state.sharePrice ?? ((state.marketCap ?? 0) / shares);
      const price     = basePrice * (1 - discount);
      if (!(price > 0)) return state;
      // Partially subscribed if the pool is short of cash — same rule as the IPO.
      const mk       = state.worldMarket;
      const poolCash = mk && Number.isFinite(mk.poolCash) ? Math.max(0, mk.poolCash) : Infinity;
      const issued   = Math.min(n, Math.floor(poolCash / price));
      const proceeds = Math.min(Math.round(issued * price), Math.floor(poolCash));
      if (!(issued > 0) || proceeds < Math.min(STOCK_MARKET.MIN_TICKET, Math.round(n * price))) {
        return state;
      }
      const newShares = shares + issued;
      const partial   = issued < n;

      // Reprice in the same step as the dilution — see repriceForShareChange.
      const repriced = repriceForShareChange(state, { shares: newShares, cashDelta: proceeds });

      return {
        ...state,
        cash: state.cash + proceeds,
        marketCap:  repriced.marketCap,
        sharePrice: repriced.sharePrice,
        svps:       svpsOf({ sharePrice: repriced.sharePrice, equity }),
        equity: {
          ...equity,
          shares:            newShares,
          offeringsThisYear: issuedThisYear + issued,
        },
        lastEquityAction: { kind: 'offering', shares: issued, gross: proceeds, pricePerShare: price },
        pendingToasts: [
          ...(state.pendingToasts ?? []),
          {
            type: 'info', icon: '📄',
            title: 'Share offering completed',
            message: `Issued ${issued.toLocaleString()} new shares at $${price.toFixed(4)} `
                   + `(${Math.round(discount * 100)}% discount) — `
                   + `${proceeds.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })} raised. `
                   + 'Existing holders are diluted.'
                   + (partial
                       ? ` Investors could only take ${Math.round((issued / n) * 100)}% of the offering.`
                       : ''),
            duration: 10000,
          },
        ],
      };
    }

    case 'BUY_BACK_SHARES': {
      // action: { shares } — retire stock from the float. Cash leaves, the share
      // count falls, and per-share value rises if you bought below fair value.
      const C = CAPITAL;
      const equity = state.equity ?? emptyEquity();
      if (!equity.isPublic) return state;

      const shares = sharesOf(state);
      const n = Math.floor(Number(action.shares));
      if (!(n > 0)) return state;

      // You can only retire shares that are actually in public hands.
      const founder = Number(equity.founderShares ?? 0);
      if (shares - n < founder) return state;

      const boughtThisYear = Number(equity.buybacksThisYear ?? 0);
      if (boughtThisYear + n > C.BUYBACK_MAX_PCT_PER_YEAR * shares) return state;

      // The pool must actually hold the stock you are retiring.
      const mk = state.worldMarket;
      if (mk && Number.isFinite(mk.selfSharesHeld) && n > mk.selfSharesHeld) return state;

      const basePrice = state.sharePrice ?? ((state.marketCap ?? 0) / shares);
      const price     = basePrice * (1 + C.BUYBACK_PREMIUM);
      if (!(price > 0)) return state;
      const cost      = Math.round(n * price);

      // Never buy back into insolvency: keep a few weeks of operating cover.
      const recentCost = (state.financialHistory ?? []).slice(-4);
      const weeklyCost = recentCost.length
        ? recentCost.reduce((sum, h) => sum + (h.totalCost ?? 0), 0) / recentCost.length
        : 0;
      if (state.cash - cost < weeklyCost * C.MIN_CASH_WEEKS_COVER) return state;

      // Retiring stock is the mirror image of issuing it: cash leaves the cap at
      // the same instant the shares leave the count, so the price moves only by
      // the premium paid — and rises later, as the same fair value is spread over
      // fewer shares.
      const retired = repriceForShareChange(state, { shares: shares - n, cashDelta: -cost });

      return {
        ...state,
        cash: state.cash - cost,
        marketCap:  retired.marketCap,
        sharePrice: retired.sharePrice,
        svps:       svpsOf({ sharePrice: retired.sharePrice, equity }),
        equity: {
          ...equity,
          shares:           shares - n,
          buybacksThisYear: boughtThisYear + n,
          buybacksEver:     Number(equity.buybacksEver ?? 0) + n,
        },
        lastEquityAction: { kind: 'buyback', shares: n, gross: cost, pricePerShare: price },
        pendingToasts: [
          ...(state.pendingToasts ?? []),
          {
            type: 'success', icon: '♻️',
            title: 'Buyback completed',
            message: `Retired ${n.toLocaleString()} shares at $${price.toFixed(4)} for `
                   + `${cost.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 })}. `
                   + `${(shares - n).toLocaleString()} shares now outstanding.`,
            duration: 10000,
          },
        ],
      };
    }

    case 'SET_DIVIDEND_POLICY': {
      // action: { payoutRatio } — a standing policy, paid every DIVIDEND_PERIOD_WEEKS
      // out of trailing-quarter profit. Only what is held OUTSIDE the founder block
      // is actually paid, so the cost scales with how much of yourself you've sold.
      const equity = state.equity ?? emptyEquity();
      if (!equity.isPublic) return state;
      const raw = Number(action.payoutRatio);
      if (!Number.isFinite(raw) || raw < 0) return state;
      const ratio = Math.min(CAPITAL.DIVIDEND_MAX_PAYOUT, raw);
      if (ratio === (equity.dividendPolicy ?? 0)) return state;
      return {
        ...state,
        equity: { ...equity, dividendPolicy: ratio },
      };
    }

    case 'TAKE_LOAN': {
      // action: { productId, principal }
      //
      // The rate is NOT the client's to choose. It used to be — `interestRate`
      // came in on the action and went straight onto the loan, so an airline the
      // model grades F, which should be paying 18%, could ask for the 3% floor
      // and get it. The client now names a PRODUCT and the engine prices it
      // (see data/credit.js). `action.interestRate` and `action.termWeeks` are
      // read only to identify which product a legacy payload meant.
      const product = getLoanProduct(action.productId)
        ?? (action.termWeeks != null ? loanProductForTerm(action.termWeeks) : null);
      if (!product) return { ...state, error: 'That loan product is not on offer.' };

      const principal = Math.floor(Number(action.principal) || 0);
      if (!(principal >= LOAN_MIN_PRINCIPAL)) {
        return { ...state, error: `The smallest loan available is $${LOAN_MIN_PRINCIPAL.toLocaleString()}.` };
      }

      // Collateral is taken at signing, so it must be checked before capacity —
      // an airline with nothing to pledge gets a reason, not a bare zero.
      let collateralIds;
      if (product.secured) {
        collateralIds = unencumberedOwnedFleet(state).map(a => a.id);
        if (collateralIds.length === 0) {
          return { ...state, error: 'Aircraft finance is secured on aircraft you own outright. You have none left to pledge.' };
        }
      }

      const capacity = borrowingCapacity(state, product.id);
      if (principal > capacity) {
        return {
          ...state,
          error: capacity > 0
            ? `Your capacity on ${product.name} is $${capacity.toLocaleString()}.`
            : `You have no borrowing capacity left on ${product.name}.`,
        };
      }

      const interestRate  = loanRate(state, product.id);
      const termWeeks     = product.termWeeks;
      const weeklyPayment = amortizedWeeklyPayment(principal, interestRate, termWeeks);
      const newLoan = {
        id:                uid(),
        productId:         product.id,
        principal,
        interestRate,
        termWeeks,
        weeklyPayment,
        weeksRemaining:    termWeeks,
        totalInterestPaid: 0,
        takenWeek:         state.week,
        takenYear:         state.year,
        // Present only on a secured facility. Its absence is what makes a loan
        // unsecured everywhere else in the model, so do not write an empty array.
        ...(collateralIds ? { collateralIds } : {}),
      };
      return {
        ...state,
        error: null,
        cash:  state.cash + principal,
        loans: [...(state.loans ?? []), newLoan],
      };
    }

    case 'REPAY_LOAN': {
      // action: { loanId } — early repayment, 2% penalty on remaining principal
      const loan = (state.loans ?? []).find(l => l.id === action.loanId);
      if (!loan) return state;
      // Outstanding principal, from the same helper the tick and the UI use.
      const remainingBalance = outstandingBalance(loan);
      const penalty = Math.round(remainingBalance * 0.02);
      const totalRepay = remainingBalance + penalty;
      if (state.cash < totalRepay) return state;
      return {
        ...state,
        cash:  state.cash - totalRepay,
        // Dropping the loan releases any aircraft it was secured on: every
        // collateral question in the model is asked of the live loan list.
        loans: (state.loans ?? []).filter(l => l.id !== action.loanId),
      };
    }

    case 'DISMISS_DEBRIEF': {
      return { ...state, showDebrief: false };
    }

    case 'CLEAR_TOASTS': {
      return { ...state, pendingToasts: [] };
    }

    case 'PUSH_TOAST': {
      // A toast raised from outside the weekly tick — used by the solo
      // autosave to tell the player their progress has stopped being written
      // to disk. Appends rather than replacing, so a warning raised mid-tick
      // cannot swallow the week's own toasts.
      if (!action.toast) return state;
      return { ...state, pendingToasts: [...(state.pendingToasts ?? []), action.toast] };
    }

    case 'CLEAR_ERROR': {
      return { ...state, advanceWeekError: null };
    }

    case 'RESET': {
      return freshState();
    }

    case 'LOAD_STATE': {
      return reconcileState(action.payload);
    }

    default:
      return state;
  }
}

// Exported for headless simulation/testing harnesses (no React required to use it).
export { reducer as gameReducer, freshState, reconcileState };

/**
 * Reconcile a loaded save to fix any ID-collision corruption.
 *
 * Specifically guards against the HMR bug where the module-level counter
 * reset to 1, causing a newly-bought aircraft to share an ID with an
 * existing aircraft already assigned to a route.
 *
 * Rules applied:
 *  1. De-duplicate fleet by ID — keep the LAST entry (most recent purchase).
 *  2. Remove routes whose aircraftId no longer matches any fleet aircraft.
 *  3. Re-derive aircraft.status from the cleaned route list.
 *  4. Migrate missing competitors field.
 */
function reconcileState(parsed) {
  if (!parsed) return freshState();

  // 1. De-duplicate fleet: if two aircraft share an ID, keep the last one.
  const seenIds = new Map();
  for (const a of (parsed.fleet ?? [])) seenIds.set(a.id, a);
  const fleet = [...seenIds.values()];

  // 2. Remove routes (passenger + cargo) pointing at aircraft that no longer exist.
  //    A covered route whose covering tail vanished goes home to its original
  //    first (reserve covers are temporary — the route belongs to the original).
  const fleetIds    = new Set(fleet.map(a => a.id));
  const unCover     = r => (r.coverForAircraftId && !fleetIds.has(r.aircraftId) && fleetIds.has(r.coverForAircraftId))
    ? { ...r, aircraftId: r.coverForAircraftId, coverForAircraftId: null } : r;
  const routes      = (parsed.routes ?? []).map(unCover).filter(r => fleetIds.has(r.aircraftId));
  const cargoRoutes = (parsed.cargoRoutes ?? []).map(unCover).filter(r => fleetIds.has(r.aircraftId));

  // 3. Re-derive status from the cleaned routes (passenger AND cargo — a freighter
  //    flying only cargo routes must still come back 'assigned', not 'idle').
  //    Preserve 'grounded' so aircraft mid-repair survive a save/reload cycle.
  const assignedIds = new Set([...routes, ...cargoRoutes].map(r => r.aircraftId));
  const cleanFleet  = fleet.map(a => {
    const seeded = seedMaintenance(a, getAircraftType(a.typeId));
    return {
      ...seeded,
      reserveBase: a.reserveBase ?? null,
      status: (a.status === 'grounded' || a.status === 'maintenance')
        ? a.status
        : (assignedIds.has(a.id) ? 'assigned' : 'idle'),
    };
  });

  // 4. Migrate missing competitors.
  const competitors = (parsed.competitors?.length > 0)
    ? parsed.competitors
    : sampleAndInitializeCompetitors(25);

  // 5. Carry through pendingOrders (default to empty array for old saves).
  const pendingOrders = parsed.pendingOrders ?? [];

  // 6. Reprice existing routes that are still using the old (too-high) fare multipliers.
  //    Old multipliers: business=3.5×, PE=1.7×, first=8.0×
  //    New multipliers: business=2.5×, PE=1.4×, first=5.0×
  //    Detection: check if businessClass price = economyPrice × 3.5 (within ±1).
  const migratedRoutes = routes.map(rIn => {
    // Old saves predate per-route catering — default them to Full Service, which
    // matches the engine's prior "everyone fed" behaviour exactly.
    const r = rIn.cateringLevel ? rIn : { ...rIn, cateringLevel: 'full' };
    const eco = r.classPrices?.economy ?? r.ticketPrice;
    if (!eco || !r.classPrices) return r;
    const bizRatio = (r.classPrices.businessClass ?? 0) / eco;
    const peRatio  = (r.classPrices.premiumEconomy ?? 0) / eco;
    // Reprice if using the old 3.5× / 1.7× defaults (allow ±5% rounding tolerance)
    const usingOldMultipliers =
      Math.abs(bizRatio - 3.5) < 0.18 &&
      Math.abs(peRatio  - 1.7) < 0.09;
    if (!usingOldMultipliers) return r;
    return {
      ...r,
      classPrices: {
        economy:        eco,
        premiumEconomy: Math.round(eco * CLASS_FARE_MULTIPLIERS.premiumEconomy),
        businessClass:  Math.round(eco * CLASS_FARE_MULTIPLIERS.businessClass),
        firstClass:     Math.round(eco * CLASS_FARE_MULTIPLIERS.firstClass),
      },
    };
  });

  // 7. Migrate to per-O&D-pair pricing (state.routePricing is the single source of
  //    truth). New saves already carry routePricing; old saves carried price on each
  //    route object — fold the (now repriced) per-route fares into the pair map, then
  //    strip price fields off the stored route objects.
  const routePricing  = { ...(parsed.routePricing  ?? {}) };
  const routeCatering = { ...(parsed.routeCatering ?? {}) };
  for (const r of migratedRoutes) {
    const key = routePairKey(r.origin, r.destination);
    if (!routePricing[key]) {
      const eco = r.classPrices?.economy ?? r.ticketPrice;
      if (eco) routePricing[key] = r.classPrices ?? defaultClassPrices(eco);
    }
    if (!routeCatering[key] && r.cateringLevel) {
      routeCatering[key] = normalizeCateringLevel(r.cateringLevel);
    }
  }
  const normalizedRoutes = migratedRoutes.map((rIn) => {
    // Strip legacy price/catering fields (single-leg routes keep these in
    // routePricing/routeCatering by pair) and guarantee a well-formed stops[].
    // Tag routes price per-segment on the route itself, so they retain their own
    // segmentPrices (in ...rest) AND their per-route cateringLevel.
    const { ticketPrice, classPrices, cateringLevel, ...rest } = rIn;
    const base = rest.segmentPrices ? { ...rest, cateringLevel } : rest;
    return normalizeRouteStops(base);
  });

  // 8. One-off: trim schedules already flying past the PHYSICAL block-hour cap.
  //    Applied at the very end so it sees the cleaned fleet/route lists, and
  //    stamped with a version so it can never run twice on the same save. In
  //    multiplayer the SERVER runs the same pure function on the authoritative
  //    blob (apps/headwinds-server/src/lib/tickService.mjs) — this is the client
  //    /solo path and the two are deterministic, so they converge.
  const reconciled = {
    ...parsed,
    fleet:            cleanFleet,
    routes:           normalizedRoutes,
    routePricing,
    routeCatering,
    cargoRoutes,
    competitors,
    pendingOrders,
    // Headwinds MP starter-fleet counter. New saves carry it; for old saves,
    // seed from how many aircraft the player already has so established airlines
    // don't suddenly get 2 free instant deliveries — a brand-new save (no fleet,
    // no orders) still gets the full perk.
    starterDeliveriesUsed:    parsed.starterDeliveriesUsed ?? Math.min(2, cleanFleet.length + pendingOrders.length),
    // Guarantee fields added in later versions exist even on old saves
    financialHistory: parsed.financialHistory ?? [],
    // Long-term KPI series (Finance ▸ Statistics). New saves carry it; for older
    // saves, seed a PARTIAL series from financialHistory so the recent financial
    // charts aren't empty on first load. Pre-update weeks can't have the passenger
    // split / network-size / efficiency fields reconstructed — they're flagged
    // `partial` and simply fill in going forward as new weeks tick.
    statsHistory:     parsed.statsHistory ?? (parsed.financialHistory ?? []).map(h => ({
      label:          h.label,
      week:           h.week,
      year:           h.year,
      absWeek:        ((h.year ?? 1) - 1) * 52 + (h.week ?? 0),
      paxOrganic:     h.passengers    ?? 0,
      revenue:        (h.revenue ?? 0) + (h.cargoRevenue ?? 0),
      partnerRevenue: h.partnerRevenue ?? 0,
      cargoRevenue:   h.cargoRevenue   ?? 0,
      cost:           h.totalCost      ?? 0,
      profit:         h.profit         ?? 0,
      cash:           h.cash           ?? 0,
      partial:        true,
    })),
    lastReport:       parsed.lastReport       ?? null,
    satisfaction:     parsed.satisfaction     ?? null,
    hubs:             parsed.hubs             ?? {},
    gates:            parsed.gates            ?? {},
    loans:            parsed.loans            ?? [],
    hedgeContracts:   parsed.hedgeContracts   ?? [],
    loyalty:          parsed.loyalty
      ? {
          effInvestment: parsed.loyalty.weeklyInvestment ?? 0,
          // Migration for pre-maturity saves: an established member base gets
          // credit for half-built trust rather than resetting to zero.
          maturity: parsed.loyalty.maturity ?? ((parsed.loyalty.members ?? 0) > 0 ? 0.5 : 0),
          pointsLiability: parsed.loyalty.pointsLiability ?? 0,
          ...parsed.loyalty,
        }
      : { weeklyInvestment: 0, effInvestment: 0, members: 0, maturity: 0, pointsLiability: 0 },
    fuelPrice:        parsed.fuelPrice        ?? { index: 1.0, history: [] },
    // Added with the capital-markets rework; old saves start at neutral sentiment.
    marketIndex:      Number.isFinite(parsed.marketIndex) ? parsed.marketIndex : MARKET_BASE_INDEX,
    allianceMembership:       parsed.allianceMembership       ?? null,
    codeshareAgreements:      parsed.codeshareAgreements      ?? [],
    marketingBudget:          parsed.marketingBudget          ?? 0,
    targetedMarketing:        parsed.targetedMarketing        ?? {},
    campaignStrength:         parsed.campaignStrength         ?? {},
    defaultCateringLevel:     normalizeCateringLevel(parsed.defaultCateringLevel),
    ancillaries:              normalizeAncillaries(parsed.ancillaries),
    // Lounges — added with the ancillary facilities rework. Old saves have no
    // lounges and no policy, which is exactly the neutral state: appeal 1, no
    // day passes, full third-party premium ground contract.
    lounges:                  parsed.lounges                  ?? {},
    loungePolicy:             parsed.loungePolicy ? normalizeLoungePolicy(parsed.loungePolicy) : null,
    awareness:                parsed.awareness                ?? 5,
    // Labor relations (unrest / strikes / negotiations) — added later; old saves
    // start calm and get their first negotiations scheduled on the next tick.
    laborRelations:           parsed.laborRelations
      ? { ...DEFAULT_LABOR_RELATIONS, ...parsed.laborRelations,
          unrest: { ...DEFAULT_LABOR_RELATIONS.unrest, ...(parsed.laborRelations.unrest ?? {}) } }
      : DEFAULT_LABOR_RELATIONS,
    missedLoanPayments:       parsed.missedLoanPayments       ?? 0,
    consecutiveNegativeWeeks: parsed.consecutiveNegativeWeeks ?? 0,
    bankruptcyReason:         parsed.bankruptcyReason         ?? null,
    cabinTemplates:           parsed.cabinTemplates           ?? [],
    // Equity block — added with the capital-markets rework. Old saves are
    // incorporated at the founder share count, already public, no dividend history,
    // which reproduces their pre-rework share price exactly.
    // A save with no equity block predates the rework: it was already trading
    // against a fixed float, so it migrates as LISTED. A genuinely new airline
    // gets emptyEquity() (private) from freshState instead.
    equity:                   parsed.equity
      ? { ...migratedEquity(), ...parsed.equity }
      : migratedEquity(),
    svps:                     Number.isFinite(parsed.svps)
      ? parsed.svps
      : svpsOf({ sharePrice: parsed.sharePrice, equity: parsed.equity }),
    // Stock portfolio — added with the Markets feature; old saves start empty.
    portfolio:                parsed.portfolio
      ? { ...emptyPortfolio(), ...parsed.portfolio, holdings: { ...(parsed.portfolio.holdings ?? {}) } }
      : emptyPortfolio(),
    // Market cap — compute on load if missing (old saves)
    marketCap:   parsed.marketCap   ?? (() => {
      const ph = (parsed.financialHistory ?? []).slice(-12).map(h => h.profit);
      return computeMarketCap(ph, parsed.cash ?? 0, parsed.awareness ?? 5).marketCap;
    })(),
    sharePrice:  parsed.sharePrice  ?? (() => {
      const ph = (parsed.financialHistory ?? []).slice(-12).map(h => h.profit);
      return computeMarketCap(ph, parsed.cash ?? 0, parsed.awareness ?? 5).sharePrice;
    })(),
    // Unsmoothed fair value — added when private airlines stopped publishing it as
    // a price. Saves written before that start from their own published cap, which
    // for a private airline WAS the fair value, so nothing moves at the migration.
    fairValue:   Number.isFinite(parsed.fairValue) ? parsed.fairValue : (parsed.marketCap ?? null),
  };
  return applyScheduleTrimMigration(reconciled);
}